void *madc_runtime_eval_expression_string(void *result, void *expr)
{
    std::string &out = *(std::string *)result;
    std::string &expression = *(std::string *)expr;
    out.clear();

    std::unique_ptr<Program> owned;
    Program *active = require_runtime_eval_program(owned);
    if ( !active )
	return result;

    madc::value resolved;
    if ( !active->runtime_eval_expression(expression,
					  resolved,
					  "__madc_runtime_eval_expression") )
	return result;
    if ( !coerce_runtime_expression_string(*active, resolved, "madc::eval_expression_string", out) )
	return result;
    return result;
}

void *madc_runtime_eval_expression_string_ctx(void *result, void *expr, void *ctx)
{
    std::string &out = *(std::string *)result;
    std::string &expression = *(std::string *)expr;
    out.clear();

    std::unique_ptr<Program> owned;
    Program *active = require_runtime_eval_program(owned);
    if ( !active )
	return result;

    madc::value resolved;
    if ( !active->runtime_eval_expression(expression,
					  resolved,
					  "__madc_runtime_eval_expression",
					  runtime_eval_context(ctx)) )
	return result;
    if ( !coerce_runtime_expression_string(*active, resolved, "madc::eval_expression_string_ctx", out) )
	return result;
    return result;
}

// The __madc_eval_*_runtime / __madc_context_set_*_runtime extern-C
// exports and the namespace madc publics live in src/ns_madc.cpp; both
// delegate to the internals above. Only the compiler-machinery scope
// setters stay here (cpp-first-api.md: they are CIR-builder-emitted
// symbols, not user-resolved functions).

extern "C" {

// cstr-key scope setters — the CIR builder's TokenScopeContext lowering
// fills the captured-scope context array with these (a string literal key
// avoids materializing a std::string temp per captured variable).
void *__madc_scope_set_int_runtime(void *ctx, const char *key, int64_t value)
{
    DBG(std::cerr << "scope_set_int ctx=" << ctx << " " << key << "=" << value << std::endl);
    ns_common::value_object_for_write(*(madc::value *)ctx,
				      "__madc_scope_set_int")
	[std::string(key)] = madc::value(value);
    return ctx;
}

void *__madc_scope_set_real_runtime(void *ctx, const char *key, double value)
{
    ns_common::value_object_for_write(*(madc::value *)ctx,
				      "__madc_scope_set_real")
	[std::string(key)] = madc::value(value);
    return ctx;
}

void *__madc_scope_set_array_runtime(void *ctx, const char *key, void *value)
{
    ns_common::value_object_for_write(*(madc::value *)ctx,
				      "__madc_scope_set_array")
	[std::string(key)] = *(const madc::value *)value;
    return ctx;
}

// `str` is the captured local's address; the host reads the std::string
// by pointer and copies it into the context (read-only snapshot).
void *__madc_scope_set_string_runtime(void *ctx, const char *key, void *str)
{
    ns_common::value_object_for_write(*(madc::value *)ctx,
				      "__madc_scope_set_string")
	[std::string(key)] = madc::value(*(const std::string *)str);
    return ctx;
}

}

static bool is_restrict_token(TokenBase *tb)
{
    return tb && tb->type() == TokenType::ttKeyword && tb->id() == TokenID::tkRESTRICT;
}

static bool is_post_pointer_qualifier_token(TokenBase *tb)
{
    return tb && tb->type() == TokenType::ttKeyword
        && (tb->id() == TokenID::tkRESTRICT
	 || tb->id() == TokenID::tkCONST
	 || tb->id() == TokenID::tkVOLATILE);
}

// Shared declarator pointer-star consumer. See the header for the contract.
// Replaces the copy-pasted `while (tkMul) { ... if (!fnptr_base) getPointerType }`
// loops so the explicit `*` count is handled the SAME way everywhere.
int Program::consume_declarator_stars(DataDef *&dd, bool *out_const_after_star)
{
    int stars = 0;
    bool fnptr_base = (dynamic_cast<DataDefFPTR *>(dd) != NULL);
    bool const_after = false;
    while ( peekToken() && (peekToken()->id() == TokenID::tkMul
			 || is_post_pointer_qualifier_token(peekToken())) )
    {
	if ( peekToken()->id() == TokenID::tkMul )
	{
	    nextToken();		// consume '*'
	    ++stars;
	    const_after = false;	// any const before this star was low-level
	    if ( !fnptr_base )
		dd = getPointerType(dd);
	}
	else
	{
	    if ( stars > 0 && peekToken()->id() == TokenID::tkCONST )
		const_after = true;	// const after the last '*' = top-level const ptr
	    nextToken();		// consume const/volatile/restrict
	}
    }
    if ( out_const_after_star )
	*out_const_after_star = const_after;
    return stars;
}

static bool is_type_qualifier_token(TokenBase *tb)
{
    return tb && tb->type() == TokenType::ttKeyword
	&& (tb->id() == TokenID::tkCONST
	 || tb->id() == TokenID::tkRESTRICT
	 || tb->id() == TokenID::tkVOLATILE
	 || tb->id() == TokenID::tkSTATIC
	 || tb->id() == TokenID::tkEXTERN);
}

static bool is_attribute_identifier_token(TokenBase *tb)
{
    if ( !tb || tb->type() != TokenType::ttIdentifier )
	return false;
    const std::string &name = ((TokenIdent *)tb)->spelling();
    return name == "__attribute__" || name == "__attribute";
}

// Ignored C++ declaration-specifier keywords. constexpr/consteval/constinit
// carry no madc codegen (like const/inline) but ARE reserved tokens — so they
// must be consumed in declaration-specifier position rather than mistaken for
// a type name. constexpr is the only one currently reserved (tkCPPKEYWORD);
// consteval/constinit are listed for when slice 6 reserves them.
static bool is_ignored_cpp_specifier_token(TokenBase *tb)
{
    if ( !tb || tb->id() != TokenID::tkCPPKEYWORD )
	return false;
    const std::string &s = ((TokenIdent *)tb)->spelling();
    return s == "constexpr" || s == "consteval" || s == "constinit";
}

TokenBase *Program::consume_gnu_attributes(TokenBase *nt,
					 std::set<std::string> *attrs,
					 std::string *alias_target,
					 size_t *explicit_align,
					 size_t *vector_bytes)
{
    while ( nt && is_attribute_identifier_token(nt) )
    {
	if ( peekToken() && peekToken()->id() == TokenID::tkOpBrk )
	{
	    int adepth = 0;
	    bool saw_alias = false;
	    bool saw_aligned = false;
	    bool saw_vector_size = false;
	    bool saw_optimize = false;
	    do {
		TokenBase *at = nextToken();
		if ( !at ) break;
		if ( attrs && adepth >= 2 && at->type() == TokenType::ttIdentifier )
		    attrs->insert(((TokenIdent *)at)->spelling());
		if ( at->type() == TokenType::ttIdentifier
		  && (((TokenIdent *)at)->spelling_is("optimize")
		   || ((TokenIdent *)at)->spelling_is("__optimize__")) )
		    saw_optimize = true;
		else if ( saw_optimize && at->type() == TokenType::ttString )
		{
		    if ( std::string(((TokenStr *)at)->str).find("no-strict-aliasing") != std::string::npos )
			pending_no_strict_aliasing = true;
		    saw_optimize = false;
		}
		if ( at->type() == TokenType::ttIdentifier
		  && ((TokenIdent *)at)->spelling_is("alias") )
		    saw_alias = true;
		else if ( alias_target && saw_alias && at->type() == TokenType::ttString )
		{
		    *alias_target = ((TokenStr *)at)->str;
		    saw_alias = false;
		}
		else if ( at->type() == TokenType::ttIdentifier
		  && (((TokenIdent *)at)->spelling_is("aligned")
		   || ((TokenIdent *)at)->spelling_is("__aligned__")) )
		    saw_aligned = true;
		else if ( explicit_align && saw_aligned && at->type() == TokenType::ttInteger )
		{
		    int64_t aval = static_cast<TokenInt *>(at)->ival();
		    if ( aval > 0 )
			*explicit_align = static_cast<size_t>(aval);
		    saw_aligned = false;
		}
		else if ( at->type() == TokenType::ttIdentifier
		  && (((TokenIdent *)at)->spelling_is("vector_size")
		   || ((TokenIdent *)at)->spelling_is("__vector_size__")) )
		    saw_vector_size = true;
		else if ( saw_vector_size && at->id() == TokenID::tkOpBrk )
		{
		    int64_t n = parse_constant_integer_expression();
		    if ( vector_bytes && n > 0 )
			*vector_bytes = (size_t)n;
		    TokenBase *cl = nextToken();
		    if ( cl && cl->id() == TokenID::tkClBrk )
			; // consumed vector_size(...) argument paren
		    else if ( cl )
			pushToken(cl);
		    saw_vector_size = false;
		    continue; // don't do depth tracking for this paren pair
		}
		if ( at->id() == TokenID::tkOpBrk ) ++adepth;
		else if ( at->id() == TokenID::tkClBrk ) --adepth;
	    } while ( adepth > 0 );
	}
	nt = nextToken();
    }
    return nt;
}

static bool is_gnu_asm_identifier_token(TokenBase *tb)
{
    TokenIdent *ident = dynamic_cast<TokenIdent *>(tb);
    if ( !ident )
	return false;
    std::string name = ident->spelling();
    return name == "asm" || name == "__asm" || name == "__asm__";
}

TokenBase *Program::consume_gnu_asm_label(TokenBase *nt,
					std::string *alias_target)
{
    while ( nt && is_gnu_asm_identifier_token(nt) )
    {
	TokenBase *open = nextToken();
	if ( !open || open->id() != TokenID::tkOpBrk )
	    Throw(open ? open : nt) << "Expecting '(' after asm label" << flush;
	TokenBase *label = nextToken();
	if ( alias_target && label && label->type() == TokenType::ttString )
	    *alias_target = ((TokenStr *)label)->str;
	TokenBase *close = nextToken();
	if ( !close || close->id() != TokenID::tkClBrk )
	    Throw(close ? close : label) << "Expecting ')' after asm label" << flush;
	nt = nextToken();
    }
    return nt;
}

// Skip (or lower the recognized copy shapes of) a GNU asm STATEMENT.
// `tb` is the asm introducer; shared by the ttIdentifier and ttKeyword
// arms of parseStatement so reserving `asm` as a keyword keeps the skip.
TokenBase *Program::skip_gnu_asm_statement(TokenBase *tb)
{
	    // optional volatile qualifier
	    if ( peekToken()
	      && peekToken()->type() == TokenType::ttKeyword
	      && peekToken()->id() == TokenID::tkVOLATILE )
		nextToken();
	    else if ( peekToken() && peekToken()->type() == TokenType::ttIdentifier )
	    {
		std::string q = ((TokenIdent *)peekToken())->spelling();
		if ( q == "volatile" || q == "__volatile__" )
		    nextToken();
	    }
	    TokenBase *ob = nextToken();
	    if ( ob && ob->id() == TokenID::tkOpBrk )
	    {
		TokenBase *tmpl = nextToken();
		bool parsed_simple_copy = false;
		if ( tmpl && tmpl->type() == TokenType::ttString
		  && ((TokenStr *)tmpl)->spelling_empty()
		  && peekToken() && peekToken()->id() == TokenID::tkColon )
		{
		    nextToken(); // ':'
		    TokenBase *out_c = nextToken();
		    TokenBase *out_ob = nextToken();
		    if ( out_c && out_c->type() == TokenType::ttString
		      && out_ob && out_ob->id() == TokenID::tkOpBrk )
		    {
			std::string out_constraint = ((TokenStr *)out_c)->str;
			if ( out_constraint == "+m" )
			{
			    int out_depth = 1;
			    while ( out_depth > 0 )
			    {
				TokenBase *t = nextToken();
				if ( !t ) break;
				if ( t->id() == TokenID::tkOpBrk ) ++out_depth;
				else if ( t->id() == TokenID::tkClBrk ) --out_depth;
			    }
			    int asm_depth = 1;
			    while ( asm_depth > 0 )
			    {
				TokenBase *t = nextToken();
				if ( !t ) break;
				if ( t->id() == TokenID::tkOpBrk ) ++asm_depth;
				else if ( t->id() == TokenID::tkClBrk ) --asm_depth;
			    }
			    if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
				return nextToken();
			    return tb;
			}
			TokenBase *out_tb = nextToken();
			TokenBase *out_expr = out_tb ? parseExpression(out_tb, true) : NULL;
			TokenBase *out_cb = nextToken();
			TokenBase *next_clause = nextToken();
			if ( out_expr
			  && out_cb && out_cb->id() == TokenID::tkClBrk
			  && next_clause && next_clause->id() == TokenID::tkClBrk )
			{
			    if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
				nextToken();
			    if ( out_constraint == "+r" )
				return out_expr;
			    return tb;
			}
			if ( out_expr
			  && out_cb && out_cb->id() == TokenID::tkClBrk
			  && next_clause && next_clause->id() == TokenID::tkSemi )
			{
			    if ( out_constraint == "+r" )
				return out_expr;
			    return next_clause;
			}
			TokenBase *in_c = nextToken();
			TokenBase *in_ob = nextToken();
			if ( out_expr
			  && out_cb && out_cb->id() == TokenID::tkClBrk
			  && next_clause && next_clause->id() == TokenID::tkColon
			  && in_c && in_c->type() == TokenType::ttString
			  && in_ob && in_ob->id() == TokenID::tkOpBrk )
			{
			    TokenBase *in_tb = nextToken();
			    TokenBase *in_expr = in_tb ? parseExpression(in_tb, true) : NULL;
			    TokenBase *in_cb = nextToken();
			    TokenBase *close = nextToken();
			    std::string in_constraint = ((TokenStr *)in_c)->str;
			    // If close is ':' (clobber list), consume
			    // remaining tokens up to outer ')'.
			    if ( close && close->id() == TokenID::tkColon )
			    {
				int rem = 1;
				while ( rem > 0 )
				{
				    TokenBase *t = nextToken();
				    if ( !t ) break;
				    if ( t->id() == TokenID::tkOpBrk ) ++rem;
				    else if ( t->id() == TokenID::tkClBrk ) --rem;
				}
				close = new TokenClBrk();
			    }
			    if ( in_expr
			      && in_cb && in_cb->id() == TokenID::tkClBrk
			      && close && close->id() == TokenID::tkClBrk
			      && out_constraint == "=r"
			      && in_constraint == "0" )
			    {
				TokenAssign *assign = new TokenAssign();
				assign->file = tb->file;
				assign->line = tb->line;
				assign->column = tb->column;
				assign->left = out_expr;
				assign->right = in_expr;
				if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
				    nextToken();
				return assign;
			    }
			    if ( in_expr
			      && in_cb && in_cb->id() == TokenID::tkClBrk
			      && close && close->id() == TokenID::tkClBrk
			      && out_constraint == "=m"
			      && in_constraint == "m" )
			    {
				if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
				    return nextToken();
				return tb;
			    }
			    // Unrecognized two-operand asm pattern — consume
			    // any remaining tokens until the outer asm ')' is
			    // found, then return as no-op. We track paren
			    // depth starting from `close` (which may be `,`,
			    // `:`, or a paren itself).
			    {
				int rem = 1; // 1 for the outer '(' consumed at asm entry
				if ( close && close->id() == TokenID::tkOpBrk ) ++rem;
				else if ( close && close->id() == TokenID::tkClBrk ) --rem;
				while ( rem > 0 )
				{
				    TokenBase *t = nextToken();
				    if ( !t ) break;
				    if ( t->id() == TokenID::tkOpBrk ) ++rem;
				    else if ( t->id() == TokenID::tkClBrk ) --rem;
				}
				parsed_simple_copy = true;
				if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
				    return nextToken();
				return tb;
			    }
			}
			// Unrecognized asm pattern — the output operand
			// was consumed but the remaining clauses don't match
			// a known shape. Consume any remaining tokens until
			// the outer asm ')' is balanced. The outer '(' was
			// consumed at asm entry; out_ob/out_cb cancel; so we
			// need 1 more ')' to close, adjusted by any parens
			// in in_c and in_ob.
			{
			    int rem = 1; // for the outer '('
			    if ( in_c && in_c->id() == TokenID::tkOpBrk ) ++rem;
			    else if ( in_c && in_c->id() == TokenID::tkClBrk ) --rem;
			    if ( in_ob && in_ob->id() == TokenID::tkOpBrk ) ++rem;
			    else if ( in_ob && in_ob->id() == TokenID::tkClBrk ) --rem;
			    while ( rem > 0 )
			    {
				TokenBase *t = nextToken();
				if ( !t ) break;
				if ( t->id() == TokenID::tkOpBrk ) ++rem;
				else if ( t->id() == TokenID::tkClBrk ) --rem;
			    }
			    parsed_simple_copy = true;
			    if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
				return nextToken();
			    return tb;
			}
		    }
		}
		if ( !parsed_simple_copy )
		{
		    int depth = 1;
		    while ( depth > 0 )
		    {
			TokenBase *t = nextToken();
			if ( !t ) break;
			if ( t->id() == TokenID::tkOpBrk ) ++depth;
			else if ( t->id() == TokenID::tkClBrk ) --depth;
		    }
		}
	    }
	    // Return the semicolon as the statement (no-op).
	    // If the asm is the body of `if (...) asm(...);`, the
	    // caller needs a non-NULL return.
	    if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
		return nextToken();
	    return tb;
}

// Skip C23 [[...]] attributes: [[gnu::noipa]], [[nodiscard]], etc.
// Returns the next meaningful token after any [[...]] sequences.
void Program::skip_c23_attributes()
{
    while ( peekToken()
	 && peekToken()->id() == TokenID::tkOpSqr )
    {
	// peek ahead: is the NEXT token also [ ?
	TokenBase *first_sq = nextToken(); // consume first [
	if ( !peekToken()
	  || peekToken()->id() != TokenID::tkOpSqr )
	{
	    pushToken(first_sq); // not [[, push back
	    return;
	}
	nextToken(); // consume second [
	// Skip until ]]
	int depth = 1;
	while ( depth > 0 )
	{
	    TokenBase *t = nextToken();
	    if ( !t )
		break;
	    if ( t->id() == TokenID::tkOpSqr )
	    {
		if ( peekToken()
		  && peekToken()->id() == TokenID::tkOpSqr )
		{
		    nextToken();
		    ++depth;
		}
	    }
	    else if ( t->id() == TokenID::tkClSqr )
	    {
		if ( peekToken()
		  && peekToken()->id() == TokenID::tkClSqr )
		{
		    nextToken();
		    --depth;
		}
	    }
	}
    }
}

size_t Program::parse_gnu_vector_size_attribute()
{
    if ( !is_attribute_identifier_token(peekToken()) )
	return 0;
    nextToken(); // consume __attribute__
    if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	return 0;
    int depth = 0;
    bool saw_vector_size = false;
    size_t vector_bytes = 0;
    do {
	TokenBase *at = nextToken();
	if ( !at ) break;
	if ( saw_vector_size && at->id() == TokenID::tkOpBrk )
	{
	    int64_t n = parse_constant_integer_expression();
	    if ( n > 0 )
		vector_bytes = (size_t)n;
	    TokenBase *cl = nextToken();
	    if ( !cl || cl->id() != TokenID::tkClBrk )
		Throw(cl ? cl : at) << "Expected ')' after vector_size argument" << flush;
	    saw_vector_size = false;
	}
	else if ( at->id() == TokenID::tkOpBrk ) ++depth;
	else if ( at->id() == TokenID::tkClBrk ) --depth;
	else if ( at->type() == TokenType::ttIdentifier
	       && (((TokenIdent *)at)->spelling_is("vector_size")
		|| ((TokenIdent *)at)->spelling_is("__vector_size__")) )
	    saw_vector_size = true;
	else if ( saw_vector_size && at->type() == TokenType::ttInteger )
	{
	    int64_t n = at->ival();
	    if ( n > 0 )
		vector_bytes = (size_t)n;
	}
    } while ( depth > 0 );
    return vector_bytes;
}

void Program::consume_typedef_gnu_attributes(std::string *mode_name,
					   size_t *vector_bytes)
{
    while ( is_attribute_identifier_token(peekToken()) )
    {
	nextToken(); // consume __attribute__
	if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	    continue;
	int depth = 0;
	bool saw_mode = false;
	bool saw_vector_size = false;
	do {
	    TokenBase *at = nextToken();
	    if ( !at ) break;
	    if ( saw_vector_size && at->id() == TokenID::tkOpBrk )
	    {
		int64_t n = parse_constant_integer_expression();
		if ( vector_bytes && n > 0 )
		    *vector_bytes = (size_t)n;
		TokenBase *cl = nextToken();
		if ( !cl || cl->id() != TokenID::tkClBrk )
		    Throw(cl ? cl : at) << "Expected ')' after vector_size argument" << flush;
		saw_vector_size = false;
	    }
	    else if ( at->id() == TokenID::tkOpBrk )
		++depth;
	    else if ( at->id() == TokenID::tkClBrk )
		--depth;
	    else if ( at->type() == TokenType::ttIdentifier
		   && ((TokenIdent *)at)->spelling_is("mode") )
		saw_mode = true;
	    else if ( at->type() == TokenType::ttIdentifier
		   && (((TokenIdent *)at)->spelling_is("vector_size")
		    || ((TokenIdent *)at)->spelling_is("__vector_size__")) )
		saw_vector_size = true;
	    else if ( mode_name && saw_mode && at->type() == TokenType::ttIdentifier )
	    {
		*mode_name = ((TokenIdent *)at)->spelling();
		saw_mode = false;
	    }
	    else if ( vector_bytes && saw_vector_size && at->type() == TokenType::ttInteger )
	    {
		int64_t n = at->ival();
		if ( n > 0 )
		    *vector_bytes = (size_t)n;
		saw_vector_size = false;
	    }
	} while ( depth > 0 );
    }
}

static DataDef *apply_gnu_mode_alias(DataDef *base_dd, const std::string &mode_name)
{
    if ( !base_dd || mode_name.empty() )
	return base_dd;

    bool is_unsigned = false;
    switch ( base_dd->rawtype() )
    {
	case DataType::dtUINT8:
	case DataType::dtUINT16:
	case DataType::dtUINT24:
	case DataType::dtUINT32:
	case DataType::dtUINT64:
	    is_unsigned = true;
	    break;
	default:
	    break;
    }

    if ( mode_name == "QI" )
	return is_unsigned ? static_cast<DataDef *>(&ddUINT8) : static_cast<DataDef *>(&ddINT8);
    if ( mode_name == "HI" )
	return is_unsigned ? static_cast<DataDef *>(&ddUINT16) : static_cast<DataDef *>(&ddINT16);
    if ( mode_name == "SI" )
	return is_unsigned ? static_cast<DataDef *>(&ddUINT32) : static_cast<DataDef *>(&ddINT32);
    if ( mode_name == "DI" )
	return is_unsigned ? static_cast<DataDef *>(&ddUINT64) : static_cast<DataDef *>(&ddINT64);

    return base_dd;
}

static bool host_is_little_endian()
{
#if defined(__BYTE_ORDER__) && defined(__ORDER_LITTLE_ENDIAN__)
    return __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__;
#else
    const uint16_t probe = 0x0100;
    return *((const uint8_t *)&probe) == 0;
#endif
}

static bool reverse_scalar_storage_requested(const std::string &order_name)
{
    if ( order_name == "big-endian" )
	return host_is_little_endian();
    if ( order_name == "little-endian" )
	return !host_is_little_endian();
    return false;
}

static bool is_contextual_identifier_token(TokenBase *tb);
static std::string contextual_identifier_name(TokenBase *tb);
static bool token_origin_allows_c89_implicit_function(TokenBase *tb)
{
    if ( !tb || !tb->file )
	return false;
    std::string path(tb->file);
    return path.size() >= 2 && path.substr(path.size() - 2) == ".c";
}

static bool is_typeof_identifier(const std::string &name)
{
    return name == "typeof" || name == "typeof_unqual"
	|| name == "__typeof" || name == "__typeof__";
}

static bool is_decltype_identifier(const std::string &name)
{
    return name == "decltype";
}

static bool is_alignof_identifier(const std::string &name)
{
    return name == "alignof" || name == "_Alignof" || name == "__alignof__";
}

static bool is_static_assert_identifier(const std::string &name)
{
    return name == "_Static_assert" || name == "static_assert";
}

static bool is_nullptr_identifier(const std::string &name)
{
    return name == "nullptr";
}

static bool is_bool_literal_identifier(const std::string &name, bool &value)
{
    if ( name == "true" )
    {
	value = true;
	return true;
    }
    if ( name == "false" )
    {
	value = false;
	return true;
    }
    return false;
}

DataDef *Program::effective_pointer_type_for_member_access(TokenBase *tb)
{
    if ( !tb )
	return NULL;

    DataDef *dd = tb->datadef();
    if ( dd && dd->is_pointer() )
	return dd;
    if ( DataDefCArray *add = dynamic_cast<DataDefCArray *>(dd) )
    {
	DataDef *elem = add->element_type ? add->element_type : &ddINT64;
	return getPointerType(elem);
    }

    if ( TokenVar *tv = dynamic_cast<TokenVar *>(tb) )
    {
	if ( tv->var.is_fixed_array() && tv->var.type )
	    return getPointerType(tv->var.type);
    }

    if ( TokenMember *tm = dynamic_cast<TokenMember *>(tb) )
    {
	if ( tm->is_fixed_array_member() && tm->var.type )
	    return getPointerType(tm->var.type);
    }

    if ( TokenOperator *op = dynamic_cast<TokenOperator *>(tb) )
    {
	if ( op->id() == TokenID::tkAdd || op->id() == TokenID::tkSub )
	{
	    DataDef *lptr = effective_pointer_type_for_member_access(op->left);
	    if ( lptr )
		return lptr;
	    return effective_pointer_type_for_member_access(op->right);
	}
    }

    return NULL;
}

static uint32_t member_proxy_flags(uint32_t owner_flags)
{
    return owner_flags & ~vfFIXEDARRAY;
}

static DataDef *deref_type_for_variable(Variable *var)
{
    if ( !var || !var->type )
	return NULL;

    if ( var->is_fixed_array() )
	return var->type;

    if ( var->type->is_pointer() )
    {
	DataDefPTR *dptr = dynamic_cast<DataDefPTR *>(var->type);
	return (dptr && dptr->base_type) ? dptr->base_type : &ddINT64;
    }

    return NULL;
}

TokenBase *Program::skip_expression_whitespace()
{
    while ( peekToken()
	&& (peekToken()->type() == TokenType::ttSpace
	  || peekToken()->type() == TokenType::ttTab
	  || peekToken()->type() == TokenType::ttEOL) )
	nextToken();
    return peekToken();
}

static bool is_realpart_identifier(const std::string &name)
{
    return name == "__real" || name == "__real__";
}

static bool is_imagpart_identifier(const std::string &name)
{
    return name == "__imag" || name == "__imag__";
}

static TokenBase *make_complex_component_token(TokenBase *expr, bool imag_part)
{
    return new TokenComplexPart(expr, imag_part);
}

static std::string make_nested_function_name(TokenCpnd *scope,
					     const std::string &local_name)
{
    static size_t nested_counter = 0;
    std::string owner = "nested";
    if ( scope && scope->method )
	owner = scope->method->returns.name;
    return owner + "__" + local_name + "__" + std::to_string(++nested_counter);
}

static std::string namespace_function_symbol(const std::string &ns_name,
					     const std::string &member_name)
{
    std::string sym = "__ns_";
    for ( size_t i = 0; i < ns_name.size(); ++i )
    {
	char c = ns_name[i];
	sym += (isalnum((unsigned char)c) || c == '_') ? c : '_';
    }
    sym += "_";
    if ( member_name.compare(0, 8, "operator") == 0 )
    {
	sym += "operator";
	std::string op = member_name.substr(8);
	for ( size_t i = 0; i < op.size(); ++i )
	{
	    char c = op[i];
	    switch ( c )
	    {
	    case '<': sym += "_lt"; break;
	    case '>': sym += "_gt"; break;
	    case '+': sym += "_pl"; break;
	    case '-': sym += "_mi"; break;
	    case '*': sym += "_ml"; break;
	    case '/': sym += "_dv"; break;
	    case '%': sym += "_rm"; break;
	    case '=': sym += "_as"; break;
	    case '&': sym += "_ad"; break;
	    case '|': sym += "_or"; break;
	    case '^': sym += "_eo"; break;
	    case '!': sym += "_nt"; break;
	    case '[': sym += "_ix"; break;
	    case ']': break;
	    case '(': sym += "_cl"; break;
	    case ')': break;
	    default:  sym += (isalnum((unsigned char)c) || c == '_') ? c : '_'; break;
	    }
	}
    }
    else
    {
	for ( size_t i = 0; i < member_name.size(); ++i )
	{
	    char c = member_name[i];
	    sym += (isalnum((unsigned char)c) || c == '_') ? c : '_';
	}
    }
    return sym;
}

static std::vector<std::string> namespace_qualifiers(const std::string &ns_name)
{
    std::vector<std::string> out;
    size_t start = 0;
    while ( start < ns_name.size() )
    {
	size_t sep = ns_name.find("::", start);
	std::string part = sep == std::string::npos
			 ? ns_name.substr(start)
			 : ns_name.substr(start, sep - start);
	if ( !part.empty() )
	    out.push_back(part);
	if ( sep == std::string::npos )
	    break;
	start = sep + 2;
    }
    return out;
}

static std::string cpp_spelling_for_mangle(DataDef *dd, bool as_ref)
{
    if ( !dd )
	return "";
    if ( as_ref )
    {
	DataDefPTR *ptr = dynamic_cast<DataDefPTR *>(dd);
	DataDef *base = ptr && ptr->base_type ? ptr->base_type : dd;
	std::string s = base->canonical_cpp_spelling.empty()
		      ? base->name : base->canonical_cpp_spelling;
	return s + "&";
    }
    return dd->canonical_cpp_spelling.empty() ? dd->name : dd->canonical_cpp_spelling;
}

static std::string namespace_cpp_function_symbol(const std::string &ns_name,
						 const std::string &member_name,
						 FuncDef *fd)
{
    std::vector<std::string> params;
    if ( fd )
    {
	for ( size_t i = 0; i < fd->parameters.size(); ++i )
	{
	    if ( fd->is_varargs && i + 1 == fd->parameters.size() )
		break;
	    std::string spelling;
	    if ( i < fd->param_cpp_spellings.size() )
		spelling = fd->param_cpp_spellings[i];
	    if ( spelling.empty() )
	    {
		bool refp = fd->is_ref_param(i);
		spelling = cpp_spelling_for_mangle(fd->parameters[i], refp);
	    }
	    params.push_back(spelling);
	}
    }
    return itanium_mangle_nested_sub(namespace_qualifiers(ns_name),
				     member_name, params);
}

static std::string namespace_cpp_variable_symbol(const std::string &ns_name,
						 const std::string &member_name)
{
    return itanium_mangle_nested_var(namespace_qualifiers(ns_name),
				    member_name);
}

static DataDef *unwrap_subscript_element_type(DataDef *base_type)
{
    if ( !base_type )
	return &ddINT64;
    if ( DataDefPTR *pdd = dynamic_cast<DataDefPTR *>(base_type) )
	return pdd->base_type ? pdd->base_type : &ddINT64;
    if ( DataDefCArray *add = dynamic_cast<DataDefCArray *>(base_type) )
	return add->element_type ? add->element_type : &ddINT64;
    return base_type;
}

static DataDef *build_fixed_array_query_type(DataDef *base_type,
					     const std::vector<carray_dim_t> &dims,
					     size_t consumed_dims)
{
    if ( !base_type )
	return &ddINT64;
    if ( consumed_dims >= dims.size() )
	return base_type;

    DataDef *result = base_type;
    for ( size_t i = dims.size(); i-- > consumed_dims; )
	result = new DataDefCArray(*result, result->name, dims[i], NULL);
    return result;
}

static DataDef *type_query_chain_datadef(TokenBase *chain)
{
    if ( !chain )
	return NULL;
    if ( TokenSubscript *ts = dynamic_cast<TokenSubscript *>(chain) )
    {
	if ( ts->object.is_fixed_array() )
	    return build_fixed_array_query_type(ts->object.type, ts->object.dims,
						1 + ts->extra_indices.size());
    }
    if ( TokenSubscriptExpr *tse = dynamic_cast<TokenSubscriptExpr *>(chain) )
    {
	if ( TokenVar *tv = dynamic_cast<TokenVar *>(tse->base_expr) )
	    if ( tv->var.is_fixed_array() )
		return build_fixed_array_query_type(tv->var.type, tv->var.dims, 1);
    }
    return chain->datadef();
}

DataDef *Program::resolve_named_datadef(const std::string &name)
{
    datadef_map_iter dmi = struct_map.find(name);
    if ( dmi != struct_map.end() )
	return dmi->second;

    flat_datatype_map_iter bmi = datatype_map.find(name);
    if ( bmi != datatype_map.end() )
	return &(*bmi)->definition;

    if ( name == "void" ) return &ddVOID;
    if ( name == "bool" || name == "_Bool" ) return &ddBOOL;
    if ( name == "char" ) return &ddCHAR;
    if ( name == "signed char" ) return &ddINT8;
    if ( name == "unsigned char" ) return &ddUINT8;
    if ( name == "short" || name == "short int"
      || name == "signed short" || name == "signed short int" )
	return &ddINT16;
    if ( name == "unsigned short" || name == "unsigned short int" )
	return &ddUINT16;
    if ( name == "int" || name == "signed" || name == "signed int" )
	return &ddINT32;
    if ( name == "unsigned" || name == "unsigned int" )
	return &ddUINT32;
    if ( name == "long" || name == "long int"
      || name == "signed long" || name == "signed long int"
      || name == "long long" || name == "long long int"
      || name == "signed long long" || name == "signed long long int"
      || name == "__int128" || name == "signed __int128" )
	return &ddINT64;
    if ( name == "unsigned long" || name == "unsigned long int"
      || name == "unsigned long long" || name == "unsigned long long int"
      || name == "unsigned __int128" )
	return &ddUINT64;
    if ( name == "float" || name == "_Float32" ) return &ddFLOAT;
    if ( name == "double" || name == "long double"
      || name == "_Float64" || name == "_Float128"
      || name == "_Float32x" || name == "_Float64x" )
	return &ddDOUBLE;
    if ( name == "int8_t" ) return &ddINT8;
    if ( name == "int16_t" ) return &ddINT16;
    if ( name == "int32_t" ) return &ddINT32;
    if ( name == "int64_t" ) return &ddINT64;
    if ( name == "uint8_t" ) return &ddUINT8;
    if ( name == "uint16_t" ) return &ddUINT16;
    if ( name == "uint32_t" ) return &ddUINT32;
    if ( name == "uint64_t" ) return &ddUINT64;
    if ( name == "size_t" ) return &ddUINT64;
    if ( name == "ptrdiff_t" ) return &ddINT64;
    if ( name == "wchar_t" ) return &ddINT32;
    if ( name == "char16_t" ) return &ddUINT16;
    if ( name == "char32_t" ) return &ddUINT32;
    if ( name == "max_align_t" ) return &ddMAX_ALIGN_T;
    if ( name == "LPSTR" ) return &ddLPSTR;
    if ( name == "array" ) return &ddARRAY;
    if ( name == "auto" ) return &ddAUTO;

    return lazy_resolve_type(name);
}

bool Program::typedef_alias_matches_datadef(const std::string &alias, DataDef *dd)
{
    if ( alias.empty() || !dd || !user_typedef_names.count(alias) )
	return false;
    return resolve_named_datadef(alias) == dd;
}

static DataDef *resolve_class_type_alias(DataDefCLASS *cls, const std::string &name)
{
    if ( !cls )
	return NULL;
    // The injected-class-name ([class.pre]/2): within class X, the name X refers
    // to X itself. A monomorphized class registers its SHORT injected name as a
    // type-alias, but its identity `name` is the FULL mangled spelling; resolve
    // that to the class too so a fully-qualified self-reference (e.g. a ctor
    // symbol `<full>__<full>`) is recognized as the class.
    if ( cls->name == name )
	return cls;
    std::map<std::string, DataDef *>::iterator ai = cls->type_aliases.find(name);
    if ( ai != cls->type_aliases.end() )
	return ai->second;
    for ( size_t i = 0; i < cls->bases.size(); ++i )
	if ( DataDef *bd = resolve_class_type_alias(cls->bases[i].base, name) )
	    return bd;
    if ( cls->base_class )
	return resolve_class_type_alias(cls->base_class, name);
    if ( cls->enclosing_class )
	return resolve_class_type_alias(cls->enclosing_class, name);
    return NULL;
}

// Class-scope `using <Base>::<member>;` ([namespace.udecl]): import the base
// class's <member> overload(s) into THIS class's overload set so they compete
// with the class's own same-name overloads (a using-declaration defeats name
// hiding). Real `__gnu_cxx::__alloc_traits` does `using _Base_type::construct;`
// to expose std::allocator_traits<_Alloc>::construct alongside its own
// custom-pointer construct overload — overload resolution + [temp.func.order]
// then pick the right one. Handles the single-name-scope, single-member shape;
// returns false (caller falls back to skipping the declaration) for any other
// shape or an unresolved/non-class base. Peeks pgm.tokens; consumes ONLY on a
// successful import (so unhandled forms reach the existing skip unchanged).
static bool try_import_using_base_member(Program &pgm, DataDefCLASS *ddc)
{
    if ( !ddc )
	return false;
    // tokens: [0]=using [1]=scope-name [2]=:: [3]=member [4]=;
    if ( pgm.tokens.size() < 5 )
	return false;
    TokenBase *scope_tb = pgm.tokens[1], *ns_tb = pgm.tokens[2];
    TokenBase *mem_tb = pgm.tokens[3], *semi_tb = pgm.tokens[4];
    if ( !scope_tb || !ns_tb || !mem_tb || !semi_tb )
	return false;
    if ( ns_tb->id() != TokenID::tkNS || semi_tb->id() != TokenID::tkSemi )
	return false;
    if ( !is_contextual_identifier_token(scope_tb)
      || !is_contextual_identifier_token(mem_tb) )
	return false;
    std::string scope_name = contextual_identifier_name(scope_tb);
    std::string member = contextual_identifier_name(mem_tb);
    if ( scope_name.empty() || member.empty() )
	return false;
    DataDefCLASS *base =
	dynamic_cast<DataDefCLASS *>(resolve_class_type_alias(ddc, scope_name));
    if ( !base )
	return false;
    bool imported = false;
    for ( size_t i = 0; i < base->methods.size(); ++i )
    {
	Variable *bm = base->methods[i];
	if ( !bm )
	    continue;
	FuncDef *fd = dynamic_cast<FuncDef *>(bm->type);
	if ( !fd )
	    continue;
	const std::string &disp = fd->method_display_name.empty()
				? bm->name : fd->method_display_name;
	if ( disp != member )
	    continue;
	bool present = false;
	for ( size_t j = 0; j < ddc->methods.size(); ++j )
	    if ( ddc->methods[j] == bm ) { present = true; break; }
	if ( present )
	    continue;
	ddc->methods.push_back(bm);
	if ( ddc->method_map.find(member) == ddc->method_map.end() )
	    ddc->method_map[member] = bm;
	imported = true;
    }
    if ( !imported )
	return false;
    pgm.nextToken(); pgm.nextToken(); pgm.nextToken();	// using scope ::
    pgm.nextToken(); pgm.nextToken();			// member ;
    return true;
}

static DataDef *resolve_class_static_member_type(DataDefCLASS *cls, const std::string &name)
{
    if ( !cls )
	return NULL;
    std::map<std::string, DataDef *>::iterator si = cls->static_member_types.find(name);
    if ( si != cls->static_member_types.end() )
	return si->second;
    for ( size_t i = 0; i < cls->bases.size(); ++i )
	if ( DataDef *bd = resolve_class_static_member_type(cls->bases[i].base, name) )
	    return bd;
    if ( cls->base_class )
	return resolve_class_static_member_type(cls->base_class, name);
    if ( cls->enclosing_class )
	return resolve_class_static_member_type(cls->enclosing_class, name);
    return NULL;
}

static bool peek_class_member_type_chain(DataDefCLASS *owner,
					 const TokenStream &tokens,
					 size_t start_index,
					 DataDef *&out,
					 size_t &consume_count,
					 std::string &leaf_name)
{
    out = NULL;
    consume_count = 0;
    leaf_name.clear();
    if ( !owner || start_index >= tokens.size()
      || !tokens[start_index]
      || tokens[start_index]->id() != TokenID::tkNS )
	return false;

    DataDefCLASS *scope = owner;
    size_t i = start_index;
    while ( i < tokens.size()
	 && tokens[i] && tokens[i]->id() == TokenID::tkNS )
    {
	size_t member_index = i + 1;
	if ( member_index >= tokens.size() || !tokens[member_index] )
	    return false;
	if ( tokens[member_index]->id() == TokenID::tkTEMPLATE )
	{
	    ++member_index;
	    if ( member_index >= tokens.size() || !tokens[member_index] )
		return false;
	}
	if ( !is_contextual_identifier_token(tokens[member_index]) )
	    return false;

	std::string member_name =
	    contextual_identifier_name(tokens[member_index]);
	DataDef *alias_dd = resolve_class_type_alias(scope, member_name);
	if ( !alias_dd )
	    return false;

	size_t next_index = member_index + 1;
	if ( next_index < tokens.size()
	  && tokens[next_index]
	  && tokens[next_index]->id() == TokenID::tkLT )
	    return false;

	consume_count = next_index - start_index;
	leaf_name = member_name;
	out = alias_dd;

	if ( next_index >= tokens.size()
	  || !tokens[next_index]
	  || tokens[next_index]->id() != TokenID::tkNS )
	    return true;

	scope = dynamic_cast<DataDefCLASS *>(alias_dd);
	if ( !scope )
	    return false;
	i = next_index;
    }
    return out != NULL;
}

// Constant value of an integral static-const data member (captured at parse), or
// false if `name` has no captured constant. Walks the base chain like the type
// resolver, so an inherited `static const … value` is found.
static bool resolve_class_static_member_const_value(DataDefCLASS *cls,
						    const std::string &name,
						    int64_t &out)
{
    if ( !cls )
	return false;
    std::map<std::string, int64_t>::iterator vi =
	cls->static_member_const_values.find(name);
    if ( vi != cls->static_member_const_values.end() )
    {
	out = vi->second;
	return true;
    }
    for ( size_t i = 0; i < cls->bases.size(); ++i )
	if ( resolve_class_static_member_const_value(cls->bases[i].base, name, out) )
	    return true;
    if ( cls->base_class )
	return resolve_class_static_member_const_value(cls->base_class, name, out);
    if ( cls->enclosing_class )
	return resolve_class_static_member_const_value(cls->enclosing_class, name, out);
    return false;
}

// get-or-create the placeholder DataDef for template parameter `name` at 0-based
// `index`. Pooled by (name, index) and owned by template_param_pool for the
// Program's lifetime (same never-freed convention as ptr_type_cache), so a Tree-1
// pattern that references it outlives the per-TU TemplateParamScope frame.
DataDefTemplateParam *Program::intern_template_param(const std::string &name,
						     unsigned index)
{
    for ( size_t i = 0; i < template_param_pool.size(); ++i )
	if ( template_param_pool[i]->param_index == index
	  && template_param_pool[i]->name == name )
	    return template_param_pool[i];
    DataDefTemplateParam *tp = new DataDefTemplateParam(name, index);
    template_param_pool.push_back(tp);
    return tp;
}

// resolve `name` to an active template-parameter placeholder (innermost frame
// first). Returns NULL — the common case — when no dependent-body frame is active,
// keeping the consult below O(1) on the non-template path.
DataDef *Program::resolve_template_param(const std::string &name)
{
    for ( std::vector<std::map<std::string, DataDef *> >::reverse_iterator it =
	      template_param_scopes.rbegin();
	  it != template_param_scopes.rend(); ++it )
    {
	std::map<std::string, DataDef *>::iterator mi = it->find(name);
	if ( mi != it->end() )
	    return mi->second;
    }
    return NULL;
}

DataDef *Program::resolve_current_class_type_alias(const std::string &name)
{
    // Two-tree Phase 2 / 2a: during a DEPENDENT template-body parse, the template's
    // own parameters (`T`) resolve to their placeholder FIRST, ahead of any class
    // scope. Inert (no active frame) in every other parse, so this is byte-identical
    // until 2a pushes a TemplateParamScope.
    if ( DataDef *tp = resolve_template_param(name) )
	return tp;
    // The CURRENT METHOD's owner class is the innermost class scope while its
    // body parses ([class.mfct]: member-function lookup reaches the class
    // scope before any enclosing/ambient one), so it must SHADOW the
    // class_scope_stack — which can hold unrelated classes when this parse
    // was triggered from inside another class's method (the dependent-pattern
    // parse of _Rb_tree::_M_insert_unique, triggered inside std::set::insert,
    // resolved `iterator` to std::set's instead of _Rb_tree's own). In a
    // normal in-class method parse the owner is also the stack's innermost
    // entry, so the reorder is a no-op there.
    if ( !compounds.empty() && compounds.top()
      && compounds.top()->method
      && compounds.top()->method->owner_class )
	if ( DataDef *dd =
		resolve_class_type_alias(compounds.top()->method->owner_class,
					 name) )
	    return dd;
    for ( std::vector<DataDefCLASS *>::reverse_iterator it =
	      class_scope_stack.rbegin();
	  it != class_scope_stack.rend(); ++it )
	if ( DataDef *dd = resolve_class_type_alias(*it, name) )
	    return dd;
    return NULL;
}

// Resolve an UNQUALIFIED identifier to the captured value of a static-const
// data member of a class currently being parsed (or a method's owner class).
// Lets an in-class constant initializer reference a sibling static-const
// member, e.g. `static const category all = (ctype | numeric);`.
bool Program::resolve_current_class_static_member_const_value(
	const std::string &name, int64_t &out)
{
    for ( std::vector<DataDefCLASS *>::reverse_iterator it =
	      class_scope_stack.rbegin();
	  it != class_scope_stack.rend(); ++it )
	if ( resolve_class_static_member_const_value(*it, name, out) )
	    return true;
    if ( !compounds.empty() && compounds.top()
      && compounds.top()->method
      && compounds.top()->method->owner_class )
	if ( resolve_class_static_member_const_value(
		 compounds.top()->method->owner_class, name, out) )
	    return true;
    return false;
}

Variable *Program::find_variable_for_contextual_type_name(const std::string &name)
{
    std::string lookup = name;
    Variable *var = findVariable(lookup);
    if ( var )
	return var;
    size_t sp = name.rfind(' ');
    if ( sp == std::string::npos || sp + 1 >= name.size() )
	return NULL;
    lookup = name.substr(sp + 1);
    return findVariable(lookup);
}

DataDefCLASS *Program::resolve_expression_class_scope(const std::string &name)
{
    DataDef *dd = resolve_current_class_type_alias(name);
    if ( !dd && !compounds.empty() && compounds.top()
      && compounds.top()->method && compounds.top()->method->owner_class )
	dd = resolve_class_type_alias(compounds.top()->method->owner_class, name);
    if ( !dd )
    {
	flat_datatype_map_iter dti = datatype_map.find(name);
	if ( dti != datatype_map.end() )
	    dd = &(*dti)->definition;
    }
    if ( !dd )
    {
	datadef_map_iter dmi = struct_map.find(name);
	if ( dmi != struct_map.end() )
	    dd = dmi->second;
    }
    if ( !dd )
	dd = lazy_resolve_type(name);
    return dynamic_cast<DataDefCLASS *>(dd);
}

static TokenDataType *make_alias_type_token(const std::string &name,
					    DataDef *dd, TokenBase *at)
{
    if ( !dd )
	return NULL;
    TokenDataType *tdt = new TokenDataType(name.c_str(), *dd);
    if ( at )
    {
	tdt->file = at->file;
	tdt->line = at->line;
	tdt->column = at->column;
    }
    return tdt;
}

TokenDataType *Program::resolve_namespaced_type_token(TokenBase *tb, bool consume_tokens)
{
    if ( !tb || tb->type() != TokenType::ttIdentifier || !peekToken() || peekToken()->id() != TokenID::tkNS )
	return NULL;

    // Scope-relative qualification: inside `namespace std`, `__cmp_cat::type`
    // names std::__cmp_cat::type (C++ searches the enclosing-namespace chain
    // before the global scope). resolve_namespace_name_in_scope falls back to
    // the absolute name itself, preserving the old absolute-only behavior.
    std::string ns_name = ((TokenIdent *)tb)->spelling();
    std::string resolved_ns = resolve_namespace_name_in_scope(ns_name);
    if ( !resolved_ns.empty() )
	ns_name = resolved_ns;

    // Extend through nested qualifiers (`a::b::member`): tokens[0] is the '::'
    // after tb; each ident+'::' pair deepens the namespace while the deeper
    // path names a known namespace. tokens[j] ends as the member candidate.
    size_t j = 1;
    while ( j + 1 < tokens.size()
	 && tokens[j] && is_contextual_identifier_token(tokens[j])
	 && tokens[j + 1] && tokens[j + 1]->id() == TokenID::tkNS )
    {
	std::string deeper = ns_name + "::"
			   + contextual_identifier_name(tokens[j]);
	if ( namespace_datatype_map.find(deeper) == namespace_datatype_map.end()
	  && namespace_map.find(deeper) == namespace_map.end() )
	    break;
	ns_name = deeper;
	j += 2;
    }

    namespace_datatype_map_t::iterator nti = namespace_datatype_map.find(ns_name);
    if ( nti == namespace_datatype_map.end() )
	return NULL;

    if ( j >= tokens.size() )
	return NULL;
    TokenBase *member_tb = tokens[j];
    if ( !member_tb )
	return NULL;
    std::string member_name;
    if ( member_tb->type() == TokenType::ttIdentifier )
	member_name = ((TokenIdent *)member_tb)->spelling();
    else if ( member_tb->type() == TokenType::ttDataType )
	member_name = ((TokenDataType *)member_tb)->spelling();
    else if ( is_contextual_identifier_token(member_tb) )
	member_name = contextual_identifier_name(member_tb);
    else
	return NULL;
    datatype_map_iter dti = nti->find(member_name);
    if ( dti == nti->end() )
	return NULL;

    if ( consume_tokens )
	for ( size_t k = 0; k <= j; ++k )
	    nextToken(); // each qualifier's '::' (+ ident) and the member
    return dti->second;
}

// Instantiate a captured template on use: `Name<ConcreteType>`. Clones the
// template's body tokens, substitutes the type parameter(s) with the concrete
// type token(s) and renames the class to a per-instantiation mangled name, then
// injects the synthesized `class Mangled { ... };` to the front of the parse
// deque and re-parses it via the existing class parser (which registers a normal
// DataDefCLASS). Returns a use-site TokenDataType for the instantiated class, or
// NULL if `tname` is not a template / the syntax doesn't match (caller falls
// through). Assumes `tb` (the template name) is already current; the next token
// must be '<'. See docs/plans/2026-05-30-template-instantiation.md.
static TokenDataType *use_site_type_token(TokenDataType *proto, TokenBase *at);
// Match `<`...`>` as a balanced delimiter pair, like `(`...`)` and `{`...`}`:
// each `<` opens one template level and is closed by exactly ONE `>`. The lexer,
// having no template context, emits `>>` as a single TokenBSR (right-shift), so a
// `>>` at a nested template-id close supplies the `>` for THIS level and leaves a
// `>` for the enclosing one (the C++11 rule). `tok` is the already-consumed
// candidate close token; on a `>`-class token this consumes the close (pushing
// back the leftover `>` for `>>`) and returns true, else returns false and
// consumes nothing extra. Applied at every template-angle close site.
// (The open side never needs splitting — `<<` cannot appear as two template
// opens in a well-formed template-id, since each level is introduced by a name.)
bool Program::consume_template_close(TokenBase *tok)
{
    if ( !tok )
	return false;
    if ( tok->id() == TokenID::tkGT )
	return true;                          // single '>'
    if ( tok->id() == TokenID::tkBSR )    // '>>' = this level's '>' + the outer one
    {
	pushToken(new TokenGT());
	return true;
    }
    return false;
}

// Operator-function-id helpers — shared by every <...> scanner so the operator
// symbol of `operator<` / `operator>>` / … is treated as part of a NAME, never
// as an angle-bracket delimiter. Free functions because some scanners walk a
// captured token vector and have no Program & in hand.
static bool token_is_operator_id_start(TokenBase *t)
{
    return t && is_contextual_identifier_token(t)
	&& contextual_identifier_name(t) == "operator";
}
// Number of tokens the operator-function-id at toks[i] spans (keyword + symbol
// [+ closing )/] for operator()/operator[]]), or 0 if toks[i] is not an
// operator-id start. For index-based scanners that walk a captured token
// sequence (templated so it serves both std::vector and the std::deque queue).
template<typename Seq>
static size_t operator_id_token_span(const Seq &toks, size_t i)
{
    if ( i >= toks.size() || !token_is_operator_id_start(toks[i]) )
	return 0;
    if ( i + 1 >= toks.size() )
	return 1;
    TokenBase *sym = toks[i + 1];
    if ( sym->type() == TokenType::ttString && i + 2 < toks.size()
      && is_contextual_identifier_token(toks[i + 2]) )
	return 3;   // user-defined literal: operator "" suffix
    if ( (sym->id() == TokenID::tkOpBrk || sym->id() == TokenID::tkOpSqr)
      && i + 2 < toks.size() )
	return 3;   // operator() / operator[]
    return 2;       // operator + single symbol token (<, <<, <=, >, >>, …)
}

// Balanced-delimiter depth for token scans: (), [], {}, <>. The hand-rolled
// "++paren … --angle … >>" if-else chain is copy-pasted across many scanners;
// this is the single shared bookkeeping (operator-ids consumed opaquely, never
// counted as a '<'). Callers layer their own logic (comma counts, terminators)
// on top using `top()` / the individual depths.
struct DelimDepth {
    int paren = 0, square = 0, brace = 0, angle = 0;
    std::vector<int> angle_paren;   // paren depth at each angle open
    TokenBase *prev = NULL;         // previous token seen by update()
    bool top() const { return !paren && !square && !brace && !angle; }
    // A `<` can only BEGIN a template-argument-list after a name (template-id
    // head: identifier / type name / the `template` keyword). After `)`, `]`,
    // a literal, etc. it is the less-than OPERATOR — real <type_traits> writes
    // `integral_constant<bool, _Tp(-1) < _Tp(0)>`, and counting that `<` as an
    // open desynced the scan by one level for the next ~1300 header lines.
    // NULL prev (scan starting mid-stream) keeps the legacy always-open rule.
    static bool angle_open_context(TokenBase *t)
    {
	if ( !t )
	    return true;
	if ( t->type() == TokenType::ttIdentifier
	  || t->type() == TokenType::ttDataType )
	    return true;
	return t->id() == TokenID::tkTEMPLATE;
    }
    // Pure delimiter bookkeeping for one token (NO operator-id handling — the
    // callers below own that, differing by index vs stream access).
    void update(TokenBase *t)
    {
	if ( !t )
	    return;
	switch ( t->id() )
	{
	    case TokenID::tkOpBrk: ++paren; break;
	    case TokenID::tkClBrk: if ( paren > 0 )  --paren;  break;
	    case TokenID::tkOpSqr: ++square; break;
	    case TokenID::tkClSqr: if ( square > 0 ) --square; break;
	    case TokenID::tkOpBrc: ++brace; break;
	    case TokenID::tkClBrc: if ( brace > 0 )  --brace;  break;
	    case TokenID::tkLT:
		if ( angle_open_context(prev) )
		{
		    ++angle;
		    angle_paren.push_back(paren);
		}
		break;
	    // An UNPARENTHESIZED `>` closes the argument list ([temp.names]):
	    // a `>` inside parens opened WITHIN the list (`A<(B > C)>`) is the
	    // greater-than operator, not a close.
	    case TokenID::tkGT:    close_angle(); break;
	    case TokenID::tkBSR:   close_angle(); close_angle(); break;
	    default: break;
	}
	prev = t;
    }
private:
    void close_angle()
    {
	if ( angle <= 0 )
	    return;
	if ( !angle_paren.empty() && paren > angle_paren.back() )
	    return;             // operator-> comparison inside parens
	--angle;
	if ( !angle_paren.empty() )
	    angle_paren.pop_back();
    }
};
// Index form: update `d` for the token sequence at toks[i]; returns the number
// of tokens consumed (1, or an operator-id's span). Templated for both
// std::vector and the std::deque token queue.
template<typename Seq>
static size_t delim_scan_step(const Seq &toks, size_t i, DelimDepth &d)
{
    if ( size_t n = operator_id_token_span(toks, i) )
	return n;
    d.update(toks[i]);
    return 1;
}

static std::string template_token_fragment(TokenBase *tb)
{
    if ( !tb )
	return "";
    if ( tb->type() == TokenType::ttIdentifier )
	return ((TokenIdent *)tb)->spelling();
    if ( tb->type() == TokenType::ttKeyword )
	return ((TokenKeyword *)tb)->spelling();
    if ( tb->type() == TokenType::ttDataType )
	return ((TokenDataType *)tb)->spelling();
    if ( tb->type() == TokenType::ttInteger )
    {
	TokenInt *ti = static_cast<TokenInt *>(tb);
	if ( !ti->source_text.empty() )
	    return ti->source_text;
	return std::to_string(ti->ival());
    }
    if ( tb->type() == TokenType::ttString )
	return ((TokenStr *)tb)->str;
    if ( TokenMultiOp *mo = dynamic_cast<TokenMultiOp *>(tb) )
	return mo->str;
    char c = (char)tb->get();
    return c ? std::string(1, c) : std::string("_");
}

static std::string template_type_arg_spelling(TokenDataType *adt,
					      const std::string &cv_spelling)
{
    if ( !adt )
	return cv_spelling;
    // These are distinct C++ template argument spellings even though madc maps
    // their storage to integer DataDefs internally. Keep the source spelling so
    // explicit specializations such as `char_traits<wchar_t>` are found.
    if ( adt->spelling_is("wchar_t") || adt->spelling_is("char16_t")
      || adt->spelling_is("char32_t") )
	return cv_spelling + adt->spelling();
    // A REFERENCE template argument (`tuple<const int&>`) must render with `&`,
    // NOT the ref-as-pointer `*` form. madc lowers references to pointers
    // (DataDefREF IS-A DataDefPTR), so a reference's name/canonical spelling is
    // the `*`-form — which is IDENTICAL to a real pointer's. Baking that into an
    // instantiation's canonical_cpp_spelling LOSES the reference identity: when
    // that spelling is later re-resolved during deduction
    // (split_template_id_spelling -> resolve_arg_spelling_datadef), `const int32_t*`
    // rebuilds a PLAIN POINTER, so the library's `_Head&` (std::get/__get_helper's
    // return, _Head = const int&) double-wraps to `const int**` -> c2mir "incompatible
    // return-expr type in function returning a pointer" -> undefined __ns_std_get
    // (map<int,int>'s `tuple<const key_type&>` get<0>). Render `referent&` so the
    // canonical spelling round-trips back to a DataDefREF, where getReferenceType's
    // reference collapsing ([dcl.ref]p6) then yields the single reference. The
    // referent keeps its own cv (`const int` -> `const int&`).
    if ( adt->definition.is_reference() )
	if ( DataDefPTR *r = dynamic_cast<DataDefPTR *>(&adt->definition) )
	    if ( r->base_type )
	    {
		const std::string &rs = r->base_type->canonical_cpp_spelling;
		return cv_spelling
		     + (rs.empty() ? r->base_type->name : rs) + "&";
	    }
    const std::string &cs = adt->definition.canonical_cpp_spelling;
    return cv_spelling + (cs.empty() ? adt->definition.name : cs);
}

static std::string sanitize_template_fragment(const std::string &s)
{
    std::string out;
    for ( size_t i = 0; i < s.size(); ++i )
    {
	unsigned char c = (unsigned char)s[i];
	out += (isalnum(c) || c == '_') ? (char)c : '_';
    }
    return out.empty() ? std::string("_") : out;
}

// The datatype_map / struct_map key HEAD for a template instantiation: the
// bare name unless the same name is declared in 2+ namespaces (std::char_traits
// vs __gnu_cxx::char_traits), where the defining namespace must disambiguate.
// Every registration AND lookup of an instantiated template must use this one
// rule — an explicit specialization registered under a differently-formed key
// is invisible to use sites, which then instantiate the primary instead.
static std::string template_instantiation_key_head(
	Program &pgm, const std::string &tname,
	const std::string &defining_namespace)
{
    std::vector<Program::TemplateDef> *g =
	pgm.template_map.find(tname);
    if ( g != pgm.template_map.end() && g->size() > 1
      && !defining_namespace.empty() )
	return sanitize_template_fragment(defining_namespace) + "__" + tname;
    return tname;
}

TokenBase *Program::collect_template_argument_spelling(TokenBase *first,
						     std::string &spelling,
						     std::vector<TokenBase *> *tokens_out)
{
    int angle_depth = 0;
    int paren_depth = 0;
    int square_depth = 0;
    TokenBase *t = first;
    while ( t )
    {
	if ( angle_depth == 0 && paren_depth == 0 && square_depth == 0
	  && (t->id() == TokenID::tkComma || t->id() == TokenID::tkGT
	   || t->id() == TokenID::tkBSR) )
	    return t;
	if ( t->id() == TokenID::tkBSR && angle_depth == 1 )
	{
	    spelling += ">";
	    if ( tokens_out )
		tokens_out->push_back(new TokenGT());
	    return new TokenGT();
	}
	// operator-function-id (`operator<`, `operator>>`, `operator()`, …):
	// the operator symbol is part of a NAME, never an angle/paren/bracket
	// delimiter. Consume `operator` + its symbol token(s) via the shared
	// primitive without touching any depth counter.
	if ( isOperatorIdStart(t) )
	{
	    std::vector<TokenBase *> opsyms;
	    std::string opname = parseOperatorId(t, tokens_out ? &opsyms : NULL);
	    spelling += opname;
	    if ( tokens_out )
	    {
		tokens_out->push_back(t->clone());
		for ( TokenBase *s : opsyms )
		    tokens_out->push_back(s->clone());
	    }
	    t = nextToken();
	    continue;
	}
	{
	    // Separate two adjacent WORD fragments (`const`+`int`, `unsigned`+`long`)
	    // with a space so a multi-word type argument spells `const int&`, not the
	    // unparseable `constint&`. Without it the canonical_cpp_spelling of an
	    // opaque/variadic instantiation (e.g. `tuple<const int&>`, a pack template)
	    // does NOT round-trip through resolve_arg_spelling_datadef — `const ` can't
	    // be peeled off `constint`, so partial-spec deduction of the element type
	    // fails and the spec is wrongly rejected for the primary (map<int,int>'s
	    // `tuple_element<0, tuple<const int&>>::type`). Only inserted between two
	    // identifier/keyword chars; `::`, `<`, `&`, `*`, `,` keep tight (sanitize/
	    // despace normalize the space away for mangled keys and canonical compares).
	    std::string frag = template_token_fragment(t);
	    if ( !spelling.empty() && !frag.empty() )
	    {
		char prev = spelling.back(), cur = frag[0];
		bool prev_word = isalnum((unsigned char)prev) || prev == '_';
		bool cur_word = isalnum((unsigned char)cur) || cur == '_';
		if ( prev_word && cur_word )
		    spelling += ' ';
	    }
	    spelling += frag;
	}
	if ( tokens_out )
	    tokens_out->push_back(t->clone());
	if ( t->id() == TokenID::tkLT )
	    ++angle_depth;
	else if ( t->id() == TokenID::tkGT && angle_depth > 0 )
	    --angle_depth;
	else if ( t->id() == TokenID::tkBSR && angle_depth > 0 )
	    angle_depth = angle_depth > 1 ? angle_depth - 2 : 0;
	else if ( t->id() == TokenID::tkOpBrk )
	    ++paren_depth;
	else if ( t->id() == TokenID::tkClBrk && paren_depth > 0 )
	    --paren_depth;
	else if ( t->id() == TokenID::tkOpSqr )
	    ++square_depth;
	else if ( t->id() == TokenID::tkClSqr && square_depth > 0 )
	    --square_depth;
	t = nextToken();
    }
    Throw(first) << "Unexpected end of input in template argument list" << flush;
    return NULL;
}

static std::string single_contextual_token_name(const std::vector<TokenBase *> &toks)
{
    if ( toks.size() != 1 || !is_contextual_identifier_token(toks[0]) )
	return "";
    return contextual_identifier_name(toks[0]);
}

static TokenDataType *resolve_type_token_sequence(Program &pgm,
						  const std::vector<TokenBase *> &seq,
						  TokenBase *loc)
{
    if ( seq.empty() )
	return NULL;

    TokenSemi *sentinel = new TokenSemi();
    std::vector<TokenBase *> inj;
    for ( size_t i = 0; i < seq.size(); ++i )
	inj.push_back(seq[i]->clone());
    inj.push_back(sentinel);
    for ( std::vector<TokenBase *>::reverse_iterator it = inj.rbegin();
	  it != inj.rend(); ++it )
	pgm.pushToken(*it);

    TokenBase *head = pgm.nextToken();
    std::string cv_spelling;
    head = pgm.consume_template_type_arg_qualifiers(head, cv_spelling);
    (void)cv_spelling;
    TokenDataType *resolved = pgm.resolve_declared_type_token(head, true, true);
    if ( resolved )
    {
	while ( pgm.peekToken() && pgm.peekToken()->id() == TokenID::tkMul )
	{
	    pgm.nextToken();
	    DataDefPTR *ptr = pgm.getPointerType(&resolved->definition);
	    TokenDataType *pdt = new TokenDataType(ptr->name.c_str(), *ptr);
	    pdt->file = loc ? loc->file : resolved->file;
	    pdt->line = loc ? loc->line : resolved->line;
	    pdt->column = loc ? loc->column : resolved->column;
	    resolved = pdt;
	}
    }

    bool have_sentinel = false;
    for ( size_t si = 0; si < pgm.tokens.size(); ++si )
	if ( pgm.tokens[si] == sentinel )
	{
	    have_sentinel = true;
	    break;
	}
    if ( have_sentinel )
    {
	while ( pgm.peekToken() && pgm.peekToken() != sentinel )
	    pgm.nextToken();
	if ( pgm.peekToken() == sentinel )
	    pgm.nextToken();
    }
    else if ( pgm.peekToken() && pgm.peekToken()->id() == TokenID::tkSemi )
	pgm.nextToken();

    return resolved;
}

static Program::TemplateAliasDef *find_template_alias_in_class_tree(
	Program &pgm, const std::string &name, DataDefCLASS *owner,
	DataDefCLASS **matched_owner, std::set<DataDefCLASS *> *seen = NULL)
{
    if ( !owner )
	return NULL;
    std::set<DataDefCLASS *> local_seen;
    if ( !seen )
	seen = &local_seen;
    if ( seen->find(owner) != seen->end() )
	return NULL;
    seen->insert(owner);

    std::vector<Program::TemplateAliasDef> *it =
	pgm.template_alias_map.find(name);
    if ( it != pgm.template_alias_map.end() )
	for ( size_t i = 0; i < it->size(); ++i )
	    if ( (*it)[i].owner_class == owner )
	    {
		if ( matched_owner )
		    *matched_owner = owner;
		return &(*it)[i];
	    }

    for ( size_t i = 0; i < owner->bases.size(); ++i )
	if ( Program::TemplateAliasDef *td =
		find_template_alias_in_class_tree(pgm, name,
						  owner->bases[i].base,
						  matched_owner, seen) )
	    return td;
    if ( Program::TemplateAliasDef *td =
	    find_template_alias_in_class_tree(pgm, name, owner->base_class,
					      matched_owner, seen) )
	return td;
    return find_template_alias_in_class_tree(pgm, name, owner->enclosing_class,
					     matched_owner, seen);
}

static TokenDataType *resolve_simple_member_detection_alias(
	Program &pgm, const Program::TemplateAliasDef &op_alias,
	const std::vector<std::vector<TokenBase *> > &op_arg_tokens,
	TokenBase *loc)
{
    const std::vector<TokenBase *> &target = op_alias.target;
    if ( target.size() < 4 )
	return NULL;
    if ( !is_contextual_identifier_token(target[0])
      || contextual_identifier_name(target[0]) != "typename" )
	return NULL;
    if ( !is_contextual_identifier_token(target[1])
      || target[2]->id() != TokenID::tkNS
      || !is_contextual_identifier_token(target[3]) )
	return NULL;

    std::string param_name = contextual_identifier_name(target[1]);
    size_t param_index = op_alias.typeparams.size();
    for ( size_t i = 0; i < op_alias.typeparams.size(); ++i )
	if ( op_alias.typeparams[i] == param_name )
	{
	    param_index = i;
	    break;
	}
    if ( param_index >= op_arg_tokens.size() )
	return NULL;

    TokenDataType *arg_type =
	resolve_type_token_sequence(pgm, op_arg_tokens[param_index], loc);
    DataDefCLASS *arg_class = arg_type
	? dynamic_cast<DataDefCLASS *>(&arg_type->definition) : NULL;
    if ( !arg_class )
	return NULL;

    std::string member_name = contextual_identifier_name(target[3]);
    DataDef *member = resolve_class_type_alias(arg_class, member_name);
    return member ? make_alias_type_token(member_name, member, loc) : NULL;
}

static bool template_param_expects_type(const std::vector<bool> &kinds,
					size_t index)
{
    return index >= kinds.size() || kinds[index];
}

static size_t first_template_pack_index(const std::vector<bool> &packs)
{
    for ( size_t i = 0; i < packs.size(); ++i )
	if ( packs[i] )
	    return i;
    return packs.size();
}

static bool template_has_parameter_pack(const std::vector<bool> &packs)
{
    return first_template_pack_index(packs) < packs.size();
}

// True when the template's base-specifier is a DEPENDENT MEMBER TYPE — a
// template-id immediately followed by `::member` in the base clause, i.e.
// `struct X : public Base<...>::type { }`. This is the non-recursive
// trait-FORWARDING shape (`__invoke_result : __result_of_impl<...>::type`,
// `__is_invocable : __is_invocable_impl<...>::type`): the class's entire meaning
// is the type it inherits, which can only be computed by really instantiating the
// base template and taking its member. It is distinct from the RECURSIVE bases
// (`tuple : _Tuple_impl<0, Ts...>`, `__and_ : conditional_t<...>`) whose base is a
// plain template-id (or alias), NOT a `::member` — so this predicate cleanly
// selects the forwarding traits without admitting the unbounded recursion the
// flag-clear at instantiate_template_use guards against. Scans the base-clause
// region of td.body (everything before the class body's opening `{` at depth 0)
// for a `>`/`>>` (template-id close) immediately followed by `::`.
static bool template_base_is_dependent_member(const Program::TemplateDef &td)
{
    int depth = 0;
    for ( size_t i = 0; i + 1 < td.body.size(); ++i )
    {
	TokenBase *t = td.body[i];
	if ( !t )
	    continue;
	TokenID id = t->id();
	if ( id == TokenID::tkOpBrc )
	{
	    if ( depth == 0 )
		return false;          // reached the class body — no dependent-member base
	    ++depth;
	}
	else if ( id == TokenID::tkClBrc )
	    --depth;
	else if ( depth == 0
	       && (id == TokenID::tkGT || id == TokenID::tkBSR)
	       && td.body[i + 1] && td.body[i + 1]->id() == TokenID::tkNS )
	    return true;               // `...>::` in the base clause
    }
    return false;
}

// A class template whose BASE CLAUSE names a template-id base (`: public
// Base<...>`). When the template itself is being really instantiated, its base
// must instantiate too — and a variadic / partial-spec base (std::tuple's
// `_Tuple_impl<_Idx, _Elements...>`) only really instantiates while variadic
// real-instantiation is active. So a true result keeps real-instantiation
// STICKY through the body re-parse (the base resolves with the flag on),
// bounded by variadic_inst_in_progress. Detects a `<` after the base-intro `:`
// and before the class body `{` (depth 0).
static bool template_base_clause_has_template_id(const Program::TemplateDef &td)
{
    bool in_base_clause = false;
    for ( size_t i = 0; i < td.body.size(); ++i )
    {
	TokenBase *t = td.body[i];
	if ( !t )
	    continue;
	TokenID id = t->id();
	if ( id == TokenID::tkOpBrc )
	    return false;              // reached the class body — no template-id base
	if ( id == TokenID::tkColon )
	    in_base_clause = true;
	else if ( in_base_clause && id == TokenID::tkLT )
	    return true;               // `: ... Name< ...` template-id base
    }
    return false;
}

// A variadic class template is REALLY instantiable (body parse + member evaluation,
// not just an opaque dependent shell) for concrete args when its only pack is a
// TRAILING TYPE pack and it carries a parseable body with no non-type params. This is
// the shape of the SFINAE trait helpers that must fold for `vector<T*>` —
// `__construct_helper<_Tp, _Args...>` whose `using type = decltype(__test<_Alloc>(0))`
// member must evaluate. Other variadic shapes (non-type packs, body-less) stay on the
// opaque path. The actual concreteness of the args is decided AFTER parsing them (a
// dependent arg falls back to the opaque shell), so this predicate only gates SHAPE.
static bool template_pack_real_instantiable(const Program::TemplateDef &td)
{
    if ( td.body.empty() )
	return false;
    size_t n = td.typeparams.size();
    if ( n == 0 )
	return false;
    size_t pack_index = first_template_pack_index(td.typeparam_is_pack);
    if ( pack_index != n - 1 )
	return false;	// no pack, or pack is not the LAST parameter
    // EVERY parameter must be a TYPE parameter — the arg loop only absorbs type args
    // into pack_subst, and a genuine non-type / template-template param needs the
    // opaque path. (td.has_non_type_params is a misnomer — it is set true even for a
    // pure TYPE pack — so test typeparam_is_type directly.)
    if ( n > td.typeparam_is_type.size() )
	return false;
    for ( size_t i = 0; i < n; ++i )
	if ( !td.typeparam_is_type[i] )
	    return false;
    return true;
}

static std::vector<TokenBase *> clone_template_tokens_with_type_subst(
	const std::vector<TokenBase *> &src,
	const std::map<std::string, TokenDataType *> &subst)
{
    std::vector<TokenBase *> out;
    for ( TokenBase *bt : src )
    {
	if ( bt && bt->type() == TokenType::ttIdentifier )
	{
	    const std::string &s = ((TokenIdent *)bt)->spelling();
	    std::map<std::string, TokenDataType *>::const_iterator si =
		subst.find(s);
	    if ( si != subst.end() )
	    {
		out.push_back(si->second->clone());
		continue;
	    }
	}
	out.push_back(bt ? bt->clone() : NULL);
    }
    return out;
}

// Like clone_template_tokens_with_type_subst, but ALSO expands a trailing pack: a
// `pack_name` identifier immediately followed by `...` is replaced by the pack's
// element types comma-separated (an EMPTY pack drops the preceding `,` so
// `<_Fn, _Args...>` -> `<_Fn>`, never `<_Fn,>`). A bare `pack_name` not followed by
// `...` falls back to the ordinary 1:1 subst. With an empty pack_name this behaves
// exactly like clone_template_tokens_with_type_subst.
static std::vector<TokenBase *> clone_template_tokens_with_pack_subst(
	const std::vector<TokenBase *> &src,
	const std::map<std::string, TokenDataType *> &subst,
	const std::string &pack_name,
	const std::vector<DataDef *> &pack_elems)
{
    std::vector<TokenBase *> out;
    for ( size_t i = 0; i < src.size(); ++i )
    {
	TokenBase *bt = src[i];
	if ( !pack_name.empty() && bt && bt->type() == TokenType::ttIdentifier
	  && ((TokenIdent *)bt)->spelling() == pack_name
	  && i + 3 < src.size()
	  && src[i+1] && src[i+1]->id() == TokenID::tkDot
	  && src[i+2] && src[i+2]->id() == TokenID::tkDot
	  && src[i+3] && src[i+3]->id() == TokenID::tkDot )
	{
	    if ( pack_elems.empty() && !out.empty()
	      && out.back()->id() == TokenID::tkComma )
	    { delete out.back(); out.pop_back(); }
	    for ( size_t e = 0; e < pack_elems.size(); ++e )
	    {
		if ( e )
		    out.push_back(new TokenComma());
		out.push_back(new TokenDataType(pack_elems[e]->name.c_str(),
						*pack_elems[e]));
	    }
	    i += 3;   // consume the `...`
	    continue;
	}
	if ( bt && bt->type() == TokenType::ttIdentifier )
	{
	    std::map<std::string, TokenDataType *>::const_iterator si =
		subst.find(((TokenIdent *)bt)->spelling());
	    if ( si != subst.end() )
	    { out.push_back(si->second->clone()); continue; }
	}
	out.push_back(bt ? bt->clone() : NULL);
    }
    return out;
}

// Substitute a variable template's captured type args into its initializer tokens,
// binding the leading fixed type parameters 1:1 and absorbing any surplus args into
// a trailing parameter pack (`is_invocable_v<_Fn, _Args...>` etc.). Without the pack
// path a multi-arg use left `_Args...` unexpanded in the init (`is_invocable<_Fn,
// int...>`), which then failed to parse — the var-template analogue of the
// partial-spec / member-fn-template trailing-pack absorption.
static std::vector<TokenBase *> substitute_var_template_init(
	const Program::VarTemplateDef &vd, const std::vector<DataDef *> &targs)
{
    bool has_pack = !vd.typeparams.empty()
		 && !vd.typeparam_is_pack.empty() && vd.typeparam_is_pack.back();
    size_t nfixed = has_pack ? vd.typeparams.size() - 1 : vd.typeparams.size();
    std::map<std::string, TokenDataType *> subst;
    for ( size_t i = 0; i < nfixed && i < targs.size(); ++i )
	if ( targs[i] )
	    subst[vd.typeparams[i]] =
		new TokenDataType(targs[i]->name.c_str(), *targs[i]);
    std::string pack_name = has_pack ? vd.typeparams.back() : std::string();
    std::vector<DataDef *> pack_elems;
    if ( has_pack )
	for ( size_t i = nfixed; i < targs.size(); ++i )
	    if ( targs[i] )
		pack_elems.push_back(targs[i]);
    return clone_template_tokens_with_pack_subst(vd.init, subst, pack_name, pack_elems);
}

static std::string template_tokens_spelling(
	const std::vector<TokenBase *> &tokens)
{
    std::string spelling;
    for ( TokenBase *t : tokens )
	spelling += template_token_fragment(t);
    return spelling;
}

static size_t template_id_suffix_end(
	const std::vector<TokenBase *> &tokens, size_t lt_index,
	bool *split_gt = NULL)
{
    // *split_gt (when provided): set true if the closing token was a `>>`
    // (tkBSR) that supplied ONE leftover `>` for an ENCLOSING template-id —
    // i.e. the suffix ended at a `>>` while only one `>` was needed to balance
    // this `<...>`. The caller that swallows the suffix must then re-emit a
    // single `>` so the enclosing template-id's close is not lost (the source
    // `Outer<Inner<_Up>>` lexes the trailing pair as one `>>`).
    if ( split_gt )
	*split_gt = false;
    int depth = 0;
    for ( size_t i = lt_index; i < tokens.size(); ++i )
    {
	// operator-function-id: skip `operator` + its symbol token(s) so e.g.
	// `operator<` is not counted as opening a nested template-id.
	if ( size_t n = operator_id_token_span(tokens, i) )
	{
	    i += n - 1;
	    continue;
	}
	if ( tokens[i]->id() == TokenID::tkLT )
	    ++depth;
	else if ( tokens[i]->id() == TokenID::tkGT )
	{
	    --depth;
	    if ( depth <= 0 )
		return i;
	}
	else if ( tokens[i]->id() == TokenID::tkBSR )
	{
	    if ( depth > 1 )
		depth -= 2;
	    else
	    {
		// `>>` closes this `<...>` (depth 1 -> 0) AND leaves a `>` for
		// the enclosing template-id.
		if ( split_gt && depth == 1 )
		    *split_gt = true;
		depth = 0;
	    }
	    if ( depth <= 0 )
		return i;
	}
    }
    return lt_index;
}

// Should the self-name template-id at `tokens[lt_index]` (== `<`), appearing in a
// class template's BODY, be kept as a DISTINCT specialization (re-instantiated)
// rather than collapsed to the injected-class-name (the mangled current type)?
//
// Per [temp.local], a self-name with the template's OWN parameter list
// (`tuple<_Tp>` inside `tuple<_Tp>`) IS the injected-class-name and collapses. A
// self-name with DIFFERENT args is a different specialization. The primary
// `_Tuple_impl`'s `typedef _Tuple_impl<_Idx+1,_Tail...> _Inherited;` is the empty-
// tuple recursion terminator (`_Tuple_impl<1>`); collapsing it to self made the
// ctor's `: _Inherited()` a delegating self-call -> infinite recursion -> stack
// overflow at run time. So it must stay distinct.
//
// But only when the args are CONCRETELY SUBSTITUTABLE — every identifier among
// them is one of the class template's own parameters (`_Idx`, `_Tail`), so the
// clone loop's substitution turns them into a real type. A self-name whose args
// reference an OUTER/dependent name (a member-template parameter, e.g.
// `_UseOtherCtor<_Tuple, tuple<_Up>>` or `_Tuple_impl<_Idx, _UElements...>`)
// cannot be instantiated here and must keep the old collapse (re-instantiating a
// dependent `tuple<_Up>` crashes type resolution). Conservative: anything not
// provably class-param-only stays collapsed.
static bool self_template_id_keep_distinct(
	const Program::TemplateDef &td, const std::vector<TokenBase *> &tokens,
	size_t lt_index)
{
    if ( lt_index >= tokens.size() || tokens[lt_index]->id() != TokenID::tkLT )
	return false;
    std::vector<std::vector<TokenBase *> > slots;
    std::vector<TokenBase *> cur;
    int depth = 0;
    for ( size_t i = lt_index + 1; i < tokens.size(); ++i )
    {
	TokenID id = tokens[i]->id();
	if ( depth == 0 && (id == TokenID::tkGT || id == TokenID::tkBSR) )
	    break;   // close of this `<...>`
	if ( id == TokenID::tkLT || id == TokenID::tkOpBrk || id == TokenID::tkOpSqr )
	    ++depth;
	else if ( id == TokenID::tkGT || id == TokenID::tkClBrk || id == TokenID::tkClSqr )
	    --depth;
	else if ( id == TokenID::tkBSR )
	    depth -= 2;
	if ( depth == 0 && id == TokenID::tkComma )
	{ slots.push_back(cur); cur.clear(); continue; }
	cur.push_back(tokens[i]);
    }
    if ( !cur.empty() )
	slots.push_back(cur);
    if ( slots.empty() )
	return false;   // `Self<>` — nothing to instantiate distinctly
    std::set<std::string> params(td.typeparams.begin(), td.typeparams.end());
    // (a) Is this the injected-class-name (args == the template's own params)?
    bool is_current = slots.size() == td.typeparams.size();
    for ( size_t k = 0; is_current && k < slots.size(); ++k )
    {
	const std::vector<TokenBase *> &slot = slots[k];
	bool is_pack = k < td.typeparam_is_pack.size() && td.typeparam_is_pack[k];
	if ( slot.empty() || !is_contextual_identifier_token(slot[0])
	  || contextual_identifier_name(slot[0]) != td.typeparams[k] )
	    { is_current = false; break; }
	size_t want = is_pack ? 4 : 1;   // pack: param-name + `...`
	if ( slot.size() != want
	  || (is_pack && (slot[1]->id() != TokenID::tkDot
		       || slot[2]->id() != TokenID::tkDot
		       || slot[3]->id() != TokenID::tkDot)) )
	    { is_current = false; break; }
    }
    if ( is_current )
	return false;   // current instantiation -> collapse to injected-class-name
    // (b) Every identifier among the args must be a class template parameter, so
    // substitution yields a concrete, instantiable type.
    for ( const std::vector<TokenBase *> &slot : slots )
	for ( TokenBase *t : slot )
	    if ( is_contextual_identifier_token(t)
	      && !params.count(contextual_identifier_name(t)) )
		return false;   // references an outer/dependent name -> collapse
    return true;
}

TokenBase *Program::consume_template_type_arg_qualifiers(TokenBase *tb,
						       std::string &spelling)
{
    while ( is_type_qualifier_token(tb) )
    {
	if ( tb->id() == TokenID::tkCONST )
	    spelling += "const ";
	else if ( tb->id() == TokenID::tkVOLATILE )
	    spelling += "volatile ";
	else if ( tb->id() == TokenID::tkRESTRICT )
	    spelling += "restrict ";
	tb = nextToken();
    }
    return tb;
}

// GCC's __integer_pack(N) builtin — the libstdc++-13 GCC-path index-sequence
// primitive (bits/utility.h: make_integer_sequence / _Build_index_tuple). It is
// valid ONLY as the entire pattern of a template-argument pack expansion
// `X<... __integer_pack(N)... ...>`; at substitution time (N already a concrete
// constant) it yields the constant pack [0, 1, ..., N-1] (size_t). This rewrites
// the live token stream IN PLACE, between a just-consumed `<` and its matching
// close, splicing each `__integer_pack(E)...` into the literal integer args so
// the ordinary template-argument loops then collect plain non-type args. Model:
// GCC cp/pt.cc expand_integer_pack (builds a vec of size_int(i)).
void Program::expand_integer_pack_template_args()
{
    // Bound the rewrite to THIS template-id's argument region: scan to the
    // angle-depth-0 close so an __integer_pack belonging to an outer/sibling
    // construct is never touched. `<` is already consumed, so depth starts at 1.
    // Track paren depth so a `<`/`>` inside `__integer_pack(...)` can't skew it.
    size_t end = tokens.size();
    {
	int adepth = 1, pdepth = 0;
	for ( size_t i = 0; i < tokens.size(); ++i )
	{
	    TokenBase *t = tokens[i];
	    if ( !t ) continue;
	    TokenID id = t->id();
	    if ( id == TokenID::tkOpBrk ) ++pdepth;
	    else if ( id == TokenID::tkClBrk ) { if ( pdepth > 0 ) --pdepth; }
	    else if ( pdepth == 0 )
	    {
		if ( id == TokenID::tkLT ) ++adepth;
		else if ( id == TokenID::tkGT ) { if ( --adepth == 0 ) { end = i; break; } }
		else if ( id == TokenID::tkBSR ) { adepth -= 2; if ( adepth <= 0 ) { end = i; break; } }
	    }
	}
    }

    std::vector<TokenBase *> out;
    bool changed = false;
    size_t j = 0;
    while ( j < end )
    {
	TokenBase *t = tokens[j];
	if ( t && t->type() == TokenType::ttIdentifier
	  && ((TokenIdent *)t)->spelling_is("__integer_pack")
	  && j + 1 < end && tokens[j+1]
	  && tokens[j+1]->id() == TokenID::tkOpBrk )
	{
	    // Match the parenthesized argument `( E )`.
	    int pd = 0;
	    size_t close_p = j + 1;
	    for ( ; close_p < end; ++close_p )
	    {
		if ( !tokens[close_p] ) continue;
		TokenID pid = tokens[close_p]->id();
		if ( pid == TokenID::tkOpBrk ) ++pd;
		else if ( pid == TokenID::tkClBrk ) { if ( --pd == 0 ) break; }
	    }
	    // Require the trailing `...` (three tkDot) within the region; without
	    // it this is not a pack expansion and is left untouched.
	    size_t dots = close_p + 1;
	    bool has_ellipsis = pd == 0 && close_p < end && dots + 2 < end
		&& tokens[dots]   && tokens[dots]->id()   == TokenID::tkDot
		&& tokens[dots+1] && tokens[dots+1]->id() == TokenID::tkDot
		&& tokens[dots+2] && tokens[dots+2]->id() == TokenID::tkDot;
	    int64_t N = -1;
	    if ( has_ellipsis )
	    {
		std::vector<TokenBase *> inner;	// tokens between '(' and ')'
		for ( size_t k = j + 2; k < close_p; ++k )
		    if ( tokens[k] ) inner.push_back(tokens[k]);
		int64_t v;
		if ( fold_nontype_arg_constant(inner, v) && v >= 0 )
		    N = v;
	    }
	    if ( N >= 0 )
	    {
		// Free the consumed pattern tokens (`__integer_pack ( E ) ...`).
		for ( size_t k = j; k <= dots + 2; ++k )
		    delete tokens[k];
		if ( N == 0 )
		{
		    // Empty pack: emit nothing; drop the adjacent separator comma
		    // (prefer the preceding one already in `out`, else the next).
		    bool dropped = false;
		    if ( !out.empty() && out.back()
		      && out.back()->id() == TokenID::tkComma )
		    { delete out.back(); out.pop_back(); dropped = true; }
		    j = dots + 3;
		    if ( !dropped && j < end && tokens[j]
		      && tokens[j]->id() == TokenID::tkComma )
		    { delete tokens[j]; ++j; }
		    changed = true;
		    continue;
		}
		// N >= 1: emit `0, 1, ..., N-1` (no trailing comma — the caller's
		// following `,`/`>` is preserved).
		for ( int64_t e = 0; e < N; ++e )
		{
		    if ( e ) out.push_back(new TokenComma());
		    out.push_back(new TokenInt(e));
		}
		j = dots + 3;	// past the three dots
		changed = true;
		continue;
	    }
	}
	out.push_back(tokens[j]);
	++j;
    }

    if ( changed )
    {
	// Carried-over originals live in `out`; erase removes the deque slots
	// (does not free), then splice the rewritten region back at the front.
	tokens.splice_front(end, out);
    }
}

// Defined below (near the partial-spec unifiers); used here to resolve a
// deduced pack element's spelling to its instantiated type token.
static DataDef *resolve_arg_spelling_datadef(Program &pgm, const std::string &spelling);
static bool datadef_has_unresolved_dependent_surface(DataDef *dd);

static bool opaque_template_args_select_concrete_partial_spec(
	Program &pgm, const Program::TemplateDef &td, const std::string &tname,
	const std::vector<std::string> &args,
	const std::vector<std::vector<TokenBase *> > &raw_arg_tokens)
{
    if ( args.size() != raw_arg_tokens.size() )
	return false;

    std::vector<TokenDataType *> arg_types_by_slot;
    std::vector<std::vector<TokenBase *> > arg_tokens_by_slot;
    std::vector<std::string> arg_spellings;
    size_t pack_index = first_template_pack_index(td.typeparam_is_pack);
    for ( size_t ai = 0; ai < args.size(); ++ai )
    {
	size_t bind_pi = ai;
	if ( bind_pi >= td.typeparams.size() )
	{
	    if ( pack_index < td.typeparams.size() )
		bind_pi = pack_index;
	    else
		return false;
	}
	if ( template_param_expects_type(td.typeparam_is_type, bind_pi) )
	{
	    DataDef *dd = resolve_arg_spelling_datadef(pgm, args[ai]);
	    if ( !dd || datadef_has_unresolved_dependent_surface(dd) )
		return false;
	    arg_types_by_slot.push_back(new TokenDataType(dd->name.c_str(), *dd));
	    arg_tokens_by_slot.push_back(std::vector<TokenBase *>());
	    arg_spellings.push_back(args[ai]);
	}
	else
	{
	    if ( raw_arg_tokens[ai].size() != 1
	      || !raw_arg_tokens[ai][0]
	      || raw_arg_tokens[ai][0]->id() != TokenID::tkInt )
		return false;
	    int64_t folded = 0;
	    if ( !pgm.fold_nontype_arg_constant(raw_arg_tokens[ai], folded) )
		return false;
	    std::vector<TokenBase *> folded_tokens;
	    folded_tokens.push_back(new TokenInt(folded));
	    arg_types_by_slot.push_back(NULL);
	    arg_tokens_by_slot.push_back(folded_tokens);
	    arg_spellings.push_back(std::to_string(folded));
	}
    }

    std::map<std::string, TokenDataType *> spec_subst;
    std::map<std::string, std::string> spec_tmpl_subst;
    std::map<std::string, std::vector<std::string> > spec_pack_subst;
    std::map<std::string, std::vector<TokenBase *> > spec_nontype_subst;
    Program::TemplateDef *spec = pgm.match_partial_specialization(
	tname, arg_types_by_slot, arg_spellings, arg_tokens_by_slot,
	td.typeparam_is_type, spec_subst, spec_tmpl_subst, spec_pack_subst,
	spec_nontype_subst);
    return spec && !spec->body.empty();
}

TokenDataType *Program::instantiate_opaque_template_use(Program::TemplateDef &td,
						      const std::string &tname,
						      TokenBase *tb)
{
    InstTimer _it(*this);	// --show-stats: instantiation time
    nextToken(); // consume '<'
    expand_integer_pack_template_args();
    std::vector<std::string> args;
    std::vector<std::vector<TokenBase *> > raw_arg_tokens;
    if ( peekToken() && (peekToken()->id() == TokenID::tkGT
      || peekToken()->id() == TokenID::tkBSR) )
    {
	TokenBase *close = nextToken();
	if ( !consume_template_close(close) )
	    Throw(close) << "Expecting '>' in " << tname << "<...>" << flush;
    }
    else
    {
	for (;;)
	{
	    TokenBase *at = nextToken();
	    std::string spelling;
	    std::vector<TokenBase *> arg_tokens;
	    TokenBase *sep = collect_template_argument_spelling(at, spelling,
								&arg_tokens);
	    args.push_back(spelling);
	    raw_arg_tokens.push_back(arg_tokens);
	    if ( sep->id() == TokenID::tkComma )
		continue;
	    if ( consume_template_close(sep) )
		break;
	    Throw(sep) << "Expecting ',' or '>' in " << tname << "<...>" << flush;
	}
    }
    size_t pack_index = first_template_pack_index(td.typeparam_is_pack);
    bool has_pack = pack_index < td.typeparams.size();
    if ( !has_pack && args.size() > td.typeparams.size() )
	Throw(tb) << tname << "<> expects " << td.typeparams.size()
		      << " argument(s), got " << args.size() << flush;
    size_t required_args = has_pack ? pack_index : td.typeparams.size();
    while ( args.size() < required_args )
    {
	size_t ai = args.size();
	if ( ai >= td.typeparam_defaults.size()
	  || td.typeparam_defaults[ai].empty() )
	    Throw(tb) << tname << "<> expects " << td.typeparams.size()
			  << " argument(s), got " << args.size() << flush;
	std::string spelling;
	std::vector<TokenBase *> arg_tokens;
	for ( TokenBase *dt : td.typeparam_defaults[ai] )
	{
	    spelling += template_token_fragment(dt);
	    arg_tokens.push_back(dt ? dt->clone() : NULL);
	}
	args.push_back(spelling);
	raw_arg_tokens.push_back(arg_tokens);
    }

    // Key an empty variadic instantiation (`tuple<>`) under the SAME bare name the
    // real-instantiation path (instantiate_template_use, via
    // template_instantiation_key_head) uses — NOT a `__empty_pack`-suffixed variant.
    // A distinct suffix split one logical type `tuple<>` into two structs (`tuple`
    // vs `tuple__empty_pack`), so the pair piecewise ctor's deduced empty value-tuple
    // param did not match the call's `tuple<>` argument — map<int,int> sub-wall B's
    // third identity mismatch. With the same key, datatype_map.find reuses one type.
    std::string mangled = tname;
    std::string canon;
    if ( td.owner_class )
    {
	canon = td.owner_class->canonical_cpp_spelling.empty()
	      ? td.owner_class->name : td.owner_class->canonical_cpp_spelling;
	canon += "::";
    }
    else if ( !td.defining_namespace.empty() )
	canon = td.defining_namespace + "::";
    canon += tname + "<";
    for ( size_t i = 0; i < args.size(); ++i )
    {
	mangled += "_" + canonical_arg_key_fragment(raw_arg_tokens[i], args[i]);
	if ( i )
	    canon += ",";
	canon += args[i];
    }
    canon += ">";

    if ( opaque_template_args_select_concrete_partial_spec(*this, td, tname,
	    args, raw_arg_tokens) )
    {
	std::vector<TokenBase *> replay;
	replay.push_back(new TokenLT());
	for ( size_t i = 0; i < raw_arg_tokens.size(); ++i )
	{
	    if ( i )
		replay.push_back(new TokenComma());
	    for ( TokenBase *t : raw_arg_tokens[i] )
		replay.push_back(t ? t->clone() : NULL);
	}
	replay.push_back(new TokenGT());
	for ( std::vector<TokenBase *>::reverse_iterator it = replay.rbegin();
	      it != replay.rend(); ++it )
	    pushToken(*it);

	bool saved_vri = allow_variadic_real_inst;
	allow_variadic_real_inst = true;
	TokenDataType *real = instantiate_template_use(tname, tb,
	    td.defining_namespace, td.owner_class);
	allow_variadic_real_inst = saved_vri;
	if ( real )
	    return real;
    }

    flat_datatype_map_iter have = datatype_map.find(mangled);
    if ( have != datatype_map.end() )
	return use_site_type_token((TokenDataType *)(*have), tb);

    DataDefCLASS *fwd = new DataDefCLASS(mangled, 0, DataType::dtRESERVED);
    fwd->is_dependent_placeholder = true;
    fwd->canonical_cpp_spelling = canon;
    struct_map[mangled] = fwd;
    // Keep the template-origin STRUCTURE (name + per-arg token runs) so tsubst
    // can rebuild the concrete instantiation from a binding later — the shell's
    // name/spelling alone is unresolvable (see Program::DependentShellOrigin).
    {
	DependentShellOrigin &org = dependent_shell_origin[fwd];
	org.tname = tname;
	org.defining_namespace = td.defining_namespace;
	org.owner_class = td.owner_class;
	org.arg_spellings = args;
	org.raw_arg_tokens.resize(raw_arg_tokens.size());
	for ( size_t ai = 0; ai < raw_arg_tokens.size(); ++ai )
	    for ( TokenBase *t : raw_arg_tokens[ai] )
		org.raw_arg_tokens[ai].push_back(t ? t->clone() : NULL);
    }
    TokenDataType *tdt = new TokenDataType(mangled.c_str(), *fwd);
    datatype_map[mangled] = tdt;
    if ( !td.defining_namespace.empty() )
	namespace_datatype_map[td.defining_namespace][mangled] = tdt;
    return use_site_type_token(tdt, tb);
}

TokenDataType *Program::instantiate_shell_origin_replay(
			const DependentShellOrigin &org,
			const std::vector<std::vector<TokenBase *> > &arg_runs)
{
    // The partial-spec replay shape (opaque_template_args_select_concrete_
    // partial_spec above): push `< run [, run ...] >` then re-enter
    // instantiate_template_use. Args here are already CONCRETE, so the
    // variadic real-instantiation gate must be open (a `tuple<int>` use
    // real-instantiates exactly like the member-type-chain path).
    std::vector<TokenBase *> replay;
    replay.push_back(new TokenLT());
    bool first_run = true;
    for ( const std::vector<TokenBase *> &run : arg_runs )
    {
	if ( !first_run )
	    replay.push_back(new TokenComma());
	first_run = false;
	for ( TokenBase *t : run )
	    if ( t )
		replay.push_back(t);
    }
    replay.push_back(new TokenGT());
    size_t replay_base = tokens.size();
    for ( std::vector<TokenBase *>::reverse_iterator it = replay.rbegin();
	  it != replay.rend(); ++it )
	pushToken(*it);

    bool saved_vri = allow_variadic_real_inst;
    bool saved_poisoned = dependent_parse_poisoned;
    allow_variadic_real_inst = true;
    TokenIdent name_tb(org.tname.c_str());
    TokenDataType *real = NULL;
    try
    {
	real = instantiate_template_use(org.tname, &name_tb,
					org.defining_namespace,
					org.owner_class);
    }
    catch ( ... ) { real = NULL; }
    allow_variadic_real_inst = saved_vri;
    // Drain any unconsumed replay tokens so a failure never leaks stray
    // injected tokens into the caller's stream (the capture+replay lesson).
    while ( tokens.size() > replay_base )
	nextToken();
    dependent_parse_poisoned = saved_poisoned;
    return real;
}

static bool is_incomplete_class_datadef(DataDef *dd)
{
    DataDefCLASS *cls = dynamic_cast<DataDefCLASS *>(dd);
    if ( !cls )
	return false;
    if ( cls->is_dependent_placeholder )
	return true;
    // A `{ ... }` body was parsed: the class is COMPLETE even with zero members
    // (a typedef-only trait such as iterator_traits<T> / __are_same<A,B>). Without
    // this, such a fully-instantiated class matches the empty-aggregate heuristic
    // below and is misread as "not yet instantiated", so the cache check in
    // instantiate_template_use re-instantiates it on every reference (measured:
    // iterator_traits<uint32_t> instantiated 6x for an empty <iostream> program).
    if ( cls->is_complete )
	return false;
    return cls->size == 0 && cls->members.empty()
	&& cls->methods.empty() && cls->ctors.empty()
	&& cls->bases.empty();
}

static bool is_incomplete_template_class_type(TokenDataType *tdt)
{
    return tdt && is_incomplete_class_datadef(&tdt->definition);
}

static bool datadef_has_unresolved_dependent_surface(DataDef *dd);

static bool class_has_dependent_base(DataDefCLASS *cls,
				     std::set<DataDefCLASS *> *seen = NULL)
{
    if ( !cls )
	return false;
    std::set<DataDefCLASS *> local_seen;
    if ( !seen )
	seen = &local_seen;
    if ( seen->find(cls) != seen->end() )
	return false;
    seen->insert(cls);
    for ( size_t i = 0; i < cls->bases.size(); ++i )
    {
	DataDefCLASS *base = cls->bases[i].base;
	if ( !base )
	    continue;
	if ( base->is_dependent_placeholder || base->has_dependent_surface
	  || class_has_dependent_base(base, seen) )
	    return true;
    }
    if ( cls->base_class
      && (cls->base_class->is_dependent_placeholder
       || cls->base_class->has_dependent_surface
       || class_has_dependent_base(cls->base_class, seen)) )
	return true;
    return false;
}

static bool class_has_unresolved_dependent_surface(DataDefCLASS *cls)
{
    return cls && (cls->is_dependent_placeholder || cls->has_dependent_surface
	|| class_has_dependent_base(cls));
}

static bool class_allows_opaque_member_type(DataDefCLASS *cls)
{
    if ( class_has_unresolved_dependent_surface(cls) )
	return true;
    return cls && cls->from_system_header
	&& cls->canonical_cpp_spelling.find('<') != std::string::npos;
}

static bool datadef_has_unresolved_dependent_surface(DataDef *dd)
{
    if ( !dd )
	return false;
    if ( dd->is_template_param() )
	return true;
    if ( DataDefCLASS *cls = dynamic_cast<DataDefCLASS *>(dd) )
	return class_has_unresolved_dependent_surface(cls);
    if ( DataDefPTR *ptr = dynamic_cast<DataDefPTR *>(dd) )
	return datadef_has_unresolved_dependent_surface(ptr->base_type);
    if ( DataDefCArray *arr = dynamic_cast<DataDefCArray *>(dd) )
	return datadef_has_unresolved_dependent_surface(arr->element_type);
    return false;
}

DataDefCLASS *Program::materialize_dependent_member_type(DataDefCLASS *owner,
						       const std::string &member_name)
{
    if ( !owner || member_name.empty() )
	return NULL;
    std::string dep_name = owner->name + "__" + sanitize_template_fragment(member_name);
    flat_datatype_map_iter have = datatype_map.find(dep_name);
    if ( have != datatype_map.end() )
	return dynamic_cast<DataDefCLASS *>(&(*have)->definition);

    DataDefCLASS *dep = new DataDefCLASS(dep_name, 0, DataType::dtRESERVED);
    dep->is_dependent_placeholder = true;
    std::string owner_spelling = owner->canonical_cpp_spelling.empty()
			       ? owner->name : owner->canonical_cpp_spelling;
    dep->canonical_cpp_spelling = owner_spelling + "::" + member_name;
    struct_map[dep_name] = dep;
    datatype_map[dep_name] = new TokenDataType(dep_name.c_str(), *dep);
    return dep;
}

DataDefCLASS *Program::materialize_opaque_class_type(const std::string &name,
						   const std::string &canonical)
{
    if ( name.empty() )
	return NULL;
    flat_datatype_map_iter have = datatype_map.find(name);
    if ( have != datatype_map.end() )
	return dynamic_cast<DataDefCLASS *>(&(*have)->definition);

    DataDefCLASS *dep = new DataDefCLASS(name, 0, DataType::dtRESERVED);
    dep->is_dependent_placeholder = true;
    dep->canonical_cpp_spelling = canonical.empty() ? name : canonical;
    struct_map[name] = dep;
    datatype_map[name] = new TokenDataType(name.c_str(), *dep);
    return dep;
}

DataDef *Program::dependent_deref_result_type(DataDef *dd)
{
    if ( !dd )
	return NULL;
    if ( DataDefPTR *ptr = dynamic_cast<DataDefPTR *>(dd) )
	return ptr->base_type ? ptr->base_type : &ddINT64;
    if ( !datadef_has_unresolved_dependent_surface(dd) )
	return NULL;
    std::string spelling = dd->canonical_cpp_spelling.empty()
			 ? dd->name : dd->canonical_cpp_spelling;
    return materialize_opaque_class_type(
	sanitize_template_fragment(dd->name + "__deref"), "*" + spelling);
}

static void record_pending_template_instantiation(
	Program &pgm, const std::string &tname, const std::string &mangled,
	const std::string &canon, const std::vector<TokenDataType *> &args)
{
    std::vector<Program::PendingTemplateInstantiation> &pending =
	pgm.pending_template_instantiations[tname];
    for ( size_t i = 0; i < pending.size(); ++i )
	if ( pending[i].mangled_name == mangled )
	    return;

    Program::PendingTemplateInstantiation pti;
    pti.mangled_name = mangled;
    pti.canonical_spelling = canon;
    for ( size_t i = 0; i < args.size(); ++i )
	pti.args.push_back((TokenDataType *)args[i]->clone());
    pending.push_back(pti);
}

TokenDataType *Program::instantiate_template_id(const std::string &tname,
					       TokenBase *tb,
					       const std::string &ns_hint,
					       DataDefCLASS *owner_hint)
{
    if ( TokenDataType *alias_inst =
	    instantiate_template_alias_use(tname, tb, ns_hint, owner_hint) )
	return alias_inst;
    return instantiate_template_use(tname, tb, ns_hint, owner_hint);
}

TokenDataType *Program::instantiate_template_use(const std::string &tname,
					       TokenBase *tb,
					       const std::string &ns_hint,
					       DataDefCLASS *owner_hint)
{
    InstTimer _it(*this);	// --show-stats: instantiation time
    Program::TemplateDef *tdp = find_template(tname, ns_hint, owner_hint);
    if ( !tdp )
	return NULL;
    if ( !peekToken() || peekToken()->id() != TokenID::tkLT )
	return NULL;
    // Copy (not reference): instantiating the body can re-enter template
    // registration, and a vector reallocation would dangle a live reference.
    // Both this function and instantiate_opaque_template_use only read td.
    Program::TemplateDef td = *tdp;
    // A variadic template normally stays an opaque dependent shell — EXCEPT a
    // concrete-arg trailing-type-pack template with a body, which must really
    // instantiate so its members (e.g. `__construct_helper<_Tp,_Args...>::type =
    // decltype(...)`) fold. The arg loop below absorbs the trailing pack into
    // pack_subst; a still-dependent arg falls back to the opaque shell after parsing.
    // Real-instantiate a variadic template ONLY for a concrete-arg trailing-type-pack
    // shape AND only while resolving a member-TYPE chain (allow_variadic_real_inst) —
    // see the flag's declaration. The flag is consumed here, then cleared so nested
    // instantiations triggered by this body do NOT inherit it (a recursive variadic
    // body would otherwise re-enter the real path unboundedly). The STICKY variant
    // (variadic_real_inst_sticky) survives this clear: it propagates real-instantiation
    // through a dependent-member-base forwarding chain (`__invoke_result` ->
    // `__result_of_impl`), bounded by variadic_inst_in_progress (set below).
    bool pack_real_inst = (allow_variadic_real_inst || variadic_real_inst_sticky)
		       && template_pack_real_instantiable(td);
    // While resolving a member-TYPE chain (allow/sticky), a PRIMARY with non-type
    // params (`__result_of_impl<bool,bool,typename,typename...>`) is itself opaque
    // (template_pack_real_instantiable rejects non-type params), but a PARTIAL SPEC
    // of it (`__result_of_impl<false,false,_Functor,_ArgTypes...>` — bools concrete,
    // own params type+pack) IS real-instantiable and carries the meaningful body
    // (`typedef decltype(_S_test<...>(0)) type;`). Defer the opaque bail so the
    // partial-spec match below can run and swap to that spec; if none matches, the
    // primary's empty body falls back to the opaque placeholder downstream (3287).
    bool try_spec_real_inst = (allow_variadic_real_inst || variadic_real_inst_sticky)
			   && partial_spec_map.count(tname);
    allow_variadic_real_inst = false;
    // When this real-instantiation forwards through a dependent-member base
    // (`: Base<...>::type`), keep real-instantiation on for the nested base/arg
    // resolution during its re-parse so the whole forwarding trait chain folds.
    bool want_sticky = pack_real_inst
		    && (template_base_is_dependent_member(td)
		     || template_base_clause_has_template_id(td));
    if ( template_has_parameter_pack(td.typeparam_is_pack) && !pack_real_inst
      && !try_spec_real_inst )
	return instantiate_opaque_template_use(td, tname, tb);
    if ( td.has_non_type_params && td.body.empty() && !try_spec_real_inst )
	return instantiate_opaque_template_use(td, tname, tb);

    // Parse `< Arg [, Arg ...] >`, resolving type parameters as DataDefs and
    // preserving non-type parameters as token sequences for later substitution.
    nextToken(); // consume '<'
    expand_integer_pack_template_args();
    std::vector<TokenDataType *> type_args;
    std::vector<TokenDataType *> arg_types_by_slot;
    std::vector<std::vector<TokenBase *> > arg_tokens_by_slot;
    std::vector<std::string> arg_spellings;
    // A concrete instantiation's identity is (defining_namespace, name, args).
    // The bare name alone suffices to key the type UNLESS the same bare name is
    // declared in more than one namespace (e.g. std::char_traits vs
    // __gnu_cxx::char_traits) — only then must the namespace enter the mangled
    // key, so the two instantiations don't alias the same datatype_map entry.
    // Keeping the common single-namespace case byte-identical avoids churning
    // every std:: template's internal tag.
    std::string mangled =
	template_instantiation_key_head(*this, tname, td.defining_namespace);
    std::map<std::string, TokenDataType *> subst;
    std::map<std::string, std::vector<TokenBase *> > token_subst;
    // A trailing-pack param deduced by a partial spec (`_SomeTemplate<_Tp, _Types...>`
    // in __replace_first_arg): name -> the pack's element type tokens (empty for an
    // empty pack). Expanded in the body loop where `_Types...` appears.
    std::map<std::string, std::vector<TokenDataType *> > pack_subst;
    // A trailing TYPE pack absorbs every arg from its position onward (see
    // template_pack_real_instantiable): once `pi` reaches `pack_index`, extra args
    // keep binding to it via this clamp, accumulating into pack_subst rather than
    // overflowing the typeparam list.
    size_t pack_index = first_template_pack_index(td.typeparam_is_pack);
    size_t pi = 0;
    if ( peekToken() && (peekToken()->id() == TokenID::tkGT
	  || peekToken()->id() == TokenID::tkBSR) )
    {
	TokenBase *close = nextToken();
	if ( !consume_template_close(close) )
	    Throw(close) << "Expecting '>' in " << tname << "<...>" << flush;
    }
    else
    {
	for (;;)
	{
	    size_t bind_pi = pi;
	    if ( bind_pi >= td.typeparams.size() )
	    {
		// Past the fixed params: a trailing pack keeps absorbing; otherwise
		// it is a genuine too-many-arguments error.
		if ( pack_index < td.typeparams.size() )
		    bind_pi = pack_index;
		else
		    Throw(tb) << tname << "<> expects " << td.typeparams.size()
				  << " argument(s)" << flush;
	    }
	    bool bind_is_pack = bind_pi < td.typeparam_is_pack.size()
			     && td.typeparam_is_pack[bind_pi];
	    TokenBase *at = nextToken();
	    TokenBase *sep = NULL;
	    if ( template_param_expects_type(td.typeparam_is_type, bind_pi) )
	    {
		std::string cv_spelling;
		at = consume_template_type_arg_qualifiers(at, cv_spelling);
		TokenDataType *adt = resolve_declared_type_token(at, true, true);
		if ( !adt )
		    Throw(at) << "Expecting a type argument to "
				  << tname << "<>" << flush;
		// Fold a trailing declarator suffix (`*`/`&`/`&&`) into the arg type.
		adt = fold_template_arg_declarator(adt, at);
		type_args.push_back(adt);
		arg_types_by_slot.push_back(adt);
		arg_tokens_by_slot.push_back(std::vector<TokenBase *>());
		// A trailing type pack accumulates its elements (the body loop expands
		// `_Args...` from pack_subst); a fixed type param binds singly.
		if ( bind_is_pack )
		    pack_subst[td.typeparams[bind_pi]].push_back(adt);
		else
		    subst[td.typeparams[bind_pi]] = adt;
		arg_spellings.push_back(template_type_arg_spelling(adt,
								  cv_spelling));
		sep = nextToken();
	    }
	    else
	    {
		std::string spelling;
		std::vector<TokenBase *> arg_tokens;
		sep = collect_template_argument_spelling(at, spelling,
							 &arg_tokens);
		// Substitution-time non-type-arg fold: a NON-dependent integral/
		// bool constant arg (`(1==1)`, `is_trivial<int>::value`,
		// `__is_bitwise_relocatable<int>::value`) normalizes to its value
		// so partial-spec selection (`enable_if<true,T>`) and the
		// instantiation key see a literal — mirrors g++/clang folding every
		// non-dependent non-type arg. A still-dependent arg fails to fold
		// and keeps its raw tokens unchanged.
		int64_t folded_nt = 0;
		if ( fold_nontype_arg_constant(arg_tokens, folded_nt) )
		{
		    arg_tokens.clear();
		    arg_tokens.push_back(new TokenInt(folded_nt));
		    spelling = std::to_string(folded_nt);
		}
		token_subst[td.typeparams[pi]] = arg_tokens;
		arg_types_by_slot.push_back(NULL);
		arg_tokens_by_slot.push_back(arg_tokens);
		arg_spellings.push_back(spelling);
	    }
	    ++pi;
	    if ( sep->id() == TokenID::tkComma )
		continue;
	    if ( consume_template_close(sep) )
		break;
	    Throw(sep) << "Expecting ',' or '>' in "
			   << tname << "<...>" << flush;
	}
    }

    while ( pi < td.typeparams.size() )
    {
	// A trailing parameter PACK absorbs zero-or-more args: reaching it with no
	// remaining args is a valid EMPTY pack (`tuple<>`, `__and_<>`), not a missing
	// argument. Leave pack_subst without an entry for it (the body loop drops the
	// preceding `,` and the `...`) and stop default-filling.
	if ( pi < td.typeparam_is_pack.size() && td.typeparam_is_pack[pi] )
	    break;
	if ( pi >= td.typeparam_defaults.size()
	  || td.typeparam_defaults[pi].empty() )
	    Throw(tb) << tname << "<> expects " << td.typeparams.size()
			  << " argument(s), got " << pi << flush;
	std::vector<TokenBase *> default_tokens =
	    clone_template_tokens_with_type_subst(td.typeparam_defaults[pi],
						 subst);
	if ( template_param_expects_type(td.typeparam_is_type, pi) )
	{
	    std::vector<TokenBase *> inj = default_tokens;
	    inj.push_back(new TokenSemi());
	    for ( std::vector<TokenBase *>::reverse_iterator it = inj.rbegin();
		  it != inj.rend(); ++it )
		pushToken(*it);
	    TokenBase *dtok = nextToken();
	    std::string cv_spelling;
	    dtok = consume_template_type_arg_qualifiers(dtok, cv_spelling);
	    TokenDataType *adt = resolve_declared_type_token(dtok, true, true);
	    if ( !adt )
		Throw(dtok ? dtok : tb)
		    << "Could not resolve default template argument for "
		    << td.typeparams[pi] << " in " << tname << "<>" << flush;
	    // Fold the default's declarator suffix (`_Tp*`, `_Tp&`, `_Tp&&`)
	    // into the argument type, mirroring the explicit-argument path's
	    // star fold. Stopping at the base type left the suffix tokens in
	    // the LIVE stream (std::iterator's `_Pointer = _Tp*, _Reference =
	    // _Tp&` defaults leaked a stray `&` that derailed the enclosing
	    // class definition) and dropped the suffix from the arg identity.
	    for (;;)
	    {
		TokenBase *sfx = peekToken();
		if ( !sfx )
		    break;
		if ( sfx->id() == TokenID::tkMul )
		{
		    nextToken();
		    DataDefPTR *ptr = getPointerType(&adt->definition);
		    TokenDataType *padt = new TokenDataType(ptr->name.c_str(), *ptr);
		    padt->file = dtok->file;
		    padt->line = dtok->line;
		    padt->column = dtok->column;
		    adt = padt;
		    continue;
		}
		if ( sfx->id() == TokenID::tkBand || sfx->id() == TokenID::tkLand )
		{
		    nextToken();
		    DataDefREF *ref = getReferenceType(&adt->definition);
		    TokenDataType *radt = new TokenDataType(ref->name.c_str(), *ref);
		    radt->file = dtok->file;
		    radt->line = dtok->line;
		    radt->column = dtok->column;
		    adt = radt;
		    continue;
		}
		break;
	    }
	    if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
		nextToken();
	    type_args.push_back(adt);
	    arg_types_by_slot.push_back(adt);
	    arg_tokens_by_slot.push_back(std::vector<TokenBase *>());
	    subst[td.typeparams[pi]] = adt;
	    arg_spellings.push_back(template_type_arg_spelling(adt,
							      cv_spelling));
	}
	else
	{
	    // Same substitution-time fold for a non-type DEFAULT argument.
	    int64_t folded_nt = 0;
	    if ( fold_nontype_arg_constant(default_tokens, folded_nt) )
	    {
		default_tokens.clear();
		default_tokens.push_back(new TokenInt(folded_nt));
		token_subst[td.typeparams[pi]] = default_tokens;
		arg_types_by_slot.push_back(NULL);
		arg_tokens_by_slot.push_back(default_tokens);
		arg_spellings.push_back(std::to_string(folded_nt));
	    }
	    else
	    {
		token_subst[td.typeparams[pi]] = default_tokens;
		arg_types_by_slot.push_back(NULL);
		arg_tokens_by_slot.push_back(default_tokens);
		arg_spellings.push_back(template_tokens_spelling(default_tokens));
	    }
	}
	++pi;
    }

    for ( size_t i = 0; i < arg_spellings.size(); ++i )
	mangled += "_" + canonical_arg_key_fragment(arg_tokens_by_slot[i],
						    arg_spellings[i]);

    // Canonical C++ spelling for Itanium mangling, built from the defining
    // namespace + template name + each arg's canonical spelling (the args were
    // instantiated first during the loop above, so they already carry theirs).
    std::string canon = td.defining_namespace.empty() ? std::string()
		      : (td.defining_namespace + "::");
    canon += tname + "<";
    for ( size_t i = 0; i < arg_spellings.size(); ++i )
    {
	if ( i ) canon += ",";
	canon += arg_spellings[i];
    }
    canon += ">";

    bool dependent_surface = false;
    for ( size_t i = 0; i < type_args.size(); ++i )
	if ( datadef_has_unresolved_dependent_surface(&type_args[i]->definition) )
	    dependent_surface = true;

    std::string registered_mangled = td.owner_class
	? td.owner_class->name + "__" + mangled : mangled;

    // Partial specialization: if a partial spec of `tname` unifies with the concrete
    // args and is more specialized than the primary, instantiate ITS body with the
    // deduced params instead. The instantiation identity (mangled/canon/
    // registered_mangled, computed above) stays keyed on the concrete args, so
    // caching is unaffected — only the body source + substitution change.
    {
	std::map<std::string, TokenDataType *> spec_subst;
	std::map<std::string, std::string> spec_tmpl_subst;
	std::map<std::string, std::vector<std::string> > spec_pack_subst;
	std::map<std::string, std::vector<TokenBase *> > spec_nontype_subst;
	if ( Program::TemplateDef *spec = match_partial_specialization(
		tname, arg_types_by_slot, arg_spellings, arg_tokens_by_slot,
		td.typeparam_is_type, spec_subst, spec_tmpl_subst, spec_pack_subst,
		spec_nontype_subst) )
	{
	    // Keep the USE-SITE owner across the swap. A nested class template's
	    // partial spec is stored globally by simple name (partial_spec_map[name])
	    // with owner_class frozen to whichever enclosing instance was parsed
	    // first (e.g. allocator_traits<pmr::polymorphic_allocator<...>::rebind_alloc>),
	    // not the allocator_traits<X> actually being instantiated here. The
	    // instantiation identity (registered_mangled, computed above) is keyed on
	    // the primary's use-site owner; letting the spec's stale owner replace it
	    // re-registers the body under the wrong owner prefix → "did not register".
	    DataDefCLASS *use_site_owner = td.owner_class;
	    td = *spec;
	    td.owner_class = use_site_owner;
	    subst = spec_subst;
	    // The matched SPEC carries the real base clause (the primary that drove
	    // want_sticky above was a body-less forward decl). Recompute sticky from
	    // the spec body so a template-id base (`_Tuple_impl<_Idx+1, _Tail...>`,
	    // `_Head_base<_Idx, _Head>`) keeps variadic real-instantiation ON while
	    // THIS spec body re-parses — otherwise those bases fall back to opaque
	    // shells and the instantiated class has no storage (size 0).
	    want_sticky = template_base_is_dependent_member(td)
		       || template_base_clause_has_template_id(td);
	    // A deduced template-template parameter (`__replace_first_arg<_Template<_Up>,
	    // _Tp>` → _Template=allocator) binds to a TEMPLATE NAME, not a type: route it
	    // through token_subst so the body's `_Template<_Tp>` clones to `allocator<_Tp>`
	    // and re-parses as a template-id. (The spec body uses the param as a template.)
	    token_subst.clear();
	    for ( std::map<std::string, std::string>::iterator t = spec_tmpl_subst.begin();
		  t != spec_tmpl_subst.end(); ++t )
	    {
		std::vector<TokenBase *> repl;
		repl.push_back(new TokenIdent(t->second));
		token_subst[t->first] = repl;
	    }
	    // A deduced NON-TYPE param (`_Idx` of `_Tuple_impl<_Idx,_Head,_Tail...>`)
	    // binds to the concrete value tokens; route through token_subst so the
	    // body's `_Idx` (and computed forms like `_Idx + 1`) clone to the literal
	    // and fold. Without this a non-type-param partial spec never specialized.
	    for ( std::map<std::string, std::vector<TokenBase *> >::iterator n =
		      spec_nontype_subst.begin(); n != spec_nontype_subst.end(); ++n )
	    {
		std::vector<TokenBase *> repl;
		for ( TokenBase *t : n->second )
		    if ( t )
			repl.push_back(t->clone());
		token_subst[n->first] = repl;
	    }
	    // A deduced trailing pack (`_Types...`) binds to the absorbed concrete
	    // args; resolve each element spelling to its type token for body
	    // expansion. The real allocator rebind leaves it empty (`allocator<_Tp>`
	    // has no extra args), so an empty pack — and its `...`/comma elision —
	    // is the common path.
	    pack_subst.clear();
	    for ( std::map<std::string, std::vector<std::string> >::iterator p =
		      spec_pack_subst.begin(); p != spec_pack_subst.end(); ++p )
	    {
		std::vector<TokenDataType *> elems;
		for ( size_t ei = 0; ei < p->second.size(); ++ei )
		{
		    DataDef *edd = resolve_arg_spelling_datadef(*this, p->second[ei]);
		    if ( edd )
			elems.push_back(new TokenDataType(edd->name.c_str(), *edd));
		}
		pack_subst[p->first] = elems;
	    }
	}
    }

    // Already instantiated? Return a use-site clone of the cached type.
    flat_datatype_map_iter have = datatype_map.find(registered_mangled);
    if ( have != datatype_map.end() )
    {
	TokenDataType *cached = (TokenDataType *)(*have);
	if ( td.body.empty() || !is_incomplete_template_class_type(cached) )
	    return use_site_type_token(cached, tb);
    }
    // A variadic template admitted to the real path (template_pack_real_instantiable)
    // but instantiated with a STILL-DEPENDENT arg stays an opaque dependent shell —
    // exactly the pre-change behavior (the 2874 short-circuit sent ALL pack uses here).
    // Only a fully concrete-arg variadic template proceeds to body parse below.
    // Re-entering the SAME mangled instantiation while sticky forwarding is active is a
    // self-referential trait loop → fall to the opaque placeholder to bound recursion.
    if ( td.body.empty() || (pack_real_inst && dependent_surface)
      || (want_sticky && variadic_inst_in_progress.count(registered_mangled)) )
    {
	DataDefCLASS *fwd = new DataDefCLASS(registered_mangled, 0, DataType::dtRESERVED);
	fwd->canonical_cpp_spelling = canon;
	fwd->is_dependent_placeholder = true;
	fwd->has_dependent_surface = true;
	struct_map[registered_mangled] = fwd;
	TokenDataType *tdt = new TokenDataType(registered_mangled.c_str(), *fwd);
	datatype_map[registered_mangled] = tdt;
	if ( !td.defining_namespace.empty() )
	    namespace_datatype_map[td.defining_namespace][registered_mangled] = tdt;
	record_pending_template_instantiation(*this, tname, registered_mangled, canon, type_args);
	return use_site_type_token(tdt, tb);
    }

    // Build the substituted, renamed class-definition token sequence:
    // clone each body token; rename the class tag (TokenIdent == class_name) to
    // `mangled`; replace each type-parameter ident with its concrete type token.
    //
    // clone() stamps each new token's file/line/column from the STATIC
    // _parse_file/_parse_line (TokenBase's ctor), which here is the INSTANTIATION
    // SITE (e.g. the user .mad), not the template's defining file. That misfiles
    // every instantiated member body to the use site, so a system-header template
    // (std::vector) is wrongly classified from_system_header=0 and ALL its member
    // bodies parse eagerly — hitting walls in members the program never ODR-uses
    // (vector::operator=(vector&&)'s __move_storage). nextToken() propagates
    // _parse_file from each consumed token during the re-parse below, so giving the
    // clones the template's real (system-header) origin makes from_system_header,
    // lazy-body deferral, AND error attribution all see the true source. Point
    // _parse_* at the template body's origin across the clone loop, then restore.
    const char *cloned_pf = TokenBase::_parse_file;
    int cloned_pl = TokenBase::_parse_line;
    int cloned_pc = TokenBase::_parse_column;
    for ( TokenBase *bt0 : td.body )
	if ( bt0 && bt0->file )
	{
	    TokenBase::_parse_file = bt0->file;
	    TokenBase::_parse_line = bt0->line;
	    TokenBase::_parse_column = bt0->column;
	    break;
	}
    std::vector<TokenBase *> inj;
    // Index of the class-body opener `{` (first top-level brace). A self-name
    // BEFORE it sits in the base clause; AFTER it, in the body. Used to keep a
    // recursive self-template BASE (`_Tuple_impl<_Idx+1,_Tail...>`) a distinct
    // template-id instead of collapsing it to the injected-class-name.
    size_t body_brace_index = td.body.size();
    for ( size_t fb = 0; fb < td.body.size(); ++fb )
	if ( td.body[fb] && td.body[fb]->id() == TokenID::tkOpBrc )
	{ body_brace_index = fb; break; }
    // Indices of trailing `...` tokens (three tkDot) belonging to a pack-
    // expansion PATTERN (`const _Elements&...`) whose pack we substituted
    // in place — see the pack_subst handling below. Skipped when reached.
    std::set<size_t> pack_pattern_skip_dots;
    // Function-parameter names whose pack was EMPTY and elided (`const _Tail&...
    // __tail` with empty _Tail): a later VALUE pack-expansion `__tail...` in the
    // ctor body / mem-init (`_Inherited(__tail...)`) must also vanish, else the
    // elided name is "undeclared". Recorded by the empty-param-pack elision.
    std::set<std::string> empty_value_pack_names;
    for ( size_t bi = 0; bi < td.body.size(); ++bi )
    {
	if ( pack_pattern_skip_dots.count(bi) )
	    continue;
	TokenBase *bt = td.body[bi];
	if ( bt->type() == TokenType::ttIdentifier )
	{
	    const std::string &s = ((TokenIdent *)bt)->spelling();
	    // VALUE pack-expansion of an elided EMPTY parameter pack: `__tail...`
	    // in `_Inherited(__tail...)` must vanish (the param `__tail` was elided
	    // for the empty pack). Drop `__tail` + `...` and balance one separating
	    // comma (preceding if present, else a following one) so the call's
	    // argument list stays well-formed (`_Inherited(__tail...)` ->
	    // `_Inherited()`, `f(a, __tail...)` -> `f(a)`).
	    if ( empty_value_pack_names.count(s)
	      && bi + 3 < td.body.size()
	      && td.body[bi+1] && td.body[bi+1]->id() == TokenID::tkDot
	      && td.body[bi+2] && td.body[bi+2]->id() == TokenID::tkDot
	      && td.body[bi+3] && td.body[bi+3]->id() == TokenID::tkDot )
	    {
		bool dropped = false;
		if ( !inj.empty() && inj.back()->id() == TokenID::tkComma )
		{ delete inj.back(); inj.pop_back(); dropped = true; }
		bi += 3;   // consume `__tail` (current) + the three dots
		if ( !dropped && bi + 1 < td.body.size()
		  && td.body[bi+1] && td.body[bi+1]->id() == TokenID::tkComma )
		    ++bi;  // consume a following comma instead
		continue;
	    }
	    std::map<std::string, TokenDataType *>::iterator si = subst.find(s);
	    if ( si != subst.end() ) { inj.push_back(si->second->clone()); continue; }
	    std::map<std::string, std::vector<TokenBase *> >::iterator nti =
		token_subst.find(s);
	    if ( nti != token_subst.end() )
	    {
		for ( size_t ni = 0; ni < nti->second.size(); ++ni )
		    inj.push_back(nti->second[ni]->clone());
		continue;
	    }
	    std::map<std::string, std::vector<TokenDataType *> >::iterator pki =
		pack_subst.find(s);
	    if ( pki != pack_subst.end() )
	    {
		// Pack expansion `_Types...`: emit the absorbed element types
		// comma-separated. An EMPTY pack (the common allocator-rebind
		// case) must drop the immediately-preceding `,` already emitted
		// (so `C<_Up, _Types...>` -> `C<_Up>`, never `C<_Up,>`). The
		// trailing `...` (three tkDot) in the body is then consumed.
		const std::vector<TokenDataType *> &elems = pki->second;
		// EMPTY function-PARAMETER pack with a declarator suffix
		// (`const _Tail&... __tail`): the pack name is followed by cv/ref/ptr
		// tokens THEN `...`. The whole parameter — leading cv already in
		// `inj`, its separating comma, the suffix, the `...`, and the param
		// name — must vanish (`(const _Head& h, const _Tail&... t)` ->
		// `(const _Head& h)`). The generic comma-drop below only handles an
		// immediately-preceding comma, so handle the suffixed pattern here.
		if ( elems.empty() )
		{
		    size_t pj = bi + 1;
		    while ( pj < td.body.size() && td.body[pj]
		      && (td.body[pj]->id() == TokenID::tkBand
		       || td.body[pj]->id() == TokenID::tkLand
		       || td.body[pj]->id() == TokenID::tkMul
		       || td.body[pj]->id() == TokenID::tkCONST
		       || td.body[pj]->id() == TokenID::tkVOLATILE) )
			++pj;
		    bool param_pack = pj > bi + 1 && pj + 2 < td.body.size()
			&& td.body[pj] && td.body[pj]->id() == TokenID::tkDot
			&& td.body[pj+1] && td.body[pj+1]->id() == TokenID::tkDot
			&& td.body[pj+2] && td.body[pj+2]->id() == TokenID::tkDot;
		    if ( param_pack )
		    {
			// Record the elided parameter name (`__tail`, the first
			// identifier after the `...`) so its VALUE pack-expansion
			// `__tail...` in the body / mem-init is elided too.
			if ( pj + 3 < td.body.size() && td.body[pj+3]
			  && is_contextual_identifier_token(td.body[pj+3]) )
			    empty_value_pack_names.insert(
				contextual_identifier_name(td.body[pj+3]));
			while ( !inj.empty()
			  && (inj.back()->id() == TokenID::tkCONST
			   || inj.back()->id() == TokenID::tkVOLATILE) )
			{ delete inj.back(); inj.pop_back(); }
			bool popped_comma = false;
			if ( !inj.empty() && inj.back()->id() == TokenID::tkComma )
			{ delete inj.back(); inj.pop_back(); popped_comma = true; }
			size_t pk = pj + 3;
			int pdepth = 0;
			while ( pk < td.body.size() && td.body[pk] )
			{
			    TokenID kid = td.body[pk]->id();
			    if ( kid == TokenID::tkOpBrk || kid == TokenID::tkLT )
				++pdepth;
			    else if ( kid == TokenID::tkClBrk )
			    { if ( pdepth == 0 ) break; --pdepth; }
			    else if ( kid == TokenID::tkGT && pdepth > 0 )
				--pdepth;
			    else if ( pdepth == 0 && kid == TokenID::tkComma )
			    { if ( !popped_comma ) ++pk; break; }
			    else if ( pdepth == 0
			      && (kid == TokenID::tkSemi || kid == TokenID::tkClBrc) )
				break;
			    ++pk;
			}
			bi = pk - 1;   // loop ++bi resumes after the elided param
			continue;
		    }
		}
		if ( elems.empty() && !inj.empty()
		  && inj.back()->id() == TokenID::tkComma )
		{
		    delete inj.back();
		    inj.pop_back();
		}
		for ( size_t ei = 0; ei < elems.size(); ++ei )
		{
		    if ( ei )
		        inj.push_back(new TokenComma());
		    inj.push_back(elems[ei]->clone());
		}
		if ( bi + 3 < td.body.size()
		  && td.body[bi+1]->id() == TokenID::tkDot
		  && td.body[bi+2]->id() == TokenID::tkDot
		  && td.body[bi+3]->id() == TokenID::tkDot )
		    bi += 3;   // consume the pack-expansion ellipsis
		else if ( elems.size() == 1 )
		{
		    // Pack expansion PATTERN: the pack name is NOT immediately
		    // followed by `...` (e.g. `const _Elements&...`), so the single
		    // element was substituted in place above, leaving the pattern's
		    // trailing `...` orphaned. Find it (the next three tkDot at the
		    // pack's own nesting depth, before any `,`/`)`/`;`/`{`) and skip
		    // it. Single-element only — a multi-arg pack pattern needs the
		    // pattern REPEATED per element (not yet supported; left to error).
		    int depth = 0;
		    for ( size_t j = bi + 1; j + 2 < td.body.size(); ++j )
		    {
			TokenID jid = td.body[j]->id();
			if ( jid == TokenID::tkLT || jid == TokenID::tkOpBrk
			  || jid == TokenID::tkOpSqr )
			    ++depth;
			else if ( jid == TokenID::tkGT || jid == TokenID::tkClBrk
			  || jid == TokenID::tkClSqr )
			    --depth;
			else if ( jid == TokenID::tkBSR )
			    depth -= 2;
			else if ( depth <= 0 && jid == TokenID::tkDot
			  && td.body[j+1]->id() == TokenID::tkDot
			  && td.body[j+2]->id() == TokenID::tkDot )
			{
			    pack_pattern_skip_dots.insert(j);
			    pack_pattern_skip_dots.insert(j + 1);
			    pack_pattern_skip_dots.insert(j + 2);
			    break;
			}
			else if ( depth <= 0
			  && (jid == TokenID::tkComma || jid == TokenID::tkClBrk
			   || jid == TokenID::tkSemi || jid == TokenID::tkOpBrc) )
			    break;   // pattern boundary, no `...` found
			if ( depth < 0 )
			    break;
		    }
		}
		continue;
	    }
	    if ( s == td.class_name )
	    {
		// A namespace-QUALIFIED reference to a same-named template in
		// a DIFFERENT namespace (`__gnu_cxx::char_traits<_CharT>` as
		// std::char_traits' base) is not a self-reference — renaming
		// it (and swallowing its <...>) corrupts the base/typedef.
		// Leave it for normal qualified resolution.
		bool foreign_qualified =
		    bi >= 2 && td.body[bi-1]
		    && td.body[bi-1]->id() == TokenID::tkNS
		    && td.body[bi-2]
		    && is_contextual_identifier_token(td.body[bi-2])
		    && contextual_identifier_name(td.body[bi-2])
		       != td.defining_namespace;
		if ( !foreign_qualified )
		{
		    // A self-name USED AS A TEMPLATE in the BASE CLAUSE
		    // (`_Tuple_impl<_Idx+1, _Tail...>` as a base of
		    // `_Tuple_impl<_Idx,_Head,_Tail...>`) is a DISTINCT specialization
		    // the class inherits — NOT the injected-class-name. Keep the name
		    // and its `<...>` so the surrounding clone loop substitutes the
		    // args (`_Idx+1`->`0+1`, `_Tail...` expands) and it re-parses as a
		    // fresh template-id, instantiating the right base. Collapsing it to
		    // the mangled self made the class try to inherit from itself
		    // ("Unknown base class"). In the BODY (method signatures), a self
		    // template-id stays collapsed as before.
		    bool self_as_template =
			bi + 1 < td.body.size()
			&& td.body[bi + 1]->id() == TokenID::tkLT;
		    bool self_template_base =
			bi < body_brace_index && self_as_template;
		    // In the BODY, a self-name template-id whose ARGS DIFFER from the
		    // template's own parameters is a DISTINCT specialization, NOT the
		    // injected-class-name — keep it distinct so the clone loop
		    // substitutes its args and it re-instantiates. The primary
		    // `_Tuple_impl`'s `typedef _Tuple_impl<_Idx+1,_Tail...> _Inherited;`
		    // (the empty-tuple recursion terminator) MUST resolve to
		    // `_Tuple_impl<1>`, not collapse to the current instantiation —
		    // collapsing made its ctor's `: _Inherited()` a delegating
		    // self-call -> infinite recursion -> stack overflow at run time. The
		    // true injected-class-name (`tuple<_Tp>` == the template's own
		    // params) still collapses below.
		    bool self_template_body_distinct =
			!self_template_base && self_as_template
			&& self_template_id_keep_distinct(td, td.body, bi + 1);
		    if ( self_template_base || self_template_body_distinct )
		    {
			inj.push_back(bt->clone());   // keep class_name; args substitute below
			continue;
		    }
		    TokenIdent *ni = (TokenIdent *)bt->clone();
		    set_token_spelling(ni, mangled);
		    inj.push_back(ni);
		    if ( bi + 1 < td.body.size()
		      && td.body[bi + 1]->id() == TokenID::tkLT )
		    {
			// Self-name USED AS A TEMPLATE (`tuple<_Tp>` inside
			// tuple's body == std::tuple<_Tp>, a DIFFERENT type):
			// the mangled current-instantiation name does not take
			// args, so swallow the `<...>`. If the suffix ends at a
			// `>>` that also closed an ENCLOSING template-id (e.g.
			// `_UseOtherCtor<_Tuple, tuple<_Up>>`), re-emit the
			// leftover `>` so the outer template-id stays balanced —
			// otherwise the spelling scanner runs past it into the
			// class body.
			bool split_gt = false;
			bi = template_id_suffix_end(td.body, bi + 1, &split_gt);
			if ( split_gt )
			    inj.push_back(new TokenGT());
		    }
		    continue;
		}
	    }
	}
	inj.push_back(bt->clone());
    }
    // Terminate the class definition so the class parser stops cleanly without
    // consuming the caller's following tokens (e.g. the declared variable name).
    TokenSemi *semi = new TokenSemi();
    inj.push_back(semi);
    // Restore the live parse position now that all instantiation clones are made;
    // nextToken() will re-derive _parse_file from each injected token as the class
    // re-parses (the clones now carry the template's true origin file).
    TokenBase::_parse_file = cloned_pf;
    TokenBase::_parse_line = cloned_pl;
    TokenBase::_parse_column = cloned_pc;

    DBG(std::cout << "instantiate_template_use(): injecting " << inj.size()
	<< " tokens for " << mangled << std::endl);

    // Inject to the FRONT of the parse deque (push_front in reverse so they
    // dequeue in order), then re-parse the class definition via its keyword token.
    for ( std::vector<TokenBase *>::reverse_iterator it = inj.rbegin(); it != inj.rend(); ++it )
	pushToken(*it);
    // Re-parse the injected class definition at TOP-LEVEL scope. Instantiation
    // is triggered mid-statement (e.g. while parsing `Box<int> b;` inside a
    // function), so the enclosing function's compound scope is active — without
    // this the class's methods would be registered as nested/local functions
    // (id `caller__Class__method__N`), breaking call-site resolution. Save and
    // clear the function context, instantiate, then restore.
    std::stack<TokenCpnd *> saved_compounds;
    std::swap(compounds, saved_compounds);
    std::vector<DataDefCLASS *> saved_class_scope_stack;
    std::swap(class_scope_stack, saved_class_scope_stack);
    std::string saved_func = cur_func_name;
    cur_func_name.clear();
    // The instantiated body is a self-contained, fully-terminated class
    // definition (its own struct/class keyword + a synthesized trailing ';',
    // injected above). It must be parsed in FULL, never inheriting the caller's
    // parse MODE: an enclosing nested-class delegation (TokenSTRUCT/TokenCLASS
    // member loop) leaves class_definition_only / parsing_cpp_struct_class set,
    // which would make this re-parse early-return at the body's '}' and leave
    // the terminating ';' to derail the caller (e.g. a template-id base clause
    // `struct I : bf<int> {...}`). Top-level instantiation already runs with
    // these clear; isolate the nested case to match.
    bool saved_def_only = class_definition_only;
    bool saved_cpp_struct_class = parsing_cpp_struct_class;
    bool saved_cpp_union_class = parsing_cpp_union_class;
    class_definition_only = false;
    parsing_cpp_struct_class = false;
    parsing_cpp_union_class = false;

    // Stashed around the re-parse; TokenCLASS::parse records it on the DataDefCLASS
    // so a bodyless method binds to the real C++ symbol without class-name tests.
    std::string saved_canon = instantiating_canonical_spelling;
    bool saved_dependent_surface = instantiating_dependent_surface;
    instantiating_canonical_spelling = canon;
    instantiating_dependent_surface = dependent_surface;
    NamespaceScope ns_scope(*this, td.defining_namespace);

    bool pushed_owner_scope = false;
    if ( td.owner_class )
    {
	class_scope_stack.push_back(td.owner_class);
	pushed_owner_scope = true;
    }

    // While re-parsing a dependent-member-base forwarding trait, keep variadic
    // real-instantiation ON (sticky) so the base `Base<...>::type` and any nested
    // forwarding template in it really instantiate, and register this mangled name
    // so a self-referential re-entry bounds out to the opaque placeholder. RAII —
    // restores on both the normal and the catch path below.
    struct StickyGuard {
	Program &p; std::string key; bool active; bool saved; bool inserted;
	StickyGuard(Program &pp, const std::string &k, bool on)
	    : p(pp), key(k), active(on), saved(pp.variadic_real_inst_sticky),
	      inserted(false)
	{
	    if ( active )
	    {
		p.variadic_real_inst_sticky = true;
		inserted = p.variadic_inst_in_progress.insert(key).second;
	    }
	}
	~StickyGuard()
	{
	    if ( active )
	    {
		p.variadic_real_inst_sticky = saved;
		if ( inserted )
		    p.variadic_inst_in_progress.erase(key);
	    }
	}
    } sticky_guard(*this, registered_mangled, want_sticky);

    TokenBase *class_kw = nextToken();   // the injected `class` keyword
    try
    {
	parseKeyword((TokenKeyword *)class_kw); // TokenCLASS::parse → registers DataDefCLASS
    }
    catch ( ... )
    {
	// EXCEPTION-SAFE RESTORE. parseKeyword swapped `compounds` / class_scope_stack
	// / cur_func_name / the cpp-struct flags / the instantiating_* stash to a fresh
	// empty context above. If it THROWS (a benign error during a nested resolution
	// — e.g. instantiating a conditional_t default — that is caught UPSTREAM), the
	// restore below would be skipped, leaving `compounds` swapped-out EMPTY. The
	// caller then parses with no local scope, so its own locals/params vanish: this
	// is why `__uninitialized_move_if_noexcept_a`'s `__last` param became "undeclared"
	// (compounds=0) after a prior argument's nested instantiation threw-and-recovered.
	// Mirror the normal-path restore, then rethrow. (NamespaceScope is already RAII.)
	if ( pushed_owner_scope && !class_scope_stack.empty()
	  && class_scope_stack.back() == td.owner_class )
	    class_scope_stack.pop_back();
	std::swap(class_scope_stack, saved_class_scope_stack);
	std::swap(compounds, saved_compounds);
	cur_func_name = saved_func;
	class_definition_only = saved_def_only;
	parsing_cpp_struct_class = saved_cpp_struct_class;
	parsing_cpp_union_class = saved_cpp_union_class;
	instantiating_canonical_spelling = saved_canon;
	instantiating_dependent_surface = saved_dependent_surface;
	throw;
    }

    if ( pushed_owner_scope
      && !class_scope_stack.empty()
      && class_scope_stack.back() == td.owner_class )
	class_scope_stack.pop_back();

    std::swap(class_scope_stack, saved_class_scope_stack);
    std::swap(compounds, saved_compounds);
    cur_func_name = saved_func;
    class_definition_only = saved_def_only;
    parsing_cpp_struct_class = saved_cpp_struct_class;
    parsing_cpp_union_class = saved_cpp_union_class;
    instantiating_canonical_spelling = saved_canon;
    instantiating_dependent_surface = saved_dependent_surface;

    // Attach any out-of-line member definitions (`Class<T>::member` in a .tcc) of
    // this template to the freshly-instantiated class as deferred (ODR-use-lazy)
    // member bodies. Keyed on the PRIMARY template's name+ns and the use-site args
    // (arg_*_by_slot), so the def's type-parameters map positionally to concretes.
    {
	datadef_map_iter sm = struct_map.find(registered_mangled);
	DataDefCLASS *inst_ddc = sm != struct_map.end()
	    ? dynamic_cast<DataDefCLASS *>(sm->second) : NULL;
	std::string ool_key = td.defining_namespace + "::" + td.class_name;
	std::vector<OutOfLineMemberInstantiation> &recs =
	    out_of_line_member_instantiations[ool_key];
	bool seen_ool_inst = false;
	for ( size_t ri = 0; ri < recs.size(); ++ri )
	    if ( recs[ri].registered_mangled == registered_mangled )
	    {
		seen_ool_inst = true;
		break;
	    }
	if ( !seen_ool_inst )
	{
	    OutOfLineMemberInstantiation rec;
	    rec.registered_mangled = registered_mangled;
	    rec.arg_types_by_slot = arg_types_by_slot;
	    rec.arg_tokens_by_slot = arg_tokens_by_slot;
	    recs.push_back(rec);
	}
	register_outofline_member_instantiations(td.class_name,
	    td.defining_namespace, registered_mangled, inst_ddc,
	    arg_types_by_slot, arg_tokens_by_slot);
    }

    flat_datatype_map_iter now = datatype_map.find(registered_mangled);
    if ( now == datatype_map.end() )
	Throw(tb) << "internal: template instantiation " << registered_mangled << " did not register" << flush;
    DBG(std::cout << "instantiate_template_use(): instantiated " << registered_mangled << std::endl);
    return use_site_type_token((TokenDataType *)(*now), tb);
}

bool Program::alias_use_args_all_concrete(const TemplateAliasDef &td,
		     const std::vector<std::vector<TokenBase *> > &arg_tokens)
{
    // This is a cheap CONCRETENESS PREDICATE, not the real resolution: it must not
    // trigger variadic real-instantiation, or the per-arg resolves below cascade
    // into the alias-use ↔ concreteness-check recursion (stack overflow). The actual
    // fold happens in the body-resolve of the caller, where the flag is honored.
    bool saved_vri = allow_variadic_real_inst;
    allow_variadic_real_inst = false;
    bool pushed_owner_scope = false;
    if ( td.owner_class )
    {
	class_scope_stack.push_back(td.owner_class);
	pushed_owner_scope = true;
    }
    bool all_concrete = true;
    for ( size_t i = 0; i < arg_tokens.size() && all_concrete; ++i )
    {
	// Default to "type" when the slot kind is unknown (pack tails); a type
	// arg is the stricter classification (it must RESOLVE non-dependently).
	bool is_type = i < td.typeparam_is_type.size()
		     ? td.typeparam_is_type[i] : true;
	if ( !is_type )
	{
	    // A non-type arg is concrete iff it constant-folds; a still-dependent
	    // arg (`bwr<_Tp>::value` with `_Tp` unbound) Throws and is caught here.
	    int64_t v = 0;
	    if ( !fold_nontype_arg_constant(arg_tokens[i], v) )
		all_concrete = false;
	    continue;
	}
	// A type arg is concrete iff it resolves (in an isolated stream, the same
	// idiom as the body resolution below) to a type with no unresolved
	// dependent surface — `NT*` concrete, `_Tp*`/a dependent placeholder not.
	std::vector<TokenBase *> body;
	for ( TokenBase *t : arg_tokens[i] )
	    if ( t )
		body.push_back(t->clone());
	body.push_back(new TokenSemi());
	size_t saved_diag_count = diagnostics.size();
	Program::ErrorInfo saved_error = last_error;
	TokenStream::State saved_tokens = tokens.swap_in(std::move(body));
	TokenDataType *rt = NULL;
	try
	{
	    rt = resolve_declared_type_token(nextToken(), true, true);
	}
	catch ( ... ) { rt = NULL; }
	tokens.swap_back(std::move(saved_tokens));
	diagnostics.resize(saved_diag_count);
	last_error = saved_error;
	if ( !rt || datadef_has_unresolved_dependent_surface(&rt->definition) )
	    all_concrete = false;
    }
    if ( pushed_owner_scope
      && !class_scope_stack.empty()
      && class_scope_stack.back() == td.owner_class )
	class_scope_stack.pop_back();
    allow_variadic_real_inst = saved_vri;
    return all_concrete;
}

TokenDataType *Program::instantiate_template_alias_use(const std::string &tname,
						     TokenBase *tb,
						     const std::string &ns_hint,
						     DataDefCLASS *owner_hint)
{
    InstTimer _it(*this);	// --show-stats: instantiation time
    Program::TemplateAliasDef *tdp = find_template_alias(tname, ns_hint,
							 owner_hint);
    if ( !tdp )
	return NULL;
    if ( !peekToken() || peekToken()->id() != TokenID::tkLT )
	return NULL;
    // COPY the def by value: find_template_alias returns a pointer into the
    // template_alias_map vector, and resolving the template arguments below
    // instantiates other templates/aliases, which call register_template_alias
    // and can REALLOCATE that vector — dangling a reference. (Symptom: a
    // member alias template like __conditional<B>::type read back 0 typeparams
    // after its args resolved, so `type<T,U>` wrongly "expects 0 type
    // arguments".) The copy is self-contained: typeparams/defaults are value
    // vectors and target holds cloned token pointers not stored in that vector.
    Program::TemplateAliasDef td = *tdp;
    if ( td.has_non_type_params )
    {
	nextToken(); // consume '<'
	std::vector<std::string> args;
	std::vector<std::vector<TokenBase *> > arg_tokens;
	for (;;)
	{
	    TokenBase *at = nextToken();
	    std::string spelling;
	    std::vector<TokenBase *> toks;
	    TokenBase *sep = collect_template_argument_spelling(at, spelling,
								&toks);
	    args.push_back(spelling);
	    arg_tokens.push_back(toks);
	    if ( sep->id() == TokenID::tkComma )
		continue;
	    if ( consume_template_close(sep) )
		break;
	    Throw(sep) << "Expecting ',' or '>' in " << tname << "<...>" << flush;
	}
	while ( args.size() < td.typeparams.size() )
	{
	    size_t ai = args.size();
	    if ( ai >= td.typeparam_defaults.size()
	      || td.typeparam_defaults[ai].empty() )
		break;
	    std::string spelling;
	    std::vector<TokenBase *> toks;
	    for ( TokenBase *dt : td.typeparam_defaults[ai] )
	    {
		spelling += template_token_fragment(dt);
		toks.push_back(dt->clone());
	    }
	    args.push_back(spelling);
	    arg_tokens.push_back(toks);
	}

	if ( tname == "__detected_or_t" && arg_tokens.size() >= 2 )
	{
	    std::string op_name = single_contextual_token_name(arg_tokens[1]);
	    DataDefCLASS *op_owner = NULL;
	    Program::TemplateAliasDef *op_alias = NULL;
	    if ( !op_name.empty() )
	    {
		for ( std::vector<DataDefCLASS *>::reverse_iterator it =
			  class_scope_stack.rbegin();
		      it != class_scope_stack.rend() && !op_alias; ++it )
		    op_alias = find_template_alias_in_class_tree(*this, op_name,
								*it,
								&op_owner);
	    }
	    std::vector<std::vector<TokenBase *> > op_args;
	    for ( size_t ai = 2; ai < arg_tokens.size(); ++ai )
		op_args.push_back(arg_tokens[ai]);
	    if ( op_alias )
	    {
		if ( TokenDataType *detected =
			resolve_simple_member_detection_alias(*this, *op_alias,
							      op_args, tb) )
		    return detected;
	    }
	    if ( TokenDataType *fallback =
		    resolve_type_token_sequence(*this, arg_tokens[0], tb) )
		return fallback;
	}

	// Cycle break: re-entering resolution of the SAME alias use (keyed tname +
	// arg spellings) is a self-referential trait loop — now reachable because a
	// variadic member really instantiates and its body re-names this alias. The
	// re-entrant call skips the resolve + concreteness check and falls to the
	// opaque placeholder, bounding the recursion (the outer resolution proceeds).
	std::string ip_key = tname + "<";
	for ( size_t i = 0; i < args.size(); ++i )
	    ip_key += (i ? "," : "") + args[i];
	ip_key += ">";
	struct InProgressGuard {
	    std::set<std::string> &s; std::string k; bool owned;
	    InProgressGuard(std::set<std::string> &set, const std::string &key)
		: s(set), k(key), owned(set.insert(key).second) {}
	    ~InProgressGuard() { if ( owned ) s.erase(k); }
	} ip_guard(alias_resolve_in_progress, ip_key);
	bool ip_reentrant = !ip_guard.owned;

	// Substitute the collected args — type AND non-type, each as its raw
	// token sequence — into the alias body and resolve, the alias-template
	// analogue of the type-params-only path below. Without this an alias
	// template with a non-type param (`conditional_t<bool,T,F>`,
	// `enable_if_t<bool,T>`, …) collapsed straight to the opaque placeholder,
	// so `conditional_t<true,int,long>` never became `int`.
	//
	// The body is resolved in an ISOLATED token stream (save/swap-in a fresh
	// deque/restore) rather than push/drain on the shared `tokens`: this alias
	// use is frequently reached WHILE instantiating an outer template body
	// (real `move_iterator::reference`), and resolving the substituted body
	// recurses into more template/alias instantiation — sentinel-draining the
	// shared stream desynced the suspended outer parse (SIGSEGV). Isolation
	// makes the recursion self-contained. If resolution fails — a genuinely
	// dependent use, or an absent `::type` (SFINAE) — fall through to the
	// opaque placeholder exactly as before.
	if ( !ip_reentrant )
	{
	    std::map<std::string, const std::vector<TokenBase *> *> tok_subst;
	    std::set<std::string> pack_param_names;
	    for ( size_t i = 0; i < td.typeparams.size() && i < arg_tokens.size(); ++i )
	    {
		tok_subst[td.typeparams[i]] = &arg_tokens[i];
		if ( i < td.typeparam_is_pack.size() && td.typeparam_is_pack[i] )
		    pack_param_names.insert(td.typeparams[i]);
	    }
	    std::vector<TokenBase *> body;
	    for ( size_t bi = 0; bi < td.target.size(); ++bi )
	    {
		TokenBase *bt = td.target[bi];
		if ( bt && bt->type() == TokenType::ttIdentifier )
		{
		    const std::string &nm = ((TokenIdent *)bt)->spelling();
		    std::map<std::string, const std::vector<TokenBase *> *>::iterator si =
			tok_subst.find(nm);
		    if ( si != tok_subst.end() )
		    {
			for ( TokenBase *rt : *si->second )
			    body.push_back(rt->clone());
			// A PACK param (`_Args`) in the alias body is followed by a
			// `...` pack-expansion ellipsis (`__construct_helper<_Tp,
			// _Args...>`). The arg slot holds the (single) bound element;
			// drop the trailing `...` so the substituted body is a valid
			// `<A*, A*>`, not `<A*, A*...>` (which derails arg parsing).
			if ( pack_param_names.count(nm)
			  && bi + 3 < td.target.size()
			  && td.target[bi+1] && td.target[bi+1]->id() == TokenID::tkDot
			  && td.target[bi+2] && td.target[bi+2]->id() == TokenID::tkDot
			  && td.target[bi+3] && td.target[bi+3]->id() == TokenID::tkDot )
			    bi += 3;
			continue;
		    }
		}
		body.push_back(bt ? bt->clone() : NULL);
	    }
	    body.push_back(new TokenSemi());

	    size_t saved_diag_count = diagnostics.size();
	    Program::ErrorInfo saved_error = last_error;
	    TokenStream::State saved_tokens = tokens.swap_in(std::move(body));

	    bool pushed_owner_scope = false;
	    if ( td.owner_class )
	    {
		class_scope_stack.push_back(td.owner_class);
		pushed_owner_scope = true;
	    }

	    TokenDataType *resolved = NULL;
	    try
	    {
		TokenBase *head = nextToken();
		resolved = resolve_declared_type_token(head, true, true);
	    }
	    catch ( ... ) { resolved = NULL; }

	    if ( pushed_owner_scope
	      && !class_scope_stack.empty()
	      && class_scope_stack.back() == td.owner_class )
		class_scope_stack.pop_back();

	    tokens.swap_back(std::move(saved_tokens));
	    if ( !resolved )
	    {
		diagnostics.resize(saved_diag_count);
		last_error = saved_error;
		// A NON-DEPENDENT (concrete-args) alias use whose body failed to
		// resolve is a genuine SFINAE substitution failure — e.g.
		// `enable_if_t<false,T>`, where `enable_if<false,T>` has no
		// `::type`. Return NULL so the enclosing fn-template candidate's
		// return-type resolution fails and the candidate is discarded
		// ([temp.deduct]/8), exactly as clang's SubstType returns a null
		// QualType on the absent-`::type` case. Caching an opaque
		// placeholder instead (below) masks the failure and made madc
		// bind the SFINAE-removed overload (the `__relocate_a_1` memmove
		// overload for a non-trivially-relocatable element). A genuinely
		// dependent use (an arg still names an unbound template parameter)
		// keeps the opaque placeholder below — correct for a dependent
		// surface that resolves later.
		if ( alias_use_args_all_concrete(td, arg_tokens) )
		    return NULL;
	    }
	    else
		return use_site_type_token(resolved, tb);
	}

	std::string mangled = tname;
	std::string canon = td.defining_namespace.empty() ? std::string()
			  : (td.defining_namespace + "::");
	canon += tname + "<";
	for ( size_t i = 0; i < args.size(); ++i )
	{
	    mangled += "_" + canonical_arg_key_fragment(arg_tokens[i], args[i]);
	    if ( i )
		canon += ",";
	    canon += args[i];
	}
	canon += ">";

	flat_datatype_map_iter have = datatype_map.find(mangled);
	if ( have != datatype_map.end() )
	    return use_site_type_token((TokenDataType *)(*have), tb);

	DataDefCLASS *fwd = new DataDefCLASS(mangled, 0, DataType::dtRESERVED);
	fwd->is_dependent_placeholder = true;
	fwd->has_dependent_surface = true;
	fwd->canonical_cpp_spelling = canon;
	struct_map[mangled] = fwd;
	TokenDataType *tdt = new TokenDataType(mangled.c_str(), *fwd);
	datatype_map[mangled] = tdt;
	if ( !td.defining_namespace.empty() )
	    namespace_datatype_map[td.defining_namespace][mangled] = tdt;
	return use_site_type_token(tdt, tb);
    }

    nextToken(); // consume '<'
    std::vector<TokenDataType *> args;
    std::vector<std::string> arg_spellings;
    std::map<std::string, TokenDataType *> subst;
	for (;;)
	{
	    TokenBase *at = nextToken();
	    std::string cv_spelling;
	    at = consume_template_type_arg_qualifiers(at, cv_spelling);
	    (void)cv_spelling;
	    TokenDataType *adt = resolve_declared_type_token(at, true, true);
	    if ( !adt )
		Throw(at) << "Expecting a type argument to " << tname << "<>" << flush;
	adt = fold_template_arg_declarator(adt, at);
	args.push_back(adt);
	arg_spellings.push_back(template_type_arg_spelling(adt, cv_spelling));
	TokenBase *sep = nextToken();
	if ( sep->id() == TokenID::tkComma )
	    continue;
	if ( consume_template_close(sep) )
	    break;
	Throw(sep) << "Expecting ',' or '>' in " << tname << "<...>" << flush;
    }
    if ( args.size() > td.typeparams.size() )
	Throw(tb) << tname << "<> expects " << td.typeparams.size()
		      << " type argument(s), got " << args.size() << flush;
    for ( size_t i = 0; i < args.size(); ++i )
	subst[td.typeparams[i]] = args[i];
    while ( args.size() < td.typeparams.size() )
    {
	size_t ai = args.size();
	if ( ai >= td.typeparam_defaults.size()
	  || td.typeparam_defaults[ai].empty() )
	    Throw(tb) << tname << "<> expects " << td.typeparams.size()
			  << " type argument(s), got " << args.size() << flush;
	std::vector<TokenBase *> inj;
	for ( TokenBase *bt : td.typeparam_defaults[ai] )
	{
	    if ( bt->type() == TokenType::ttIdentifier )
	    {
		const std::string &s = ((TokenIdent *)bt)->spelling();
		std::map<std::string, TokenDataType *>::iterator si = subst.find(s);
		if ( si != subst.end() )
		{
		    inj.push_back(si->second->clone());
		    continue;
		}
	    }
	    inj.push_back(bt->clone());
	}
	inj.push_back(new TokenSemi());
	for ( std::vector<TokenBase *>::reverse_iterator it = inj.rbegin();
	      it != inj.rend(); ++it )
	    pushToken(*it);
	TokenBase *dtok = nextToken();
	std::string cv_spelling;
	dtok = consume_template_type_arg_qualifiers(dtok, cv_spelling);
	(void)cv_spelling;
	TokenDataType *adt = resolve_declared_type_token(dtok, true, true);
	if ( !adt )
	    Throw(dtok ? dtok : tb) << "Could not resolve default template argument for "
					<< td.typeparams[ai] << " in "
					<< tname << "<>" << flush;
	if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
	    nextToken();
	args.push_back(adt);
	arg_spellings.push_back(template_type_arg_spelling(adt, cv_spelling));
	subst[td.typeparams[ai]] = adt;
    }

    std::vector<TokenBase *> inj;
    for ( TokenBase *bt : td.target )
    {
	if ( bt->type() == TokenType::ttIdentifier )
	{
	    const std::string &s = ((TokenIdent *)bt)->spelling();
	    std::map<std::string, TokenDataType *>::iterator si = subst.find(s);
	    if ( si != subst.end() )
	    {
		inj.push_back(si->second->clone());
		continue;
	    }
	}
	inj.push_back(bt->clone());
    }
    TokenSemi *alias_sentinel = new TokenSemi();
    inj.push_back(alias_sentinel);
    for ( std::vector<TokenBase *>::reverse_iterator it = inj.rbegin();
	  it != inj.rend(); ++it )
	pushToken(*it);

    bool pushed_owner_scope = false;
    if ( td.owner_class )
    {
	class_scope_stack.push_back(td.owner_class);
	pushed_owner_scope = true;
    }

    TokenBase *head = nextToken();
    TokenDataType *resolved = resolve_declared_type_token(head, true, true);
    bool have_sentinel = false;
    for ( size_t si = 0; si < tokens.size(); ++si )
	if ( tokens[si] == alias_sentinel )
	{
	    have_sentinel = true;
	    break;
	}
    if ( have_sentinel )
    {
	while ( peekToken() && peekToken() != alias_sentinel )
	    nextToken();
	if ( peekToken() == alias_sentinel )
	    nextToken();
    }
    else if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
	nextToken();

    if ( pushed_owner_scope
      && !class_scope_stack.empty()
      && class_scope_stack.back() == td.owner_class )
	class_scope_stack.pop_back();

    // FALLBACK: the body failed to resolve in the CALLER's context, but it was
    // written in the alias's DEFINING namespace and may reference a sibling
    // member UNQUALIFIED (`getvt = typename midalias<T>::value_type;` where the
    // sibling alias `midalias` is in the same namespace). When this alias is
    // reached via a QUALIFIED use from outside (`foo::getvt<X>`) that namespace
    // is not lexically active, so the sibling was undeclared. Retry ONCE with
    // the defining namespace activated — strictly additive (only on a prior
    // failure), so it cannot change any resolution that already succeeded.
    // Real trigger: the std::__detail `iter_value_t`/`__iter_traits` alias chain
    // pulled by reverse_iterator at --std=c++20.
    if ( !resolved && !td.defining_namespace.empty()
      && current_namespace() != td.defining_namespace )
    {
	std::vector<TokenBase *> inj2;
	for ( TokenBase *bt : td.target )
	{
	    if ( bt->type() == TokenType::ttIdentifier )
	    {
		const std::string &s = ((TokenIdent *)bt)->spelling();
		std::map<std::string, TokenDataType *>::iterator si = subst.find(s);
		if ( si != subst.end() )
		{
		    inj2.push_back(si->second->clone());
		    continue;
		}
	    }
	    inj2.push_back(bt->clone());
	}
	TokenSemi *sentinel2 = new TokenSemi();
	inj2.push_back(sentinel2);
	for ( std::vector<TokenBase *>::reverse_iterator it = inj2.rbegin();
	      it != inj2.rend(); ++it )
	    pushToken(*it);

	bool po2 = false;
	if ( td.owner_class )
	{ class_scope_stack.push_back(td.owner_class); po2 = true; }
	namespace_stack.push_back(td.defining_namespace);

	TokenBase *head2 = nextToken();
	try { resolved = resolve_declared_type_token(head2, true, true); }
	catch ( ... ) { resolved = NULL; }

	if ( !namespace_stack.empty()
	  && namespace_stack.back() == td.defining_namespace )
	    namespace_stack.pop_back();
	if ( po2 && !class_scope_stack.empty()
	  && class_scope_stack.back() == td.owner_class )
	    class_scope_stack.pop_back();

	bool hs2 = false;
	for ( size_t si = 0; si < tokens.size(); ++si )
	    if ( tokens[si] == sentinel2 ) { hs2 = true; break; }
	if ( hs2 )
	{
	    while ( peekToken() && peekToken() != sentinel2 )
		nextToken();
	    if ( peekToken() == sentinel2 )
		nextToken();
	}
	else if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
	    nextToken();

	if ( resolved )
	    return use_site_type_token(resolved, tb);
    }

    if ( !resolved && td.owner_class
      && class_has_unresolved_dependent_surface(td.owner_class) )
    {
	std::string member_fragment = tname;
	std::string owner_spelling = td.owner_class->canonical_cpp_spelling.empty()
				   ? td.owner_class->name
				   : td.owner_class->canonical_cpp_spelling;
	std::string canon = owner_spelling + "::" + tname + "<";
	for ( size_t ai = 0; ai < arg_spellings.size(); ++ai )
	{
	    member_fragment += "_" + canonical_arg_key_fragment(
		std::vector<TokenBase *>(), arg_spellings[ai]);
	    if ( ai )
		canon += ",";
	    canon += arg_spellings[ai];
	}
	canon += ">";
	std::string dep_name = td.owner_class->name + "__"
			     + sanitize_template_fragment(member_fragment);
	DataDefCLASS *dep = materialize_opaque_class_type(dep_name, canon);
	if ( dep )
	{
	    dep->has_dependent_surface = true;
	    return make_alias_type_token(dep_name, dep, tb);
	}
    }

    return resolved ? use_site_type_token(resolved, tb) : NULL;
}

void Program::complete_pending_template_instantiations(const std::string &class_name)
{
    std::map<std::string, std::vector<Program::PendingTemplateInstantiation>>::iterator pi =
	pending_template_instantiations.find(class_name);
    if ( pi == pending_template_instantiations.end() )
	return;
    if ( !template_with_body(class_name) )
	return;

    std::vector<Program::PendingTemplateInstantiation> pending = pi->second;
    for ( size_t i = 0; i < pending.size(); ++i )
    {
	flat_datatype_map_iter have = datatype_map.find(pending[i].mangled_name);
	if ( have == datatype_map.end()
	  || !is_incomplete_template_class_type((TokenDataType *)(*have)) )
	    continue;
	if ( template_completion_requested.find(pending[i].mangled_name)
	  == template_completion_requested.end() )
	    continue;

	std::vector<TokenBase *> toks;
	toks.push_back(new TokenLT());
	for ( size_t ai = 0; ai < pending[i].args.size(); ++ai )
	{
	    if ( ai )
		toks.push_back(new TokenComma());
	    toks.push_back(pending[i].args[ai]->clone());
	}
	toks.push_back(new TokenGT());
	for ( std::vector<TokenBase *>::reverse_iterator it = toks.rbegin();
	      it != toks.rend(); ++it )
	    pushToken(*it);

	TokenIdent fake_name(class_name.c_str());
	instantiate_template_use(class_name, &fake_name);
    }
}

bool Program::request_template_instantiation_completion(const std::string &mangled_name)
{
    template_completion_requested.insert(mangled_name);
    for ( std::map<std::string, std::vector<Program::PendingTemplateInstantiation>>::iterator pi =
	      pending_template_instantiations.begin();
	  pi != pending_template_instantiations.end(); ++pi )
    {
	for ( size_t i = 0; i < pi->second.size(); ++i )
	{
	    if ( pi->second[i].mangled_name != mangled_name )
		continue;
	    complete_pending_template_instantiations(pi->first);
	    return true;
	}
    }
    return false;
}

TokenDataType *Program::resolve_typename_type_token(TokenBase *first,
						  bool allow_lazy_types,
						  TokenBase *typename_tb)
{
    if ( !first )
	Throw(typename_tb) << "Expecting qualified type after 'typename'" << flush;
    if ( first->id() == TokenID::tkNS )
    {
	TokenBase *head = nextToken();
	TokenDataType *resolved =
	    resolve_declared_type_token(head, true, allow_lazy_types);
	return resolved;
    }

    TokenDataType *owner_type = NULL;
    if ( is_contextual_identifier_token(first)
      && peekToken() && peekToken()->id() == TokenID::tkLT )
    {
	std::string first_name = contextual_identifier_name(first);
	for ( std::vector<DataDefCLASS *>::reverse_iterator it =
		  class_scope_stack.rbegin();
	      it != class_scope_stack.rend(); ++it )
	{
	    if ( !*it )
		continue;
	    // Member-TYPE chain head: allow a concrete trailing-type-pack template to
	    // really instantiate so a subsequent `::member` reads an evaluated member.
	    bool saved_vri = allow_variadic_real_inst;
	    allow_variadic_real_inst = true;
	    owner_type = instantiate_template_id(first_name, first,
						std::string(), *it);
	    allow_variadic_real_inst = saved_vri;
	    if ( owner_type )
		break;
	}
    }
    if ( !owner_type )
	owner_type = resolve_declared_type_token(first, true, allow_lazy_types, false);
    if ( !owner_type )
	return NULL;
    DataDefCLASS *owner = dynamic_cast<DataDefCLASS *>(&owner_type->definition);
    if ( !owner )
	return NULL;
    if ( is_incomplete_class_datadef(owner) )
    {
	request_template_instantiation_completion(owner->name);
	flat_datatype_map_iter refreshed = datatype_map.find(owner->name);
	if ( refreshed != datatype_map.end() )
	    owner = dynamic_cast<DataDefCLASS *>(&(*refreshed)->definition);
	if ( !owner )
	    return NULL;
    }

    while ( peekToken() && peekToken()->id() == TokenID::tkNS )
    {
	if ( is_incomplete_class_datadef(owner) )
	{
	    request_template_instantiation_completion(owner->name);
	    flat_datatype_map_iter refreshed = datatype_map.find(owner->name);
	    if ( refreshed != datatype_map.end() )
		owner = dynamic_cast<DataDefCLASS *>(&(*refreshed)->definition);
	    if ( !owner )
		return NULL;
	}
	nextToken(); // consume ::
	TokenBase *member_tb = nextToken();
	if ( member_tb && member_tb->id() == TokenID::tkTEMPLATE )
	    member_tb = nextToken();
	if ( !member_tb || !is_contextual_identifier_token(member_tb) )
	    Throw(member_tb ? member_tb : typename_tb)
		<< "Expecting member type after '::' in typename" << flush;
	std::string member_name = contextual_identifier_name(member_tb);
	if ( peekToken() && peekToken()->id() == TokenID::tkLT )
	{
	    if ( TokenDataType *inst =
		    instantiate_template_id(member_name, member_tb,
					    std::string(), owner) )
	    {
		owner = dynamic_cast<DataDefCLASS *>(&inst->definition);
		if ( !owner )
		    return inst;
		if ( !peekToken() || peekToken()->id() != TokenID::tkNS )
		    return inst;
		continue;
	    }
	    skip_template_id_suffix();
	}

	DataDef *alias_dd = resolve_class_type_alias(owner, member_name);
	if ( !alias_dd && class_allows_opaque_member_type(owner) )
	    alias_dd = materialize_dependent_member_type(owner, member_name);
	if ( !alias_dd )
	    return NULL;
	if ( !peekToken() || peekToken()->id() != TokenID::tkNS )
	    return make_alias_type_token(member_name, alias_dd, member_tb);
	owner = dynamic_cast<DataDefCLASS *>(alias_dd);
	if ( !owner )
	    return NULL;
    }

    return owner_type;
}

TokenDataType *Program::resolve_class_member_type_chain(DataDefCLASS *owner,
						      TokenBase *owner_tb)
{
    if ( !owner || !peekToken() || peekToken()->id() != TokenID::tkNS )
	return NULL;

    bool first_segment = true;
    while ( peekToken() && peekToken()->id() == TokenID::tkNS )
    {
	if ( is_incomplete_class_datadef(owner) )
	{
	    request_template_instantiation_completion(owner->name);
	    flat_datatype_map_iter refreshed = datatype_map.find(owner->name);
	    if ( refreshed != datatype_map.end() )
		owner = dynamic_cast<DataDefCLASS *>(&(*refreshed)->definition);
	    if ( !owner )
		return NULL;
	}
	// Probe the FIRST segment before consuming anything: in expression
	// position `Type::static_member` must reach the expression parser
	// untouched — descend only when `::name` names a member TYPE (alias,
	// nested class, member template) or the owner admits opaque dependent
	// members. Once a segment is consumed we are committed and the
	// "not a type member" diagnostic below is correct.
	if ( first_segment )
	{
	    TokenBase *probe = tokens.size() > 1 ? tokens[1] : NULL;
	    if ( probe && probe->id() == TokenID::tkTEMPLATE )
		probe = tokens.size() > 2 ? tokens[2] : NULL;
	    if ( !probe || !is_contextual_identifier_token(probe) )
		return NULL;
	    std::string probe_name = contextual_identifier_name(probe);
	    // The opaque-dependent-member escape is deliberately NOT part of
	    // the probe: speculative type resolution (if-condition heads,
	    // expression positions) must not consume `::static_member` of a
	    // dependent-surface class. Committed type contexts that need
	    // opaque materialization (typename ...) run their own loop.
	    // A member ALIAS template (`Owner<...>::type<A,B>`, e.g. libstdc++'s
	    // `__conditional<C>::template type<If,Else>`) is the third member-TYPE
	    // shape the loop body resolves (via instantiate_template_id ->
	    // instantiate_template_alias_use), so the probe must admit it too —
	    // otherwise the chain never descends and the type fails to resolve.
	    if ( !resolve_class_type_alias(owner, probe_name)
	      && !find_template(probe_name, std::string(), owner)
	      && !find_template_alias(probe_name, std::string(), owner) )
		return NULL;
	    first_segment = false;
	}
	nextToken(); // consume ::
	TokenBase *member_tb = nextToken();
	if ( member_tb && member_tb->id() == TokenID::tkTEMPLATE )
	    member_tb = nextToken();
	if ( !member_tb || !is_contextual_identifier_token(member_tb) )
	    Throw(member_tb ? member_tb : owner_tb)
		<< "Expecting member type after '::'" << flush;
	std::string member_name = contextual_identifier_name(member_tb);
	if ( peekToken() && peekToken()->id() == TokenID::tkLT )
	{
	    if ( TokenDataType *inst =
		    instantiate_template_id(member_name, member_tb,
					    std::string(), owner) )
	    {
		owner = dynamic_cast<DataDefCLASS *>(&inst->definition);
		if ( !owner )
		    return inst;
		if ( !peekToken() || peekToken()->id() != TokenID::tkNS )
		    return inst;
		continue;
	    }
	    skip_template_id_suffix();
	}

	DataDef *alias_dd = resolve_class_type_alias(owner, member_name);
	if ( !alias_dd && class_allows_opaque_member_type(owner) )
	    alias_dd = materialize_dependent_member_type(owner, member_name);
	if ( !alias_dd )
	    Throw(member_tb) << "'" << member_name
				 << "' is not a type member" << flush;
	if ( !peekToken() || peekToken()->id() != TokenID::tkNS )
	    return make_alias_type_token(member_name, alias_dd, member_tb);
	owner = dynamic_cast<DataDefCLASS *>(alias_dd);
	if ( !owner )
	    return NULL;
    }

    return NULL;
}

// When a resolved type is a class and a `::` follows (and the caller asked for
// it), descend the member-type chain (`T::member::...`); otherwise hand back
// the type unchanged. The one seam every resolve_declared_type_token branch
// uses — template-id instantiations included — so `Tmpl<Args>::member` works
// wherever a declared type is accepted (typedef, declaration, template arg).
TokenDataType *Program::resolve_member_chain_or_type(TokenDataType *type_tok,
						     TokenBase *tb,
						     bool consume_class_member_chain)
{
    if ( !type_tok )
	return NULL;
    if ( consume_class_member_chain
      && peekToken() && peekToken()->id() == TokenID::tkNS )
	if ( DataDefCLASS *owner =
		dynamic_cast<DataDefCLASS *>(&type_tok->definition) )
	    if ( TokenDataType *member =
		    resolve_class_member_type_chain(owner, tb) )
		return member;
    return type_tok;
}

TokenDataType *Program::resolve_declared_type_token(TokenBase *tb,
						  bool consume_ns_tokens,
						  bool allow_lazy_types,
						  bool consume_class_member_chain)
{
    if ( !tb )
	return NULL;
    if ( tb->type() == TokenType::ttDataType )
    {
	if ( peekToken() && peekToken()->id() == TokenID::tkLT )
	{
	    std::string tname = ((TokenDataType *)tb)->spelling();
	    if ( TokenDataType *inst = instantiate_template_id(tname, tb) )
		return resolve_member_chain_or_type(inst, tb,
						    consume_class_member_chain);
	}
	return resolve_member_chain_or_type((TokenDataType *)tb, tb,
					    consume_class_member_chain);
    }
    if ( tb->id() == TokenID::tkCLASS
      || tb->id() == TokenID::tkSTRUCT
      || tb->id() == TokenID::tkUNION )
    {
	TokenBase *name_tb = nextToken();
	if ( !name_tb || !is_contextual_identifier_token(name_tb) )
	{
	    Throw(name_tb ? name_tb : tb)
		<< "Expecting type name after elaborated type specifier" << flush;
	}
	if ( TokenDataType *tdt = resolve_declared_type_token(name_tb,
		consume_ns_tokens, allow_lazy_types) )
	    return tdt;
	return NULL;
    }
    if ( !is_contextual_identifier_token(tb) )
	return NULL;

    std::string tname = contextual_identifier_name(tb);
    if ( tname == "typename" )
	return resolve_typename_type_token(nextToken(),
					   allow_lazy_types, tb);
    if ( is_decltype_identifier(tname) )
    {
	if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	    return NULL;
	nextToken(); // consume '('
	TokenBase *expr_head = nextToken();
	if ( !expr_head )
	    Throw(tb) << "Expecting expression in decltype(...)" << flush;
	// The decltype operand is UNEVALUATED: entities it names are not ODR-used,
	// so template-call bodies must not be instantiated (declval's "must not be
	// used!" body). The depth guard suppresses body instantiation in parseCallFunc
	// for this operand and every nested call within it; the return type is still
	// resolved. RAII-restore so an exception mid-parse cannot leave it raised.
	++unevaluated_operand_depth;
	TokenBase *expr = NULL;
	try { expr = parseExpression(expr_head, true); }
	catch ( ... ) { --unevaluated_operand_depth; throw; }
	--unevaluated_operand_depth;
	TokenBase *close = nextToken();
	if ( !close || close->id() != TokenID::tkClBrk )
	    Throw(close ? close : tb) << "Expecting ')' after decltype(...)" << flush;
	DataDef *dd = expr ? expr->datadef() : NULL;
	if ( !dd )
	    Throw(tb) << "Could not resolve decltype(...) operand type" << flush;
	TokenDataType *tdt = new TokenDataType(dd->name.c_str(), *dd);
	tdt->file = tb->file;
	tdt->line = tb->line;
	tdt->column = tb->column;
	return tdt;
    }

    if ( peekToken() && peekToken()->id() == TokenID::tkLT )
    {
	if ( TokenDataType *inst = instantiate_template_id(tname, tb) )
	    return resolve_member_chain_or_type(inst, tb,
						consume_class_member_chain);
	// Nested class template OR member ALIAS template used UNQUALIFIED inside
	// its enclosing class (`_Rb_tree_impl<_Compare> _M_impl;` in the _Rb_tree
	// body; `__pointer<_Key> _M_pkey;` where `template<class _Tp> using
	// __pointer = ...;` is a member alias template, node_handle.h): the call
	// above passes owner_hint=NULL, which find_template / find_template_alias
	// match only against top-level templates, so a member template is missed
	// and a later branch returns the bare template/alias with the '<...>' left
	// unconsumed. Retry with each active class scope as the owner_hint so the
	// member template (class or alias) is found and instantiated.
	// Snapshot the scope pointers: instantiate_template_id below can push the
	// owner onto class_scope_stack (a real variadic-member instantiation now
	// does), reallocating the vector and invalidating a live reverse_iterator —
	// the next deref then segfaults. The DataDefCLASS objects outlive the call,
	// so a copy of the pointers is safe to iterate.
	if ( template_map.count(tname) || template_alias_map.count(tname) )
	{
	    std::vector<DataDefCLASS *> scopes(class_scope_stack.rbegin(),
					       class_scope_stack.rend());
	    for ( DataDefCLASS *sc : scopes )
		if ( TokenDataType *inst =
			instantiate_template_id(tname, tb, "", sc) )
		    return resolve_member_chain_or_type(inst, tb,
							consume_class_member_chain);
	}
    }

    // Unqualified type lookup inside a namespace: C++ searches the enclosing
    // namespace chain (std::pmr -> std) BEFORE the global scope. Namespace-
    // scope aliases live ONLY in namespace_datatype_map (not flat-leaked), so
    // a header class inside namespace std deriving from bare `true_type`
    // resolves here.
    {
	std::string scope = current_namespace();
	while ( !scope.empty() )
	{
	    namespace_datatype_map_t::iterator nti =
		namespace_datatype_map.find(scope);
	    if ( nti != namespace_datatype_map.end() )
	    {
		datatype_map_iter ndmi = nti->find(tname);
		if ( ndmi != nti->end() )
		{
		    TokenDataType *use = (TokenDataType *)ndmi->second->clone();
		    use->file   = tb->file;
		    use->line   = tb->line;
		    use->column = tb->column;
		    return resolve_member_chain_or_type(use, tb,
							consume_class_member_chain);
		}
	    }
	    size_t sp = scope.rfind("::");
	    scope = sp == std::string::npos ? std::string() : scope.substr(0, sp);
	}
    }

    flat_datatype_map_iter dmi = datatype_map.find(tname);
    if ( dmi != datatype_map.end() )
    {
	// dmi->second is the shared prototype token created at the typedef's
	// definition, carrying the definition-site position. Return a clone
	// stamped with this use-site token's position, so a typedef'd-type
	// usage (and any diagnostic or CIR node derived from it) maps to the
	// use site rather than the typedef definition.
	TokenDataType *use = (TokenDataType *)(*dmi)->clone();
	use->file   = tb->file;
	use->line   = tb->line;
	use->column = tb->column;
	return resolve_member_chain_or_type(use, tb, consume_class_member_chain);
    }

    if ( DataDef *class_alias = resolve_current_class_type_alias(tname) )
    {
	TokenDataType *alias_tok = make_alias_type_token(tname, class_alias, tb);
	return resolve_member_chain_or_type(alias_tok, tb,
					    consume_class_member_chain);
    }

    // `Name<ConcreteType>` where Name is a captured (alias or class) template:
    // instantiate (or reuse) the concrete type and return it. Guarded on a
    // following '<', so non-template identifiers are unaffected.
    if ( TokenDataType *inst = instantiate_template_id(tname, tb) )
	return resolve_member_chain_or_type(inst, tb, consume_class_member_chain);

    // `Q1::Q2::...::Name<Args>` where Name is a captured template. The maps are
    // keyed by bare name but declarations are namespace-qualified variants, so
    // keep the qualifier chain as a namespace hint for the shared resolver.
    if ( peekToken() && peekToken()->id() == TokenID::tkNS )
    {
	// tokens[0] is the '::' after tb; a qualifier ident sits at index 1,
	// each followed by '::', until the template name (an ident) is followed
	// by '<'.
	std::string ns_name = tname;
	std::string resolved_ns = resolve_namespace_name_in_scope(ns_name);
	if ( !resolved_ns.empty() )
	    ns_name = resolved_ns;
	size_t j = 1;
	while ( j + 1 < tokens.size()
	     && tokens[j] && is_contextual_identifier_token(tokens[j]) )
	{
	    std::string member_name = contextual_identifier_name(tokens[j]);
	    if ( tokens[j+1]->id() == TokenID::tkLT
	      && template_declared_in_namespace(member_name, ns_name) )
	    {
		for ( size_t k = 0; k < j; k++ )
		    nextToken();               // consume '::' + each (qualifier '::')
		TokenBase *name_tok = nextToken(); // consume the template name
		if ( TokenDataType *inst =
			instantiate_template_id(member_name, name_tok, ns_name) )
		    return resolve_member_chain_or_type(inst, tb,
						consume_class_member_chain);
		break;
	    }
	    if ( tokens[j+1]->id() == TokenID::tkNS )
	    {
		ns_name += "::" + member_name;
		j += 2;                            // skip a namespace qualifier
	    }
	    else
		break;
	}
    }

    if ( TokenDataType *ns_type = resolve_namespaced_type_token(tb, consume_ns_tokens) )
	return resolve_member_chain_or_type(ns_type, tb,
					    consume_class_member_chain);

    if ( !allow_lazy_types || findVariable(tname) )
	return NULL;

    DataDef *dd = lazy_resolve_type(tname);
    if ( !dd )
	return NULL;
    return new TokenDataType(dd->name.c_str(), *dd);
}

DataDef *Program::resolve_type_token_range(const std::vector<TokenBase *> &toks,
					   size_t start, size_t end)
{
    if ( start >= end || end > toks.size() )
	return NULL;
    // Isolated token stream: swap in [start,end) + a ';' sentinel so the
    // canonical resolver (template-ids, `std::`, class-scope typedefs) reads
    // exactly the return type and stops, then restore the live position. The
    // resolver may instantiate a template-id (idempotent/memoized) — that is
    // the desired side effect; everything else is local.
    std::vector<TokenBase *> seq;
    for ( size_t i = start; i < end; ++i )
	if ( toks[i] )
	    seq.push_back(toks[i]);
    seq.push_back(new TokenSemi());
    TokenBase *saved_cur = _cur_token;
    TokenBase *saved_prv = _prv_token;
    TokenStream::State saved_tokens = tokens.swap_in(std::move(seq));
    _cur_token = NULL;
    _prv_token = NULL;
    DataDef *result = NULL;
    try
    {
	TokenDataType *rt = resolve_declared_type_token(nextToken(), true, true);
	if ( rt )
	    result = &rt->definition;
    }
    catch ( ... )
    {
	result = NULL;
    }
    tokens.swap_back(std::move(saved_tokens));
    _cur_token = saved_cur;
    _prv_token = saved_prv;
    return result;
}

static void parse_objtemp_ctor_arguments(Program &pgm, TokenObjTemp *ot,
					 TokenBase *loc, TokenID close_id,
					 const char *close_spelling)
{
    while ( pgm.peekToken() && pgm.peekToken()->id() != close_id )
    {
	ot->ctor_args.push_back(pgm.parseExpression(pgm.nextToken(), true));
	if ( pgm.peekToken() && pgm.peekToken()->id() == TokenID::tkComma )
	    pgm.nextToken();
    }
    if ( !pgm.peekToken() || pgm.peekToken()->id() != close_id )
	pgm.Throw(loc) << "Expected '" << close_spelling
		       << "' after constructor arguments" << flush;
    pgm.nextToken();
}

// Functional construction `T(args)` / `T{args}` / `Template<...>(args)` in expression position:
// build a TokenObjTemp constructing an anonymous temporary of class T. Recognized
// ONLY when the identifier names a CLASS type (a captured template-id we can
// instantiate, or a known class) IMMEDIATELY followed by '(' or '{' -- so ordinary
// function/variable references (resolved earlier in parseExpression) are untouched.
// Returns NULL when it is not a functional construction. General C++ feature; no
// per-class machinery (works for any class, incl. header-defined std:: classes).
// True when the `(` about to be parsed opens a CALL on a callable receiver
// already sitting on exStack — a functor-class object (declares operator()) or
// a function/function-pointer variable — that the `(` binds to directly
// (prevToken is the receiver's own last token: its identifier, or the `)`/`]`
// closing a call/subscript result). In that case `call(Type(...), ...)` is an
// argument list whose first argument is a functional construction, NOT a
// C-style cast `(Type)expr`. Without this guard, a first argument whose leading
// token is a TYPE (e.g. a substituted class template type parameter,
// `_KeyOfValue()(__v)` in std::_Rb_tree::_M_insert_) steals the `(` for the
// cast/compound-literal path, which drops the temp and the trailing arguments.
bool Program::paren_opens_call_on_receiver(std::stack<TokenBase *> &exStack)
{
	if ( exStack.empty() )
		return false;
	TokenBase *pv = prevToken();
	if ( !pv
	  || (pv->type() != TokenType::ttIdentifier
	   && pv->id() != TokenID::tkClBrk
	   && pv->id() != TokenID::tkClSqr) )
		return false;
	TokenBase *recv = exStack.top();
	std::string op_call("operator()");
	DataDefCLASS *rc = operand_object_class(recv);
	if ( rc && rc->findMethod(op_call) )
		return true;
	TokenVar *rv = dynamic_cast<TokenVar *>(recv);
	if ( rv && rv->var.type && rv->var.type->is_function() )
		return true;
	return false;
}

TokenObjTemp *Program::try_parse_functional_ctor(TokenBase *name_tb)
{
	std::string name = contextual_identifier_name(name_tb);
	if ( name.empty() )
		return NULL;
	DataDefCLASS *cdd = NULL;
	if ( peekToken() && peekToken()->id() == TokenID::tkLT
	  && (find_template(name) || find_template_alias(name)) )
	{
		// Template-id: instantiate (consumes `<...>`), then require '('.
		if ( TokenDataType *inst = instantiate_template_id(name, name_tb) )
			cdd = dynamic_cast<DataDefCLASS *>(&inst->definition);
	}
	else
	{
		flat_datatype_map_iter dmi = datatype_map.find(name);
		if ( dmi != datatype_map.end() )
			cdd = dynamic_cast<DataDefCLASS *>(&(*dmi)->definition);
		if ( !cdd )
		{
			datadef_map_iter sdmi = struct_map.find(name);
			if ( sdmi != struct_map.end() )
				cdd = dynamic_cast<DataDefCLASS *>(sdmi->second);
		}
	}
	if ( !cdd )
		return NULL;
	if ( !peekToken()
	  || (peekToken()->id() != TokenID::tkOpBrk
	   && peekToken()->id() != TokenID::tkOpBrc) )
		return NULL;   // a bare type-id, not a construction
	TokenID open_id = peekToken()->id();
	TokenID close_id = open_id == TokenID::tkOpBrc ? TokenID::tkClBrc
						       : TokenID::tkClBrk;
	const char *close_spelling = open_id == TokenID::tkOpBrc ? "}" : ")";
	nextToken(); // consume '(' or '{'
	TokenObjTemp *ot = new TokenObjTemp(cdd);
	ot->file = name_tb->file; ot->line = name_tb->line; ot->column = name_tb->column;
	parse_objtemp_ctor_arguments(*this, ot, name_tb, close_id, close_spelling);
	instantiate_member_ctor_template_for_construction(cdd, ot->ctor_args);
	return ot;
}

TokenBase *Program::parse_functional_type_expression(TokenBase *type_tb,
						   DataDef *type_dd)
{
    if ( !type_tb || !type_dd )
	return NULL;
    if ( !peekToken()
      || (peekToken()->id() != TokenID::tkOpBrk
       && peekToken()->id() != TokenID::tkOpBrc) )
	return NULL;

    TokenID open_id = peekToken()->id();
    TokenID close_id = open_id == TokenID::tkOpBrc ? TokenID::tkClBrc
						   : TokenID::tkClBrk;
    const char *close_spelling = open_id == TokenID::tkOpBrc ? "}" : ")";
    if ( open_id == TokenID::tkOpBrc
      && dynamic_cast<DataDefCLASS *>(type_dd) == NULL )
	return NULL;
    nextToken(); // consume '(' or '{'
    if ( DataDefCLASS *cdd = dynamic_cast<DataDefCLASS *>(type_dd) )
    {
	TokenObjTemp *ot = new TokenObjTemp(cdd);
	ot->file = type_tb->file;
	ot->line = type_tb->line;
	ot->column = type_tb->column;
	parse_objtemp_ctor_arguments(*this, ot, type_tb, close_id, close_spelling);
	instantiate_member_ctor_template_for_construction(cdd, ot->ctor_args);
	return ot;
    }

    TokenBase *expr = NULL;
    if ( peekToken() && peekToken()->id() == TokenID::tkClBrk )
    {
	nextToken(); // value-initialization: T()
	if ( type_dd->is_pointer() )
	{
	    TokenNullptr *np = new TokenNullptr();
	    np->setDataType(type_dd);
	    np->file = type_tb->file;
	    np->line = type_tb->line;
	    np->column = type_tb->column;
	    expr = np;
	}
	else
	{
	    TokenInt *zero = new TokenInt(0);
	    zero->setDataType(type_dd);
	    zero->file = type_tb->file;
	    zero->line = type_tb->line;
	    zero->column = type_tb->column;
	    expr = zero;
	}
    }
    else
    {
	TokenBase *expr_head = nextToken();
	if ( !expr_head )
	    Throw(type_tb) << "Expecting expression in functional cast" << flush;
	expr = parseExpression(expr_head, true, false, false, 0, true);
	if ( !peekToken() || peekToken()->id() != TokenID::tkClBrk )
	    Throw(type_tb) << "Expected ')' after functional cast expression" << flush;
	nextToken(); // consume ')'
    }

    TokenCast *tc = new TokenCast(type_dd, expr);
    tc->file = type_tb->file;
    tc->line = type_tb->line;
    tc->column = type_tb->column;
    return tc;
}

// A type-name usage must carry its own source position, not the position of
// the shared prototype TokenDataType held in datatype_map (which is stamped at
// the typedef's definition site). Return a clone of `proto` positioned at the
// use-site token `at`, so declarations and diagnostics map to the usage.
static TokenDataType *use_site_type_token(TokenDataType *proto, TokenBase *at)
{
    if ( !proto || !at )
	return proto;
    TokenDataType *t = (TokenDataType *)proto->clone();
    t->file = at->file;
    t->line = at->line;
    t->column = at->column;
    return t;
}

static size_t query_datadef_measure(const DataDef *dd, bool want_alignof)
{
    if ( !dd )
	return 0;
    return want_alignof ? dd->alignment() : dd->size;
}

static std::string canonical_builtin_simple_type_name(DataDef *dd)
{
    if ( !dd )
	return "";
    if ( dd == &ddDOUBLE )
	return "double";
    if ( DataDefENUM *enum_dd = dynamic_cast<DataDefENUM *>(dd) )
	return "enum:" + enum_dd->enum_name;
    if ( DataDefCOMPLEX *complex_dd = dynamic_cast<DataDefCOMPLEX *>(dd) )
    {
	std::string elem = canonical_builtin_simple_type_name(complex_dd->element_type);
	return elem.empty() ? "" : "complex(" + elem + ")";
    }
    if ( DataDefPTR *ptr_dd = dynamic_cast<DataDefPTR *>(dd) )
    {
	std::string base = canonical_builtin_simple_type_name(ptr_dd->base_type);
	return base.empty() ? "" : "ptr(" + base + ")";
    }
    if ( DataDefCArray *array_dd = dynamic_cast<DataDefCArray *>(dd) )
    {
	std::string elem = canonical_builtin_simple_type_name(array_dd->element_type);
	return elem.empty() ? "" : "array(" + elem + ")";
    }
    if ( dd->is_struct() )
	return "struct:" + dd->name;

    switch ( dd->rawtype() )
    {
	case DataType::dtVOID: return "void";
	case DataType::dtBOOL: return "bool";
	case DataType::dtUINT8: return "unsigned char";
	case DataType::dtINT8: return "char";
	case DataType::dtUINT16: return "unsigned short";
	case DataType::dtINT16: return "short";
	case DataType::dtUINT24: return "unsigned int24";
	case DataType::dtINT24: return "int24";
	case DataType::dtUINT32: return "unsigned int";
	case DataType::dtINT32: return "int";
	case DataType::dtUINT64: return "unsigned long";
	case DataType::dtINT64: return "long";
	case DataType::dtFLOAT: return "float";
	case DataType::dtDOUBLE: return "double";
	case DataType::dtLDOUBLE: return "long double";
	default: break;
    }
    return dd->name;
}

static void strip_top_level_type_qualifiers(std::string &sig)
{
    static const char *prefixes[] = {"const ", "restrict "};
    bool changed = true;
    while ( changed )
    {
	changed = false;
	for ( size_t i = 0; i < sizeof(prefixes) / sizeof(prefixes[0]); ++i )
	{
	    const char *prefix = prefixes[i];
	    size_t len = strlen(prefix);
	    if ( sig.compare(0, len, prefix) == 0 )
	    {
		sig.erase(0, len);
		changed = true;
	    }
	}
    }
}

bool Program::parse_builtin_types_compatible_operand(TokenBase *type_tb,
						   std::string &sig)
{
    sig.clear();
    if ( !type_tb )
	return false;

    std::string leading_qualifiers;
    while ( is_type_qualifier_token(type_tb) )
    {
	if ( !leading_qualifiers.empty() )
	    leading_qualifiers += ' ';
	leading_qualifiers += ((TokenKeyword *)type_tb)->spelling();
	type_tb = nextToken();
	if ( !type_tb )
	    return false;
    }

    if ( type_tb->type() == TokenType::ttDataType )
    {
	TokenDataType *tdt = (TokenDataType *)type_tb;
	if ( tdt->spelling_is("long double") )
	    sig = "long double";
	else
	    sig = canonical_builtin_simple_type_name(&tdt->definition);
    }
    else if ( type_tb->type() == TokenType::ttIdentifier )
    {
	std::string tname = ((TokenIdent *)type_tb)->spelling();
	if ( is_typeof_identifier(tname) )
	{
	    if ( !skip_expression_whitespace() || peekToken()->id() != TokenID::tkOpBrk )
		return false;
	    nextToken();
	    TokenBase *inner_tb = nextToken();
	    if ( !inner_tb )
		return false;
	    DataDef *inner_dd = NULL;
	    if ( inner_tb->type() == TokenType::ttIdentifier )
	    {
		std::string inner_name = ((TokenIdent *)inner_tb)->spelling();
		Variable *inner_var = findVariable(inner_name);
		if ( inner_var )
		    inner_dd = inner_var->type;
		else
		    inner_dd = resolve_named_datadef(inner_name);
	    }
	    else if ( inner_tb->type() == TokenType::ttDataType )
		inner_dd = &((TokenDataType *)inner_tb)->definition;
	    else if ( inner_tb->type() == TokenType::ttKeyword
		   && (inner_tb->id() == TokenID::tkSTRUCT || inner_tb->id() == TokenID::tkUNION) )
	    {
		TokenBase *tag_tb = nextToken();
		if ( !tag_tb || !is_contextual_identifier_token(tag_tb) )
		    return false;
		inner_dd = resolve_named_datadef(contextual_identifier_name(tag_tb));
	    }
	    if ( !inner_dd )
	    {
		TokenBase *expr = parseExpression(inner_tb, true, false, true, 1);
		inner_dd = expr ? expr->datadef() : NULL;
	    }
	    if ( !inner_dd )
		return false;
	    if ( skip_expression_whitespace() && peekToken()->id() == TokenID::tkClBrk )
		nextToken();
	    else if ( (!curToken() || curToken()->id() != TokenID::tkClBrk)
	       && (!prevToken() || prevToken()->id() != TokenID::tkClBrk) )
		return false;
	    sig = canonical_builtin_simple_type_name(inner_dd);
	}
	else
	{
	    DataDef *dd = resolve_named_datadef(tname);
	    sig = canonical_builtin_simple_type_name(dd);
	}
    }
    else if ( type_tb->type() == TokenType::ttKeyword
	   && (type_tb->id() == TokenID::tkSTRUCT || type_tb->id() == TokenID::tkUNION) )
    {
	TokenBase *tag_tb = nextToken();
	if ( !tag_tb || !is_contextual_identifier_token(tag_tb) )
	    return false;
	sig = (type_tb->id() == TokenID::tkSTRUCT ? "struct:" : "union:")
	    + contextual_identifier_name(tag_tb);
    }
    else if ( type_tb->type() == TokenType::ttKeyword && type_tb->id() == TokenID::tkENUM )
    {
	TokenBase *tag_tb = nextToken();
	if ( !tag_tb || !is_contextual_identifier_token(tag_tb) )
	    return false;
	sig = "enum:" + contextual_identifier_name(tag_tb);
    }
    else
	return false;

    if ( sig.empty() )
	return false;
    if ( !leading_qualifiers.empty() )
	sig = leading_qualifiers + " " + sig;

    bool wrapped = false;
    while ( peekToken() )
    {
	skip_expression_whitespace();
	if ( !peekToken() )
	    break;
	if ( peekToken()->id() == TokenID::tkMul )
	{
	    nextToken();
	    std::string ptr_qualifiers;
	    skip_expression_whitespace();
	    while ( peekToken() && is_type_qualifier_token(peekToken()) )
	    {
		if ( !ptr_qualifiers.empty() )
		    ptr_qualifiers += ' ';
		ptr_qualifiers += ((TokenKeyword *)nextToken())->spelling();
	    }
	    sig = ptr_qualifiers.empty()
		? "ptr(" + sig + ")"
		: ptr_qualifiers + " ptr(" + sig + ")";
	    wrapped = true;
	    continue;
	}
	if ( peekToken()->id() == TokenID::tkOpSqr )
	{
	    nextToken();
	    int depth = 1;
	    while ( depth > 0 )
	    {
		TokenBase *dim_tb = nextToken();
		if ( !dim_tb )
		    return false;
		if ( dim_tb->id() == TokenID::tkOpSqr )
		    ++depth;
		else if ( dim_tb->id() == TokenID::tkClSqr )
		    --depth;
	    }
	    sig = "array(" + sig + ")";
	    wrapped = true;
	    continue;
	}
	break;
    }

    if ( !wrapped )
	strip_top_level_type_qualifiers(sig);
    return true;
}

Variable *Program::resolve_c_identifier(TokenIdent *ident_tb, bool expression_head)
{
	Variable *var = NULL;

	if ( expression_head )
	{
	    // C++ unqualified lookup: a function parameter or block local shadows a
	    // same-named namespace member. Check the function-local scope BEFORE the
	    // namespace so e.g. `perl::substr`'s `length` parameter is not resolved to
	    // the `perl::length` function, or `ruby::delete`'s `chars` parameter to the
	    // `ruby::chars` function (emitting a function pointer where a value is
	    // expected). The namespace still precedes the GLOBAL scope below, so an
	    // unqualified `index` inside `namespace perl` still binds to perl::index,
	    // not the global C `index`. Skipped for an explicit `ns::member` qualifier
	    // (stmt_callee_namespace set) — that names the namespace and must not be
	    // shadowed by a local.
	    TokenCpnd *code = stmt_callee_namespace.empty() && !compounds.empty()
			    ? compounds.top() : NULL;
	    if ( code )
		var = code->findVariableLocal(strpool, ident_tb->spelling());
	    if ( !var )
	    {
		std::string lookup_ns = active_cpp_lookup_namespace();
		if ( !lookup_ns.empty() )
		    var = find_namespace_member_in_scope_chain(lookup_ns,
							       ident_tb->spelling());
	    }
	}
	if ( !var )
	    var = findVariable(ident_tb->spelling());
	if ( !var && !expression_head )
	{
	    std::string lookup_ns = active_cpp_lookup_namespace();
	    if ( !lookup_ns.empty() )
		var = find_namespace_member_in_scope_chain(lookup_ns,
							   ident_tb->spelling());
	}
	return var;
}

static bool read_constant_integer(Variable *var, madc_wide_int &out)
{
    if ( !var || !var->is_constant() || !var->data || !var->type || !var->type->is_integer() )
	return false;
    switch ( var->type->rawtype() )
    {
	case DataType::dtBOOL:   out = *((bool *)var->data) ? 1 : 0; return true;
	case DataType::dtINT8:   out = *((int8_t *)var->data);   return true;
	case DataType::dtUINT8:  out = *((uint8_t *)var->data);  return true;
	case DataType::dtINT16:  out = *((int16_t *)var->data);  return true;
	case DataType::dtUINT16: out = *((uint16_t *)var->data); return true;
	case DataType::dtINT24:  out = *((int16_t *)var->data);  return true;
	case DataType::dtUINT24: out = *((uint16_t *)var->data); return true;
	case DataType::dtINT32:  out = *((int32_t *)var->data);  return true;
	case DataType::dtUINT32: out = *((uint32_t *)var->data); return true;
	// 64-bit reads stay SIGN-CARRIED into the wide fold carrier (an int64_t
	// read even for dtUINT64): identical bits and identical fold results to
	// the historical int64 evaluator for every ≤64-bit program. See the
	// madc_wide_int typedef note (datadef.h).
	case DataType::dtINT64:  out = *((int64_t *)var->data);  return true;
	case DataType::dtUINT64: out = *((int64_t *)var->data);  return true;
	case DataType::dtINT128:  out = *((madc_wide_int *)var->data); return true;
	case DataType::dtUINT128: out = (madc_wide_int)*((madc_wide_uint *)var->data); return true;
	default:
	    return false;
    }
}

static void copy_token_location(TokenBase *dst, TokenBase *src)
{
    if ( !dst || !src )
	return;
    dst->file = src->file;
    dst->line = src->line;
    dst->column = src->column;
}

TokenBase *Program::make_expression_context_literal(const madc::value &resolved,
						  TokenBase *src)
{
    TokenBase *tb = NULL;

    switch ( resolved.type() )
    {
	case madc::value::kind::boolean:
	    tb = new TokenInt(resolved.as_boolean() ? 1 : 0);
	    break;
	case madc::value::kind::integer:
	    tb = new TokenInt(resolved.as_integer());
	    break;
	case madc::value::kind::real:
	    tb = new TokenReal(resolved.as_real());
	    break;
	case madc::value::kind::string:
	{
	    std::string literal = resolved.as_string();
	    Variable *literal_var = addLiteral(literal);
	    if ( !literal_var )
		return NULL;
	    tb = new TokenVar(*literal_var);
	    break;
	}
	default:
	    return NULL;
    }

    copy_token_location(tb, src);
    return tb;
}

bool Program::resolve_integer_constant(TokenBase *tb, madc_wide_int &out)
{
    if ( !tb )
	return false;
    if ( tb->type() == TokenType::ttInteger )
    {
	// wival(): the full 128-bit value for a semantically wide constant
	// (parser-folded, ddINT128/ddUINT128-typed); the plain (or
	// gcc-canon-truncated) 64-bit value for everything else.
	out = tb->wival();
	return true;
    }
    if ( tb->type() == TokenType::ttChar )
    {
	out = ((TokenChar *)tb)->get();
	return true;
    }
    // Also accept contextual-identifier keywords (`class`, `try`, `catch`,
    // etc.) as integer constants when they resolve to one — this lets
    // `case class:` work for an enum that has `class` as one of its tags.
    std::string name;
    if ( tb->type() == TokenType::ttIdentifier )
	name = ((TokenIdent *)tb)->spelling();
    else if ( is_contextual_identifier_token(tb) )
	name = contextual_identifier_name(tb);
    else
	return false;
    // Scoped-enum constant in a constant expression: `Tag::Value` (e.g. a
    // `case Color::Green:` label). The enumerators live in the tag's
    // pseudo-namespace (see TokenENUM::parse), so resolve through it. Keep this
    // probe transactional: `ns::Tmpl<...>::member` also starts with a namespace
    // name, and the qualified-member constant folder below must see the intact
    // token chain when this narrow enum lookup does not resolve.
    if ( peekToken() && peekToken()->id() == TokenID::tkNS )
    {
	TokenStream::Pos saved_tokens = tokens.savepos();
	TokenBase *saved_cur = _cur_token;
	TokenBase *saved_prv = _prv_token;
	namespace_map_t::iterator nsi = namespace_map.find(name);
	if ( nsi != namespace_map.end() )
	{
	    nextToken(); // consume '::'
	    TokenBase *member_tb = nextToken();
	    if ( member_tb && is_contextual_identifier_token(member_tb) )
	    {
		std::string member = contextual_identifier_name(member_tb);
		variable_map_iter vmi = nsi->second.find(member);
		if ( vmi != nsi->second.end()
		  && read_constant_integer(vmi->second, out) )
		    return true;
	    }
	    tokens = saved_tokens;
	    _cur_token = saved_cur;
	    _prv_token = saved_prv;
	    if ( _cur_token )
	    {
		TokenBase::_parse_file = _cur_token->file;
		TokenBase::_parse_line = _cur_token->line;
		TokenBase::_parse_column = _cur_token->column;
	    }
	    return false;
	}
	return false;
    }
    Variable *var = findVariable(name);
    return read_constant_integer(var, out);
}

static bool is_named_cpp_cast(const std::string &name);
static bool datadef_involves_placeholder(DataDef *dd);

static madc_wide_int apply_integer_cast_value(DataDef *cast_dd, madc_wide_int val,
					      bool force_unsigned = false)
{
    if ( !cast_dd )
	return val;
    bool is_unsigned = force_unsigned || cast_dd->is_unsigned();
    int sz = cast_dd->size;
    if ( sz == 1 )
	return is_unsigned ? (madc_wide_int)(uint8_t)val : (madc_wide_int)(int8_t)val;
    if ( sz == 2 )
	return is_unsigned ? (madc_wide_int)(uint16_t)val : (madc_wide_int)(int16_t)val;
    if ( sz == 4 )
	return is_unsigned ? (madc_wide_int)(uint32_t)val : (madc_wide_int)(int32_t)val;
    // 8-byte cast truncates the wide carrier to 64 bits SIGN-CARRIED (even for
    // unsigned long): identical bits and identical fold results to the
    // historical int64 evaluator; `(long)((__int128)1 << 64)` folds to 0.
    if ( sz == 8 )
	return (madc_wide_int)(int64_t)val;
    // 16-byte cast is the identity on the carrier: (__int128)x re-signs a
    // 64-bit value correctly (already sign-carried); (unsigned __int128)x has
    // the same 128-bit pattern.
    return val;
}

madc_wide_int Program::parse_constant_named_cpp_cast(TokenBase *cast_tb,
						     const std::string &cast_name)
{
    if ( !peekToken() || peekToken()->id() != TokenID::tkLT )
	Throw(cast_tb) << "Expecting '<' after " << cast_name << flush;
    nextToken();

    TokenBase *type_tb = nextToken();
    bool force_unsigned = false;
    while ( type_tb && (type_tb->id() == TokenID::tkCONST
	   || type_tb->id() == TokenID::tkVOLATILE
	   || type_tb->id() == TokenID::tkRESTRICT) )
	type_tb = nextToken();
    if ( type_tb && type_tb->type() == TokenType::ttIdentifier
      && ((TokenIdent *)type_tb)->spelling_is("unsigned") )
	force_unsigned = true;

    TokenDataType *tdt = resolve_declared_type_token(type_tb, true, true);
    if ( !tdt )
	Throw(type_tb ? type_tb : cast_tb)
	    << cast_name << " target is not a type" << flush;
    DataDef *cast_dd = &tdt->definition;
    while ( peekToken()
	 && (peekToken()->id() == TokenID::tkMul
	  || peekToken()->id() == TokenID::tkCONST
	  || peekToken()->id() == TokenID::tkVOLATILE
	  || peekToken()->id() == TokenID::tkRESTRICT) )
    {
	TokenBase *pt = nextToken();
	if ( pt->id() == TokenID::tkMul )
	    cast_dd = getPointerType(cast_dd);
    }
    if ( peekToken()
      && (peekToken()->id() == TokenID::tkBand
       || peekToken()->id() == TokenID::tkLand) )
    {
	nextToken();
	cast_dd = getPointerType(cast_dd);
    }
    if ( !peekToken() || peekToken()->id() != TokenID::tkGT )
	Throw(cast_tb) << "Expecting '>' to close "
			   << cast_name << "<...>" << flush;
    nextToken();
    if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	Throw(cast_tb) << "Expecting '(' after "
			   << cast_name << "<...>" << flush;
    nextToken();

    madc_wide_int val = parse_constant_integer_expression();
    TokenBase *close = nextToken();
    if ( !close || close->id() != TokenID::tkClBrk )
	Throw(close ? close : cast_tb)
	    << "Expecting ')' after " << cast_name << "<...>(...)" << flush;
    return apply_integer_cast_value(cast_dd, val, force_unsigned);
}

bool Program::try_parse_constant_functional_cast(TokenBase *type_tb,
						 madc_wide_int &out)
{
    if ( !type_tb || !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	return false;

    DataDef *cast_dd = NULL;
    if ( type_tb->type() == TokenType::ttDataType )
	cast_dd = &static_cast<TokenDataType *>(type_tb)->definition;
    else if ( is_contextual_identifier_token(type_tb) )
    {
	std::string name = contextual_identifier_name(type_tb);
	cast_dd = resolve_current_class_type_alias(name);
	if ( !cast_dd )
	    cast_dd = resolve_named_datadef(name);
    }
    if ( !cast_dd )
	return false;

    nextToken(); // consume '('
    madc_wide_int val = parse_constant_integer_expression();
    TokenBase *close = nextToken();
    if ( !close || close->id() != TokenID::tkClBrk )
	Throw(close ? close : type_tb)
	    << "Expecting ')' after functional cast in constant expression" << flush;
    out = apply_integer_cast_value(cast_dd, val);
    return true;
}

bool Program::is_shared_global_extern_reference(TokenCpnd *code, Variable *var)
{
    return parsing_extern_decl
	&& code
	&& var
	&& var->is_global();
}

static size_t query_fixed_array_sizeof_value(TokenVar *tv, bool want_alignof, bool deref);

TokenBase *Program::parse_parenthesized_expression(const char *context,
						 bool stop_on_closing_paren)
{
    TokenBase *open = nextToken();
    if ( !open || open->id() != TokenID::tkOpBrk )
	Throw(open) << "expecting ( after " << context << flush;

    TokenBase *first = nextToken();
    TokenBase *expr = parseExpression(first, true, false, stop_on_closing_paren, 1);
    if ( !expr )
	Throw(first ? first : open) << "Failed to parse " << context << " expression" << flush;

    return expr;
}

DataDef *Program::resolve_type_query_datadef(TokenBase *type_tb,
					   const std::string &op_name,
					   bool &have_value, size_t &query_value)
{
    bool want_alignof = is_alignof_identifier(op_name);
    DataDef *dd = NULL;
    Variable *var = NULL;

    if ( is_contextual_identifier_token(type_tb) )
    {
	std::string tname = contextual_identifier_name(type_tb);
	var = findVariable(tname);
	if ( var && peekToken()
	  && (peekToken()->id() == TokenID::tkOpSqr
	   || peekToken()->id() == TokenID::tkDot
	   || peekToken()->id() == TokenID::tkDeRef) )
	{
	    TokenBase *chain = parsePostfixChain(type_tb);
	    DataDef *cdd = chain ? chain->datadef() : NULL;
	    if ( !cdd )
		Throw(type_tb) << op_name << ": cannot determine type of expression" << flush;
	    query_value = query_datadef_measure(cdd, want_alignof);
	    if ( !want_alignof )
	    {
		if ( TokenMember *tm = dynamic_cast<TokenMember *>(chain) )
		{
		    if ( tm->is_fixed_array_member() )
		    {
			DataDef *otype = tm->object.type;
			if ( DataDefPTR *opt = dynamic_cast<DataDefPTR *>(otype) )
			    otype = opt->base_type;
			if ( DataDefSTRUCT *sdd = dynamic_cast<DataDefSTRUCT *>(otype) )
			{
			    std::string mname = tm->var.name;
			    query_value *= sdd->m_count(mname);
			}
		    }
		}
	    }
	    have_value = true;
	    return NULL;
	}
	if ( var )
	{
	    query_value = query_datadef_measure(var->type, want_alignof);
	    if ( !want_alignof && var->is_fixed_array() )
		query_value *= var->total_elements();
	    have_value = true;
	    return NULL;
	}
	dd = resolve_current_class_type_alias(tname);
	if ( dd )
	    return dd;
    }

    if ( type_tb->type() == TokenType::ttDataType )
	dd = &((TokenDataType *)type_tb)->definition;
    else if ( type_tb->type() == TokenType::ttIdentifier )
    {
	std::string tname = ((TokenIdent *)type_tb)->spelling();
	var = findVariable(tname);
	if ( var && peekToken()
	  && (peekToken()->id() == TokenID::tkOpSqr
	   || peekToken()->id() == TokenID::tkDot
	   || peekToken()->id() == TokenID::tkDeRef) )
	{
	    TokenBase *chain = parsePostfixChain(type_tb);
	    DataDef *cdd = chain ? chain->datadef() : NULL;
	    if ( !cdd )
		Throw(type_tb) << op_name << ": cannot determine type of expression" << flush;
	    query_value = query_datadef_measure(cdd, want_alignof);
	    if ( !want_alignof )
	    {
		if ( TokenMember *tm = dynamic_cast<TokenMember *>(chain) )
		{
		    if ( tm->is_fixed_array_member() )
		    {
			DataDef *otype = tm->object.type;
			if ( DataDefPTR *opt = dynamic_cast<DataDefPTR *>(otype) )
			    otype = opt->base_type;
			if ( DataDefSTRUCT *sdd = dynamic_cast<DataDefSTRUCT *>(otype) )
			{
			    std::string mname = tm->var.name;
			    query_value *= sdd->m_count(mname);
			}
		    }
		}
	    }
	    have_value = true;
	    var = NULL;
	}
	else if ( var )
	{
	    query_value = query_datadef_measure(var->type, want_alignof);
	    if ( !want_alignof && var->is_fixed_array() )
		query_value *= var->total_elements();
	    have_value = true;
	}
	else
	{
	    dd = resolve_current_class_type_alias(tname);
	    if ( !dd )
		dd = resolve_named_datadef(tname);
	}
    }
    else if ( type_tb->type() == TokenType::ttKeyword
	   && (type_tb->id() == TokenID::tkSTRUCT || type_tb->id() == TokenID::tkUNION) )
    {
	TokenBase *tag_tb = nextToken();
	if ( tag_tb && tag_tb->type() == TokenType::ttIdentifier )
	    dd = resolve_named_datadef(((TokenIdent *)tag_tb)->spelling());
	if ( !dd )
	    Throw(tag_tb) << "Unknown struct/union type in " << op_name << flush;
    }
    else if ( type_tb->type() == TokenType::ttKeyword && type_tb->id() == TokenID::tkENUM )
    {
	// sizeof(enum X) — enums are int-sized
	if ( peekToken() && is_contextual_identifier_token(peekToken()) )
	    nextToken(); // consume tag
	query_value = sizeof(int);
	have_value = true;
    }
    else if ( type_tb->type() == TokenType::ttKeyword && type_tb->id() == TokenID::tkCONST )
    {
	// sizeof(const type) — skip const qualifier
	TokenBase *inner = nextToken();
	return resolve_type_query_datadef(inner, op_name, have_value, query_value);
    }
    else if ( type_tb->id() == TokenID::tkMul )
    {
	TokenBase *deref_tb = nextToken();
	if ( !deref_tb || !is_contextual_identifier_token(deref_tb) )
	    Throw(type_tb) << "Expecting identifier after '*' in " << op_name << flush;
	DataDef *deref_base = NULL;
	if ( peekToken()
	  && (peekToken()->id() == TokenID::tkDot
	   || peekToken()->id() == TokenID::tkDeRef
	   || peekToken()->id() == TokenID::tkOpSqr) )
	{
	    TokenBase *chain = parsePostfixChain(deref_tb);
	    DataDef *cdd = chain ? chain->datadef() : NULL;
	    if ( !cdd )
		Throw(deref_tb) << op_name << "(*expr): cannot determine type" << flush;
	    if ( cdd->is_pointer() )
	    {
		DataDefPTR *cdp = dynamic_cast<DataDefPTR *>(cdd);
		deref_base = (cdp && cdp->base_type) ? cdp->base_type : &ddINT64;
	    }
	    else
		deref_base = cdd;
	}
	else
	{
	    std::string dname = contextual_identifier_name(deref_tb);
	    Variable *dvar = findVariable(dname);
	    if ( !dvar )
		Throw(deref_tb) << "undeclared identifier '" << dname << "' in " << op_name << "(*...)" << flush;
	    if ( dvar->is_fixed_array() )
		deref_base = dvar->type;
	    else if ( dvar->type->is_pointer() )
	    {
		DataDefPTR *dptr = dynamic_cast<DataDefPTR *>(dvar->type);
		deref_base = (dptr && dptr->base_type) ? dptr->base_type : &ddINT64;
	    }
	    else
		Throw(deref_tb) << op_name << "(*" << dname << "): not a pointer or array" << flush;
	}
	query_value = query_datadef_measure(deref_base, want_alignof);
	have_value = true;
    }

    return dd;
}

size_t Program::evaluate_type_query(TokenBase *op_tb, const std::string &op_name)
{
    bool want_alignof = is_alignof_identifier(op_name);

    if ( peekToken() && peekToken()->id() != TokenID::tkOpBrk )
    {
	TokenBase *probe = peekToken();
	bool deref = (probe->id() == TokenID::tkMul);
	if ( deref )
	{
	    nextToken();
	    probe = peekToken();
	}
	// sizeof "literal" — string literal without parens
	if ( probe && probe->type() == TokenType::ttString )
	{
	    TokenStr *ts = static_cast<TokenStr *>(nextToken());
	    return ts->spelling_len() + 1; // include NUL terminator
	}
	if ( !probe || !is_contextual_identifier_token(probe) )
	    Throw(op_tb) << "Expecting '(' or identifier after " << op_name << flush;
	TokenBase *id_tb = nextToken();
	TokenBase *chain = parsePostfixChain(id_tb);
	DataDef *cdd = type_query_chain_datadef(chain);
	if ( !cdd )
	    Throw(id_tb) << op_name << ": cannot determine type of expression" << flush;
	size_t value = query_datadef_measure(cdd, want_alignof);
	if ( deref && cdd->is_pointer() )
	{
	    DataDefPTR *pdd = dynamic_cast<DataDefPTR *>(cdd);
	    if ( pdd && pdd->base_type )
		value = query_datadef_measure(pdd->base_type, want_alignof);
	}
	else if ( TokenVar *tv = dynamic_cast<TokenVar *>(chain) )
	{
	    if ( tv->var.is_fixed_array() )
		value = query_fixed_array_sizeof_value(tv, want_alignof, deref);
	}
	return value;
    }

    if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	Throw(op_tb) << "Expecting '(' after " << op_name << flush;
    nextToken();
    TokenBase *type_tb = nextToken();
    DataDef *dd = NULL;
    size_t value = 0;
    bool have_value = false;

    dd = resolve_type_query_datadef(type_tb, op_name, have_value, value);
    // Fallback: sizeof(expression) — parse as expression, use its type
    bool expr_fallback_consumed_paren = false;
    if ( !have_value && !dd )
    {
	// sizeof("literal") — C string literals are char arrays. Check type_tb
	// before parseExpression transforms it.
	if ( type_tb && type_tb->type() == TokenType::ttString )
	{
	    TokenStr *ts = static_cast<TokenStr *>(type_tb);
	    value = ts->spelling_len() + 1; // include NUL terminator
	    have_value = true;
	    dd = NULL;
	}
	else
	{
	    TokenBase *expr = parseExpression(type_tb, true, false, true, 1);
	    if ( expr && expr->datadef() )
	    {
		dd = expr->datadef();
		// For fixed arrays accessed as expressions, use element size
		if ( TokenVar *tv = dynamic_cast<TokenVar *>(expr) )
		    if ( tv->var.is_fixed_array() )
			value = query_fixed_array_sizeof_value(tv, want_alignof, false);
		if ( !value )
		    value = query_datadef_measure(dd, want_alignof);
		have_value = true;
		dd = NULL; // have_value is set, skip the pointer/array loop below
		expr_fallback_consumed_paren = true;
	    }
	    if ( !have_value )
		Throw(type_tb) << "Unknown type in " << op_name << flush;
	}
    }

    while ( !have_value && peekToken() )
    {
	if ( peekToken()->id() == TokenID::tkMul )
	{
	    nextToken();
	    dd = getPointerType(dd);
	    continue;
	}
	if ( peekToken()->id() == TokenID::tkOpBrk )
	{
	    TokenBase *open = nextToken();
	    TokenBase *star = nextToken();
	    if ( !star || star->id() != TokenID::tkMul )
		Throw(star ? star : open) << "Unsupported parenthesized declarator in " << op_name << flush;
	    dd = getPointerType(dd);
	    TokenBase *close = nextToken();
	    if ( !close || close->id() != TokenID::tkClBrk )
		Throw(close ? close : open) << "Expecting ')' in " << op_name << " function pointer type" << flush;
	    if ( peekToken() && peekToken()->id() == TokenID::tkOpBrk )
	    {
		nextToken();
		int depth = 1;
		while ( depth > 0 )
		{
		    TokenBase *pt = nextToken();
		    if ( !pt )
			Throw(open) << "Unexpected end of input in " << op_name << " function pointer parameter list" << flush;
		    if ( pt->id() == TokenID::tkOpBrk )
			++depth;
		    else if ( pt->id() == TokenID::tkClBrk )
			--depth;
		}
	    }
	    continue;
	}
	break;
    }
    // The expression fallback (sizeof(expr)) already consumed the closing
    // paren via parseExpression's stop_on_closing_paren. Only consume it
    // here for the type-name / variable-name path.
    if ( !expr_fallback_consumed_paren )
    {
	if ( !peekToken() || peekToken()->id() != TokenID::tkClBrk )
	    Throw(type_tb) << "Expecting ')' after " << op_name << " type" << flush;
	nextToken();
    }

    if ( !have_value && dd )
	value = query_datadef_measure(dd, want_alignof);

    return value;
}

// --- Type-trait builtins (__is_class, __is_base_of, …) ------------------------
// libstdc++ <type_traits>/<tuple> implement std::is_* via these compiler
// intrinsics. madc monomorphizes templates (token-substitute + re-parse on use),
// so by the time `__is_class(T)` is parsed the arg is a CONCRETE type — no
// dependent-placeholder handling is needed; evaluate to a bool constant here.
//
// CORRECTNESS-FIRST: only traits madc can answer FAITHFULLY from its DataDef model
// are recognized; the rest fall through to the normal undeclared-identifier path
// (a clear error, never a WRONG bool that would silently corrupt SFINAE). Adding a
// new trait = one entry here + one branch in eval_type_trait — provided madc can
// model it exactly.
// Implement EXACTLY the gcc-13 trait builtins that madc can answer faithfully —
// no more: providing a builtin gcc lacks (e.g. __is_pointer/__is_void, which gcc
// implements in libstdc++, not the compiler) could shadow a library identifier.
static int type_trait_arity(const std::string &name)
{
    if ( name == "__is_same" || name == "__is_base_of"
      || name == "__is_assignable" )
	return 2;
    if ( name == "__is_class" || name == "__is_union" || name == "__is_enum"
      || name == "__has_trivial_destructor" || name == "__is_trivial"
      || name == "__is_empty" || name == "__is_standard_layout"
      || name == "__is_pod" )
	return 1;
    return 0;   // not a supported trait
}

static bool is_type_trait_builtin(const std::string &name)
{
    return type_trait_arity(name) != 0;
}

static bool trait_is_enum(DataDef *dd)
{
    return dynamic_cast<DataDefENUM *>(dd) != NULL;
}
// __is_class: a (non-union) class OR struct. DataDefCLASS derives from
// DataDefSTRUCT, so both match the cast; union_layout separates out unions, and a
// DataDefENUM is not a DataDefSTRUCT so enums are excluded.
static bool trait_is_class(DataDef *dd)
{
    DataDefSTRUCT *s = dynamic_cast<DataDefSTRUCT *>(dd);
    return s && !s->union_layout;
}
static bool trait_is_union(DataDef *dd)
{
    DataDefSTRUCT *s = dynamic_cast<DataDefSTRUCT *>(dd);
    return s && s->union_layout;
}
// __is_empty(T) ([meta.unary.prop]): T is a non-union class with NO non-static
// data members, no virtual functions, no virtual bases, and every base class is
// itself empty. A non-class type is not empty (is_empty<int> = false). libstdc++
// instantiates is_empty<allocator<T>> for its allocator EBO compression, which
// <memory>'s allocator_traits chain drags into the vector reallocation path.
static bool trait_is_empty(DataDef *dd)
{
    // A non-class/union type is not empty (is_empty<int> = false). `members`
    // lives on the DataDefSTRUCT base, so a bare empty struct (DataDefSTRUCT not
    // promoted to DataDefCLASS) is handled too.
    DataDefSTRUCT *s = dynamic_cast<DataDefSTRUCT *>(dd);
    if ( !s || s->union_layout )
	return false;
    if ( !s->members.empty() )		// non-static data members -> not empty
	return false;
    DataDefCLASS *c = dynamic_cast<DataDefCLASS *>(dd);
    if ( !c )
	return true;			// plain empty struct: no bases / virtuals
    if ( c->is_polymorphic() )		// virtual functions -> not empty
	return false;
    if ( c->base_class && !trait_is_empty(c->base_class) )
	return false;
    for ( size_t i = 0; i < c->bases.size(); ++i )
    {
	if ( c->bases[i].is_virtual )	// a virtual base -> not empty
	    return false;
	if ( c->bases[i].base && !trait_is_empty(c->bases[i].base) )
	    return false;
    }
    return true;
}
// __has_trivial_destructor(T) ([class.dtor] triviality, the gcc-13 builtin
// libstdc++'s stl_construct.h dispatches `_Destroy_aux<...>` on): a non-class
// type is trivially destructible; a class is iff it has no user-declared (or
// virtual) destructor AND every direct base and every class-type data member is
// trivially destructible. Pointer members are non-class, hence trivial.
static bool trait_has_trivial_destructor(DataDef *dd)
{
    DataDefCLASS *c = dynamic_cast<DataDefCLASS *>(dd);
    if ( !c )
	return true;
    if ( c->has_user_dtor )
	return false;
    if ( c->base_class && !trait_has_trivial_destructor(c->base_class) )
	return false;
    for ( size_t i = 0; i < c->bases.size(); ++i )
	if ( c->bases[i].base && !trait_has_trivial_destructor(c->bases[i].base) )
	    return false;
    for ( size_t i = 0; i < c->members.size(); ++i )
	if ( c->members[i].second
	  && !trait_has_trivial_destructor(c->members[i].second) )
	    return false;
    return true;
}
// __is_trivial(T) ([basic.types]: a trivially-copyable type with a trivial
// default constructor — the gcc/clang builtin libstdc++'s uninitialized_copy /
// stl_algobase dispatch the memmove optimization on). A non-class type
// (scalar/pointer/enum) is trivial; a class is trivial iff it declares no
// constructor or destructor, is not polymorphic, and every base and class-type
// member is itself trivial. Conservative for the rare user-copy-ctor-only case
// (returns false), which only ever disables an optimization — never miscompiles.
// Verified against g++ and clang++ (int/ptr/POD=1, user-ctor/user-dtor/virtual=0).
static bool trait_is_trivial(DataDef *dd)
{
    DataDefCLASS *c = dynamic_cast<DataDefCLASS *>(dd);
    if ( !c )
	return true;
    if ( c->has_user_ctor || c->has_user_dtor || c->is_polymorphic() )
	return false;
    if ( c->base_class && !trait_is_trivial(c->base_class) )
	return false;
    for ( size_t i = 0; i < c->bases.size(); ++i )
	if ( c->bases[i].base && !trait_is_trivial(c->bases[i].base) )
	    return false;
    for ( size_t i = 0; i < c->members.size(); ++i )
	if ( c->members[i].second && !trait_is_trivial(c->members[i].second) )
	    return false;
    return true;
}
// __is_standard_layout(T) ([class.prop]): a scalar / pointer / enum is standard-
// layout; a class is standard-layout iff it has no virtual functions and no virtual
// bases, all non-static data members share the SAME access control and are each
// standard-layout, every base class is standard-layout, non-static data members
// appear in at most ONE class of the hierarchy, and the first member's type is not a
// base type. The repeated-base-subobject clause ([class.prop] last bullet) is rare
// and not modeled — conservative-true there only relaxes an EBO optimization, never
// miscompiles (mirrors trait_is_trivial's documented conservatism). Verified against
// g++/clang for int/ptr/empty-class (=1) and virtual/mixed-access (=0).
static bool trait_is_standard_layout(DataDef *dd)
{
    DataDefSTRUCT *s = dynamic_cast<DataDefSTRUCT *>(dd);
    if ( !s )
	return true;   // scalar / pointer / enum
    DataDefCLASS *c = dynamic_cast<DataDefCLASS *>(dd);
    if ( c && c->is_polymorphic() )
	return false;   // virtual functions / vptr
    uint32_t acc0 = 0;
    bool have_acc = false;
    for ( size_t i = 0; i < s->members.size(); ++i )
    {
	uint32_t a = i < s->member_access.size() ? s->member_access[i] : 0;
	if ( !have_acc ) { acc0 = a; have_acc = true; }
	else if ( a != acc0 ) return false;          // mixed access control
	if ( s->members[i].second && !trait_is_standard_layout(s->members[i].second) )
	    return false;
    }
    if ( c )
    {
	bool base_has_members = false;
	if ( c->base_class )
	{
	    if ( !trait_is_standard_layout(c->base_class) ) return false;
	    if ( !c->base_class->members.empty() ) base_has_members = true;
	}
	for ( size_t i = 0; i < c->bases.size(); ++i )
	{
	    if ( c->bases[i].is_virtual ) return false;     // virtual base
	    if ( c->bases[i].base )
	    {
		if ( !trait_is_standard_layout(c->bases[i].base) ) return false;
		if ( !c->bases[i].base->members.empty() ) base_has_members = true;
	    }
	}
	if ( base_has_members && !c->members.empty() )
	    return false;    // non-static data members in both a base and the derived class
	if ( !c->members.empty() && c->members[0].second )
	{
	    DataDef *fm = c->members[0].second;        // first member's type != a base type
	    if ( c->base_class && fm == (DataDef *)c->base_class ) return false;
	    for ( size_t i = 0; i < c->bases.size(); ++i )
		if ( c->bases[i].base && fm == (DataDef *)c->bases[i].base ) return false;
	}
    }
    return true;
}
// __is_pod(T) ([basic.types] pre-C++20; a gcc-13 compiler builtin): POD == trivial
// AND standard-layout. libstdc++'s _Rb_tree_impl selects an EBO layout via
// `__is_pod(_Key_compare)` (stl_tree.h), so std::map / std::set need it.
static bool trait_is_pod(DataDef *dd)
{
    return trait_is_trivial(dd) && trait_is_standard_layout(dd);
}
// __is_base_of(B, D): true if B and D name the same class, or B is a (direct or
// indirect) base of class D. Ignores access (matches the intrinsic's semantics —
// std:: layers accessibility on top). Both must be class types.
static bool trait_is_base_of(DataDef *base, DataDef *derived)
{
    DataDefCLASS *b = dynamic_cast<DataDefCLASS *>(base);
    DataDefCLASS *d = dynamic_cast<DataDefCLASS *>(derived);
    if ( !b || !d )
	return false;
    if ( b == d || b->name == d->name )
	return true;
    if ( d->base_class && trait_is_base_of(b, d->base_class) )
	return true;
    for ( size_t i = 0; i < d->bases.size(); ++i )
	if ( d->bases[i].base && trait_is_base_of(b, d->bases[i].base) )
	    return true;
    return false;
}

// One parsed type-argument to a type trait, with the ref/cv qualification that
// `__is_assignable` / `__is_constructible` are sensitive to (`int&` != `int`,
// `const int&` != `int&`). `dd` is the REFERENT type (references are recorded as
// flags, not folded into a DataDefREF) after folding any trailing `*`.
struct TraitTypeArg
{
    DataDef *dd;
    bool is_lref;          // trailing `&`
    bool is_rref;          // trailing `&&`
    bool referent_const;   // leading `const`
    TraitTypeArg() : dd(NULL), is_lref(false), is_rref(false), referent_const(false) {}
    bool same_as(const TraitTypeArg &o) const
    {
	return dd && o.dd && dd->name == o.dd->name
	    && is_lref == o.is_lref && is_rref == o.is_rref
	    && referent_const == o.referent_const;
    }
};

// Tri-state: 1 = yes, 0 = no, -1 = madc cannot determine faithfully (the caller
// raises a clear error rather than emit a WRONG bool — a wrong trait result would
// silently corrupt SFINAE; see the correctness-first note on type_trait_arity).

// Is class `c` copy-/move-assignable? A usable (non-`= delete`) user `operator=`
// makes it assignable; an `operator=` that is `= delete` makes it not. With no
// user `operator=` the implicit one applies: assignable iff every base and every
// object/reference data member is assignable (a reference member deletes the
// implicit copy-assign). Mirrors what class_copy_assign_members synthesizes plus
// the deleted-operator=/reference-member exclusions g++/clang apply.
static int trait_class_assignable(DataDefCLASS *c)
{
    if ( !c )
	return -1;
    for ( Variable *mv : c->methods )
    {
	if ( !mv )
	    continue;
	FuncDef *fd = dynamic_cast<FuncDef *>(mv->type);
	if ( !fd || fd->parameters.size() < 2 )
	    continue;
	bool is_assign = mv->name == "operator="
	    || fd->method_display_name == "operator="
	    || mv->name == c->name + "__operator=";
	if ( !is_assign )
	    continue;
	if ( !fd->is_deleted )
	    return 1;            // a usable copy/move operator= exists
	return 0;                // the (only) operator= is deleted
    }
    // A deleted `operator=` was dropped from `methods` (recorded as a flag).
    if ( c->has_deleted_copy_assign )
	return 0;
    if ( c->base_class )
    {
	int s = trait_class_assignable(c->base_class);
	if ( s != 1 )
	    return s;
    }
    for ( size_t i = 0; i < c->bases.size(); ++i )
    {
	if ( !c->bases[i].base )
	    continue;
	int s = trait_class_assignable(c->bases[i].base);
	if ( s != 1 )
	    return s;
    }
    for ( size_t i = 0; i < c->members.size(); ++i )
    {
	DataDef *m = c->members[i].second;
	if ( !m )
	    continue;
	if ( dynamic_cast<DataDefREF *>(m) )
	    return 0;            // a reference member deletes the implicit copy-assign
	if ( DataDefCLASS *mc = dynamic_cast<DataDefCLASS *>(m) )
	{
	    int s = trait_class_assignable(mc);
	    if ( s != 1 )
		return s;
	}
    }
    return 1;
}

// Is a scalar/pointer/enum lvalue of type `to` assignable from a value of type
// `from`? Same type or two arithmetic types (arithmetic conversions) or a
// pointer from a pointer/null. Anything else madc does not model exactly -> -1.
static int trait_scalar_assignable_from(DataDef *to, DataDef *from)
{
    if ( !to || !from )
	return -1;
    if ( to == from || to->name == from->name )
	return 1;
    if ( to->is_numeric() && from->is_numeric() )
	return 1;
    if ( to->is_pointer() && (from->is_pointer() || from->is_numeric()) )
	return 1;
    return -1;
}

// __is_assignable(To, From): is `declval<To>() = declval<From>()` well-formed?
// (The gcc/clang intrinsic; libstdc++'s std::is_assignable wraps it.)
static int trait_is_assignable(const TraitTypeArg &to, const TraitTypeArg &from)
{
    DataDefCLASS *to_class = dynamic_cast<DataDefCLASS *>(to.dd);
    // A non-class prvalue (no reference) cannot be assigned to; nor can a
    // non-class rvalue reference. A class prvalue/rvalue-ref CAN (member op=).
    if ( !to_class && !to.is_lref )
	return 0;
    if ( !to_class && to.is_rref )
	return 0;
    if ( to.referent_const )
	return 0;
    if ( !to_class )
	return trait_scalar_assignable_from(to.dd, from.dd);
    return trait_class_assignable(to_class);
}

TokenBase *Program::evaluate_type_trait(TokenBase *op_tb, const std::string &name)
{
    int arity = type_trait_arity(name);
    if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	Throw(op_tb) << "Expecting '(' after " << name << flush;
    nextToken(); // consume '('

    std::vector<TraitTypeArg> args;
    for (;;)
    {
	TraitTypeArg a;
	TokenBase *at = nextToken();
	std::string cv_spelling;
	at = consume_template_type_arg_qualifiers(at, cv_spelling);
	a.referent_const = cv_spelling.find("const") != std::string::npos;
	TokenDataType *adt = resolve_declared_type_token(at, true, true);
	if ( !adt )
	    Throw(at ? at : op_tb) << "Expecting a type argument to " << name << flush;
	DataDef *dd = &adt->definition;
	// Fold trailing pointer stars (`__is_pointer(int*)`), mirroring the
	// template-argument parser.
	while ( peekToken() && peekToken()->id() == TokenID::tkMul )
	{
	    nextToken();
	    dd = getPointerType(dd);
	}
	a.dd = dd;
	// Trailing reference (`T&` / `T&&`) — load-bearing for __is_assignable.
	if ( peekToken() && peekToken()->id() == TokenID::tkBand )
	{ nextToken(); a.is_lref = true; }
	else if ( peekToken() && peekToken()->id() == TokenID::tkLand )
	{ nextToken(); a.is_rref = true; }
	args.push_back(a);
	TokenBase *sep = nextToken();
	if ( sep && sep->id() == TokenID::tkComma )
	    continue;
	if ( sep && sep->id() == TokenID::tkClBrk )
	    break;
	Throw(sep ? sep : op_tb) << "Expecting ',' or ')' in " << name << "(...)" << flush;
    }

    if ( (int)args.size() != arity )
	Throw(op_tb) << name << " expects " << arity << " type argument(s), got "
		     << args.size() << flush;

    bool result = false;
    if ( name == "__is_same" )
	result = args[0].same_as(args[1]);
    else if ( name == "__is_enum" )
	result = trait_is_enum(args[0].dd);
    else if ( name == "__is_class" )
	result = trait_is_class(args[0].dd);
    else if ( name == "__is_union" )
	result = trait_is_union(args[0].dd);
    else if ( name == "__is_empty" )
	result = trait_is_empty(args[0].dd);
    else if ( name == "__is_base_of" )
	result = trait_is_base_of(args[0].dd, args[1].dd);
    else if ( name == "__has_trivial_destructor" )
	result = trait_has_trivial_destructor(args[0].dd);
    else if ( name == "__is_trivial" )
	result = trait_is_trivial(args[0].dd);
    else if ( name == "__is_standard_layout" )
	result = trait_is_standard_layout(args[0].dd);
    else if ( name == "__is_pod" )
	result = trait_is_pod(args[0].dd);
    else if ( name == "__is_assignable" )
    {
	int s = trait_is_assignable(args[0], args[1]);
	if ( s < 0 )
	    Throw(op_tb) << "cannot faithfully evaluate __is_assignable(...) for "
			 << "these operand types" << flush;
	result = s != 0;
    }

    TokenInt *ti = new TokenInt(result ? 1 : 0);
    ti->setDataType(&ddBOOL);
    ti->file = op_tb->file;
    ti->line = op_tb->line;
    ti->column = op_tb->column;
    return ti;
}

static bool is_runtime_sized_type(DataDef *dd)
{
    if ( !dd )
	return false;
    if ( DataDefSTRUCT *sdd = dynamic_cast<DataDefSTRUCT *>(dd) )
	return sdd->has_runtime_size();
    if ( DataDefCArray *add = dynamic_cast<DataDefCArray *>(dd) )
	return add->has_runtime_size();
    return false;
}

// A type query whose VALUE is not knowable at parse time: a VLA type (runtime
// value) or a bare template-parameter placeholder (instantiation-time value —
// folding it would bake the placeholder's meaningless size 0 into the Tree-1
// pattern; tsubst expands the deferred TokenTypeQuery's type marker instead).
static bool type_query_size_is_deferred(DataDef *dd)
{
    if ( !dd )
	return false;
    return is_runtime_sized_type(dd) || dd->is_template_param();
}

static TokenBase *make_type_query_token(TokenBase *op_tb, DataDef *dd, bool want_alignof)
{
    TokenBase *result = NULL;
    if ( !type_query_size_is_deferred(dd)
      || (want_alignof && !dd->is_template_param()) )
    {
	TokenInt *ti = new TokenInt((int64_t)query_datadef_measure(dd, want_alignof));
	ti->setDataType(&ddUINT64);
	result = ti;
    }
    else
	result = new TokenTypeQuery(dd, want_alignof);
    result->file = op_tb ? op_tb->file : NULL;
    result->line = op_tb ? op_tb->line : 0;
    result->column = op_tb ? op_tb->column : 0;
    return result;
}

static size_t query_fixed_array_sizeof_value(TokenVar *tv, bool want_alignof, bool deref)
{
    if ( !tv || !tv->var.type )
	return 0;
    size_t value = query_datadef_measure(tv->var.type, want_alignof);
    if ( !want_alignof && !deref )
	value *= tv->var.total_elements();
    return value;
}

static bool try_eval_known_integer(TokenBase *tb, int64_t &out)
{
    if ( !tb )
	return false;
    if ( TokenInt *ti = dynamic_cast<TokenInt *>(tb) )
    {
	out = ti->ival();
	return true;
    }
    if ( TokenChar *tc = dynamic_cast<TokenChar *>(tb) )
    {
	out = tc->ival();
	return true;
    }
    if ( TokenVar *tv = dynamic_cast<TokenVar *>(tb) )
    {
	if ( tv->var.is_constant() )
	{
	    out = tv->var.get<int64_t>();
	    return true;
	}
	return false;
    }
    if ( TokenNeg *tn = dynamic_cast<TokenNeg *>(tb) )
    {
	int64_t rhs = 0;
	if ( try_eval_known_integer(tn->right, rhs) )
	{
	    out = -rhs;
	    return true;
	}
	return false;
    }
    if ( TokenAdd *ta = dynamic_cast<TokenAdd *>(tb) )
    {
	int64_t lhs = 0, rhs = 0;
	if ( try_eval_known_integer(ta->left, lhs) && try_eval_known_integer(ta->right, rhs) )
	{
	    out = lhs + rhs;
	    return true;
	}
	return false;
    }
    if ( TokenSub *ts = dynamic_cast<TokenSub *>(tb) )
    {
	int64_t lhs = 0, rhs = 0;
	if ( try_eval_known_integer(ts->left, lhs) && try_eval_known_integer(ts->right, rhs) )
	{
	    out = lhs - rhs;
	    return true;
	}
	return false;
    }
    return false;
}

TokenBase *Program::materialize_cast_literal_operand(TokenBase *tb)
{
    if ( !tb )
	return tb;
    if ( tb->type() != TokenType::ttString )
	return tb;

    TokenStr *first = static_cast<TokenStr *>(tb);
    std::string literal = first->str;
    bool wide_literal = first->wide;
    while ( peekToken() && peekToken()->type() == TokenType::ttString )
    {
	TokenStr *next = static_cast<TokenStr *>(nextToken());
	if ( wide_literal || next->wide )
	{
	    if ( !wide_literal )
	    {
		std::string converted;
		for ( unsigned char c : literal )
		{
		    converted += (char)c;
		    converted += '\0';
		    converted += '\0';
		    converted += '\0';
		}
		literal = converted;
		wide_literal = true;
	    }
	    if ( next->wide )
		literal += next->str;
	    else
	    {
		for ( unsigned char c : next->str )
		{
		    literal += (char)c;
		    literal += '\0';
		    literal += '\0';
		    literal += '\0';
		}
	    }
	}
	else
	    literal += next->str;
    }

    Variable *var = wide_literal ? addWideLiteral(literal) : addLiteral(literal);
    TokenVar *tv = new TokenVar(*var);
    tv->file = tb->file;
    tv->line = tb->line;
    tv->column = tb->column;
    return tv;
}

static int64_t fixed_array_object_size(const Variable &var)
{
    if ( !var.is_fixed_array() || !var.type || !var.type->size )
	return -1;
    return (int64_t)var.type->size * (int64_t)var.total_elements();
}

static int64_t token_pointer_element_size(TokenBase *tb)
{
    if ( !tb )
	return 1;
    if ( TokenVar *tv = dynamic_cast<TokenVar *>(tb) )
    {
	if ( tv->var.is_fixed_array() && tv->var.type )
	    return tv->var.type->size ? (int64_t)tv->var.type->size : 1;
    }
    if ( TokenMember *tm = dynamic_cast<TokenMember *>(tb) )
    {
	if ( tm->is_fixed_array_member() && tm->var.type )
	    return tm->var.type->size ? (int64_t)tm->var.type->size : 1;
    }
    DataDef *dd = tb->datadef();
    if ( DataDefPTR *pdd = dynamic_cast<DataDefPTR *>(dd) )
	return (pdd->base_type && pdd->base_type->size) ? (int64_t)pdd->base_type->size : 1;
    if ( DataDefCArray *add = dynamic_cast<DataDefCArray *>(dd) )
	return (add->element_type && add->element_type->size) ? (int64_t)add->element_type->size : 1;
    return (dd && dd->size) ? (int64_t)dd->size : 1;
}

static int64_t known_object_size_for_expr(TokenBase *expr, int mode);

static int64_t remaining_object_size(int64_t base_size, int64_t index, int64_t elem_size)
{
    if ( base_size < 0 || index < 0 || elem_size <= 0 )
	return -1;
    int64_t used = index * elem_size;
    if ( used >= base_size )
	return 0;
    return base_size - used;
}

static int64_t known_object_size_for_lvalue(TokenBase *expr, int mode)
{
    if ( !expr )
	return -1;
    if ( TokenVar *tv = dynamic_cast<TokenVar *>(expr) )
    {
	int64_t array_size = fixed_array_object_size(tv->var);
	if ( array_size >= 0 )
	    return array_size;
	return tv->var.type ? (int64_t)tv->var.type->size : -1;
    }
    if ( TokenMember *tm = dynamic_cast<TokenMember *>(expr) )
    {
	if ( tm->is_fixed_array_member() )
	{
	    DataDefSTRUCT *sdd = tm->owner_struct_type();
	    std::string mname = tm->var.name;
	    if ( sdd && tm->var.type )
		return (int64_t)sdd->m_count(mname) * (int64_t)tm->var.type->size;
	}
	return tm->var.type ? (int64_t)tm->var.type->size : -1;
    }
    if ( TokenSubscript *ts = dynamic_cast<TokenSubscript *>(expr) )
    {
	int64_t index = 0;
	if ( !try_eval_known_integer(ts->index, index) )
	    return -1;
	int64_t base_size = -1;
	if ( ts->object.is_fixed_array() )
	    base_size = fixed_array_object_size(ts->object);
	else
	    base_size = ts->object.object_size_hint;
	return remaining_object_size(base_size, index, ts->datadef() ? (int64_t)ts->datadef()->size : 1);
    }
    if ( TokenSubscriptExpr *tse = dynamic_cast<TokenSubscriptExpr *>(expr) )
    {
	int64_t index = 0;
	if ( !try_eval_known_integer(tse->index, index) )
	    return -1;
	int64_t base_size = known_object_size_for_expr(tse->base_expr, mode);
	return remaining_object_size(base_size, index, tse->datadef() ? (int64_t)tse->datadef()->size : 1);
    }
    return expr->datadef() ? (int64_t)expr->datadef()->size : -1;
}

static int64_t known_object_size_for_expr(TokenBase *expr, int mode)
{
    if ( !expr )
	return -1;
    if ( TokenVar *tv = dynamic_cast<TokenVar *>(expr) )
    {
	int64_t array_size = fixed_array_object_size(tv->var);
	if ( array_size >= 0 )
	    return array_size;
	return tv->var.object_size_hint;
    }
    if ( TokenMember *tm = dynamic_cast<TokenMember *>(expr) )
    {
	if ( tm->is_fixed_array_member() )
	{
	    DataDefSTRUCT *sdd = tm->owner_struct_type();
	    std::string mname = tm->var.name;
	    if ( sdd && tm->var.type )
		return (int64_t)sdd->m_count(mname) * (int64_t)tm->var.type->size;
	}
	return tm->var.object_size_hint;
    }
    if ( TokenAddrOf *tao = dynamic_cast<TokenAddrOf *>(expr) )
    {
	int64_t array_size = fixed_array_object_size(tao->var);
	if ( array_size >= 0 )
	    return array_size;
	return tao->var.type ? (int64_t)tao->var.type->size : -1;
    }
    if ( TokenAddrExpr *tae = dynamic_cast<TokenAddrExpr *>(expr) )
	return known_object_size_for_lvalue(tae->expr, mode);
    if ( TokenAdd *ta = dynamic_cast<TokenAdd *>(expr) )
    {
	int64_t offset = 0;
	if ( try_eval_known_integer(ta->right, offset) )
	{
	    int64_t base_size = known_object_size_for_expr(ta->left, mode);
	    return remaining_object_size(base_size, offset, token_pointer_element_size(ta->left));
	}
	if ( try_eval_known_integer(ta->left, offset) )
	{
	    int64_t base_size = known_object_size_for_expr(ta->right, mode);
	    return remaining_object_size(base_size, offset, token_pointer_element_size(ta->right));
	}
	return -1;
    }
    if ( TokenSub *ts = dynamic_cast<TokenSub *>(expr) )
    {
	int64_t offset = 0;
	if ( try_eval_known_integer(ts->right, offset) )
	{
	    int64_t base_size = known_object_size_for_expr(ts->left, mode);
	    return remaining_object_size(base_size, offset, token_pointer_element_size(ts->left));
	}
	return -1;
    }
    if ( TokenTerQ *tt = dynamic_cast<TokenTerQ *>(expr) )
    {
	int64_t true_size = known_object_size_for_expr(tt->true_expr, mode);
	int64_t false_size = known_object_size_for_expr(tt->false_expr, mode);
	if ( true_size < 0 || false_size < 0 )
	    return -1;
	return mode == 1 ? std::min(true_size, false_size)
			 : std::max(true_size, false_size);
    }
    if ( TokenCast *tc = dynamic_cast<TokenCast *>(expr) )
	return known_object_size_for_expr(tc->expr, mode);
    if ( TokenCallFunc *tcf = dynamic_cast<TokenCallFunc *>(expr) )
    {
	if ( (tcf->var.name == "__builtin_alloca" || tcf->var.name == "alloca" || tcf->var.name == "malloc")
	  && tcf->argc() == 1 )
	{
	    int64_t size = 0;
	    if ( try_eval_known_integer(tcf->parameters[0], size) && size >= 0 )
		return size;
	}
    }
    return -1;
}

static void update_pointer_object_size_hints(TokenBase *expr)
{
    if ( !expr )
	return;
    if ( TokenAssign *ta = dynamic_cast<TokenAssign *>(expr) )
    {
	if ( TokenVar *lhs = dynamic_cast<TokenVar *>(ta->left) )
	{
	    if ( lhs->var.type && lhs->var.type->is_pointer() && !lhs->var.is_fixed_array() )
		lhs->var.object_size_hint = known_object_size_for_expr(ta->right, 0);
	}
	update_pointer_object_size_hints(ta->left);
	update_pointer_object_size_hints(ta->right);
	return;
    }
    if ( TokenComma *tc = dynamic_cast<TokenComma *>(expr) )
    {
	update_pointer_object_size_hints(tc->left);
	update_pointer_object_size_hints(tc->right);
	return;
    }
    if ( TokenTerQ *tt = dynamic_cast<TokenTerQ *>(expr) )
    {
	update_pointer_object_size_hints(tt->condition);
	update_pointer_object_size_hints(tt->true_expr);
	update_pointer_object_size_hints(tt->false_expr);
    }
}

TokenBase *Program::materialize_runtime_struct_size_captures(TokenCpnd *code,
							    DataDefSTRUCT *dds, TokenBase *loc)
{
    if ( !code || !dds || !dds->has_runtime_size() )
	return NULL;

    static int runtime_size_capture_counter = 0;
    std::string cap_name = "__vla_type_size_" + std::to_string(runtime_size_capture_counter++);
    Variable *cap_var = addVariable(code, ddUINT64, cap_name, 1, NULL, false);
    TokenDecl *td = new TokenDecl(*cap_var);
    td->file = loc ? loc->file : NULL;
    td->line = loc ? loc->line : 0;
    td->column = loc ? loc->column : 0;

    TokenAssign *assign = new TokenAssign();
    assign->file = td->file;
    assign->line = td->line;
    assign->column = td->column;
    assign->left = new TokenVar(*cap_var);
    assign->right = new TokenTypeQuery(dds, false, false);
    td->initialize = assign;

    dds->runtime_size_expr = new TokenVar(*cap_var);
    return td;
}

// Capture a VLA dimension expression into a hidden uint64 local declared
// just before the VLA variable. Both the heap-allocation count and any
// later sizeof(var) read the capture, so the dimension expression's side
// effects run exactly once and sizeof reflects the declaration-time value
// even when the dimension variable changes afterwards (C99 6.5.3.4p2; gcc
// keeps the VLA bound in a hidden temp the same way). dim_expr is REPLACED
// with a TokenVar referencing the capture; the returned TokenDecl carries
// the original expression as the capture's initializer.
TokenBase *Program::materialize_vla_dim_capture(TokenCpnd *code,
						TokenBase *&dim_expr,
						TokenBase *loc)
{
    if ( !code || !dim_expr )
	return NULL;

    static int vla_dim_capture_counter = 0;
    std::string cap_name = "__madc_vla_dim_" + std::to_string(vla_dim_capture_counter++);
    Variable *cap_var = addVariable(code, ddUINT64, cap_name, 1, NULL, false);
    TokenDecl *td = new TokenDecl(*cap_var);
    td->file = loc ? loc->file : NULL;
    td->line = loc ? loc->line : 0;
    td->column = loc ? loc->column : 0;

    TokenAssign *assign = new TokenAssign();
    assign->file = td->file;
    assign->line = td->line;
    assign->column = td->column;
    assign->left = new TokenVar(*cap_var);
    assign->right = dim_expr;
    td->initialize = assign;

    dim_expr = new TokenVar(*cap_var);
    return td;
}

TokenBase *Program::try_parse_dynamic_type_query(TokenBase *op_tb,
					       const std::string &op_name)
{
    bool want_alignof = is_alignof_identifier(op_name);
    if ( want_alignof )
	return NULL;

    auto consume_simple_named_type = [&](DataDef *dd) -> TokenBase * {
	if ( !type_query_size_is_deferred(dd) )
	    return NULL;
	nextToken();
	return make_type_query_token(op_tb, dd, false);
    };

    if ( peekToken() && peekToken()->id() != TokenID::tkOpBrk )
    {
	TokenBase *probe = peekToken();
	if ( is_contextual_identifier_token(probe) )
	{
	    std::string name = contextual_identifier_name(probe);
	    if ( !findVariable(name) )
	    {
		DataDef *dd = resolve_template_param(name);
		if ( !dd )
		    dd = resolve_named_datadef(name);
		if ( TokenBase *query = consume_simple_named_type(dd) )
		    return query;
	    }
	}
	return NULL;
    }

    if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	return NULL;

    size_t ix = 0;
    if ( ix >= tokens.size() || tokens[ix]->id() != TokenID::tkOpBrk )
	return NULL;
    ++ix;
    if ( ix >= tokens.size() )
	return NULL;

    DataDef *dd = NULL;
    TokenBase *type_tb = tokens[ix];
    if ( type_tb->type() == TokenType::ttDataType )
	dd = &((TokenDataType *)type_tb)->definition;
    else if ( type_tb->type() == TokenType::ttIdentifier )
    {
	std::string name = ((TokenIdent *)type_tb)->spelling();
	if ( !findVariable(name) )
	{
	    dd = resolve_template_param(name);
	    if ( !dd )
		dd = resolve_named_datadef(name);
	}
    }
    else if ( type_tb->type() == TokenType::ttKeyword
	   && (type_tb->id() == TokenID::tkSTRUCT || type_tb->id() == TokenID::tkUNION) )
    {
	++ix;
	if ( ix >= tokens.size() || !is_contextual_identifier_token(tokens[ix]) )
	    return NULL;
	dd = resolve_named_datadef(contextual_identifier_name(tokens[ix]));
    }
    if ( !type_query_size_is_deferred(dd) )
	return NULL;

    TokenBase *open = nextToken();
    (void)open;
    TokenBase *consumed = nextToken();
    if ( !consumed )
	return NULL;
    if ( consumed->type() == TokenType::ttKeyword
      && (consumed->id() == TokenID::tkSTRUCT || consumed->id() == TokenID::tkUNION) )
    {
	TokenBase *tag_tb = nextToken();
	if ( !tag_tb || !is_contextual_identifier_token(tag_tb) )
	    Throw(tag_tb ? tag_tb : consumed) << "Expecting struct/union tag in " << op_name << flush;
    }
    if ( !peekToken() || peekToken()->id() != TokenID::tkClBrk )
	Throw(consumed) << "Expecting ')' after " << op_name << " type" << flush;
    nextToken();
    return make_type_query_token(op_tb, dd, false);
}

// sizeof applied to a VLA VARIABLE (`sizeof(a)` / `sizeof a` where `a` was
// declared `T a[n]`): the result is a runtime value — the product of the
// declaration-time dimension captures (materialize_vla_dim_capture rewrote
// the stored dim expressions to TokenVars over those hidden locals) times
// the element size. Returns NULL without consuming tokens when the operand
// is not a bare VLA variable; the constant path handles everything else.
// alignof never needs this: alignment is a property of the element type.
TokenBase *Program::try_parse_vla_variable_sizeof(TokenBase *op_tb,
						  const std::string &op_name)
{
    if ( is_alignof_identifier(op_name) )
	return NULL;

    bool paren = peekToken() && peekToken()->id() == TokenID::tkOpBrk;
    TokenBase *ident_tb = NULL;
    if ( paren )
    {
	if ( tokens.size() < 3 )
	    return NULL;
	if ( !tokens[1] || !is_contextual_identifier_token(tokens[1])
	  || !tokens[2] || tokens[2]->id() != TokenID::tkClBrk )
	    return NULL;
	ident_tb = tokens[1];
    }
    else
    {
	ident_tb = peekToken();
	if ( !ident_tb || !is_contextual_identifier_token(ident_tb) )
	    return NULL;
    }

    std::string vla_var_name = contextual_identifier_name(ident_tb);
    Variable *v = findVariable(vla_var_name);
    if ( !v || !v->is_vla() || !v->vla_size_expr )
	return NULL;

    // Fresh leaf per use — AST nodes are single-use; the declaration keeps
    // ownership of the stored dim expressions.
    auto dim_leaf = [&](TokenBase *e) -> TokenBase * {
	if ( !e )
	    return NULL;
	if ( TokenVar *tv = dynamic_cast<TokenVar *>(e) )
	{
	    TokenVar *fresh = new TokenVar(tv->var);
	    copy_token_location(fresh, op_tb);
	    return fresh;
	}
	if ( TokenInt *ti = dynamic_cast<TokenInt *>(e) )
	{
	    TokenInt *c = new TokenInt(ti->ival());
	    c->setDataType(&ddUINT64);
	    copy_token_location(c, op_tb);
	    return c;
	}
	return NULL;
    };
    auto mul = [&](TokenBase *l, TokenBase *r) -> TokenBase * {
	TokenMul *m = new TokenMul();
	copy_token_location(m, op_tb);
	m->left = l;
	m->right = r;
	return m;
    };

    TokenBase *total = dim_leaf(v->vla_size_expr);
    if ( !total )
	return NULL;
    DataDef *elem = v->type;
    if ( DataDefPTR *wp = dynamic_cast<DataDefPTR *>(elem) )
	elem = wp->base_type;
    while ( DataDefCArray *c = dynamic_cast<DataDefCArray *>(elem) )
    {
	TokenBase *d;
	if ( c->has_runtime_size() )
	    d = dim_leaf(c->count_expr);
	else
	{
	    TokenInt *ci = new TokenInt((int64_t)c->count);
	    ci->setDataType(&ddUINT64);
	    copy_token_location(ci, op_tb);
	    d = ci;
	}
	if ( !d )
	    return NULL;
	total = mul(total, d);
	elem = c->element_type;
    }
    TokenInt *esz = new TokenInt((int64_t)elem->size);
    esz->setDataType(&ddUINT64);
    copy_token_location(esz, op_tb);
    total = mul(total, esz);

    if ( paren )
    {
	nextToken(); // consume '('
	nextToken(); // consume identifier
	nextToken(); // consume ')'
    }
    else
	nextToken(); // consume identifier
    return total;
}

TokenDataType *Program::parse_typeof_datatype(TokenBase *op_tb)
{
    if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	Throw(op_tb) << "Expecting '(' after typeof" << flush;
    nextToken();

    TokenBase *type_tb = nextToken();
    if ( !type_tb )
	Throw(op_tb) << "Unexpected end of input in typeof" << flush;

    DataDef *dd = NULL;
    bool closed_paren = false;
    if ( type_tb->type() == TokenType::ttDataType )
	dd = &((TokenDataType *)type_tb)->definition;
    else if ( type_tb->type() == TokenType::ttKeyword && type_tb->id() == TokenID::tkSTRUCT )
    {
	TokenBase *tag_tb = nextToken();
	if ( tag_tb && tag_tb->type() == TokenType::ttIdentifier )
	    dd = resolve_named_datadef(((TokenIdent *)tag_tb)->spelling());
	if ( !dd )
	    Throw(tag_tb) << "Unknown struct type in typeof" << flush;
    }
    else if ( type_tb->type() == TokenType::ttIdentifier )
    {
	std::string tname = ((TokenIdent *)type_tb)->spelling();
	dd = resolve_named_datadef(tname);
	if ( !dd )
	{
	    TokenBase *expr = parseExpression(type_tb, true, false, true, 1);
	    if ( peekToken() && peekToken()->id() == TokenID::tkClBrk )
		nextToken();
	    else if ( (!curToken() || curToken()->id() != TokenID::tkClBrk)
		   && (!prevToken() || prevToken()->id() != TokenID::tkClBrk) )
		Throw(type_tb) << "Expecting ')' after typeof expression" << flush;
	    dd = expr ? expr->datadef() : NULL;
	    closed_paren = true;
	}
    }
    else
    {
	TokenBase *expr = parseExpression(type_tb, true, false, true, 1);
	if ( peekToken() && peekToken()->id() == TokenID::tkClBrk )
	    nextToken();
	else if ( (!curToken() || curToken()->id() != TokenID::tkClBrk)
	       && (!prevToken() || prevToken()->id() != TokenID::tkClBrk) )
	    Throw(type_tb) << "Expecting ')' after typeof expression" << flush;
	dd = expr ? expr->datadef() : NULL;
	closed_paren = true;
    }

    while ( !closed_paren && dd && peekToken() && peekToken()->id() == TokenID::tkMul )
    {
	nextToken();
	dd = getPointerType(dd);
    }
    if ( !closed_paren && (!peekToken() || peekToken()->id() != TokenID::tkClBrk) )
	Throw(type_tb) << "Expecting ')' after typeof" << flush;
    if ( !closed_paren )
	nextToken();

    if ( !dd )
	Throw(type_tb) << "typeof: cannot determine operand type" << flush;

    return new TokenDataType(dd->name.c_str(), *dd);
}

bool Program::parsing_template_instantiated_member_body()
{
    if ( instantiating_canonical_spelling.empty()
      || compounds.empty() || !compounds.top()
      || !compounds.top()->method )
	return false;
    return compounds.top()->method->owner_class != NULL;
}

void Program::consume_deferred_static_assert_statement(TokenBase *tb)
{
    if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	Throw(tb) << "Expecting '(' after " << ((TokenIdent *)tb)->spelling() << flush;
    nextToken();

    int depth = 1;
    while ( depth > 0 )
    {
	TokenBase *t = nextToken();
	if ( !t )
	    Throw(tb) << "Unexpected end of input in static assertion" << flush;
	if ( t->id() == TokenID::tkOpBrk )
	    ++depth;
	else if ( t->id() == TokenID::tkClBrk )
	    --depth;
    }
    if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
	nextToken();
}

TokenBase *Program::parse_static_assert_statement(TokenBase *tb)
{
    if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	Throw(tb) << "Expecting '(' after " << ((TokenIdent *)tb)->spelling() << flush;

    if ( parsing_template_instantiated_member_body()
      || fn_template_instantiation_depth > 0 )
    {
	consume_deferred_static_assert_statement(tb);
	return NULL;
    }

    nextToken();

    int64_t cond = parse_constant_integer_expression();
    std::string message = "static assertion failed";
    if ( peekToken() && peekToken()->id() == TokenID::tkComma )
    {
	nextToken();
	TokenBase *msg_tb = nextToken();
	if ( !msg_tb || msg_tb->type() != TokenType::ttString )
	    Throw(msg_tb ? msg_tb : tb) << "Expecting string literal in static assertion" << flush;
	message = ((TokenStr *)msg_tb)->str;
    }

    if ( !peekToken() || peekToken()->id() != TokenID::tkClBrk )
	Throw(tb) << "Expecting ')' after static assertion" << flush;
    nextToken();
    if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
	nextToken();

    if ( !cond )
	Throw(tb) << message << flush;
    return NULL;
}

void Program::consume_class_static_assert_declaration(TokenBase *tb)
{
    if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	Throw(tb) << "Expecting '(' after " << contextual_identifier_name(tb) << flush;
    nextToken(); // consume '('

    TokenBase *first_expr = NULL;
    size_t top_expr_tokens = 0;
    bool before_message = true;
    std::string message = "static assertion failed";
    int depth = 1;
    while ( depth > 0 )
    {
	TokenBase *t = nextToken();
	if ( !t )
	    Throw(tb) << "Unexpected end of input in static assertion" << flush;

	if ( depth == 1 && before_message )
	{
	    if ( t->id() == TokenID::tkComma )
	    {
		before_message = false;
		continue;
	    }
	    if ( t->id() != TokenID::tkClBrk )
	    {
		if ( !first_expr )
		    first_expr = t;
		++top_expr_tokens;
	    }
	}
	else if ( depth == 1 && !before_message && t->type() == TokenType::ttString )
	    message = ((TokenStr *)t)->str;

	if ( t->id() == TokenID::tkOpBrk )
	    ++depth;
	else if ( t->id() == TokenID::tkClBrk )
	    --depth;
    }
    if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
	nextToken();

    bool simple_false = false;
    if ( top_expr_tokens == 1 && first_expr )
    {
	if ( first_expr->type() == TokenType::ttInteger )
	    simple_false = static_cast<TokenInt *>(first_expr)->ival() == 0;
	else if ( is_contextual_identifier_token(first_expr) )
	{
	    bool value = true;
	    if ( is_bool_literal_identifier(contextual_identifier_name(first_expr),
		    value) )
		simple_false = !value;
	}
    }
    if ( simple_false )
	Throw(tb) << message << flush;
}

bool Program::try_parse_constant_offsetof_address(int64_t &out)
{
    auto saved_tokens = tokens.savepos();
    size_t saved_diag_count = diagnostics.size();
    Program::ErrorInfo saved_error = last_error;

    auto fail = [&]() -> bool {
	tokens = saved_tokens;
	diagnostics.resize(saved_diag_count);
	last_error = saved_error;
	return false;
    };

    TokenBase *open_outer = nextToken();
    TokenBase *open_cast = nextToken();
    if ( !open_outer || open_outer->id() != TokenID::tkOpBrk
      || !open_cast || open_cast->id() != TokenID::tkOpBrk )
	return fail();

    DataDef *base_dd = NULL;
    TokenBase *type_tb = nextToken();
    if ( !type_tb )
	return fail();
    if ( type_tb->type() == TokenType::ttKeyword
      && (type_tb->id() == TokenID::tkSTRUCT || type_tb->id() == TokenID::tkUNION) )
    {
	TokenBase *tag_tb = nextToken();
	if ( !tag_tb || !is_contextual_identifier_token(tag_tb) )
	    return fail();
	base_dd = resolve_named_datadef(contextual_identifier_name(tag_tb));
    }
    else if ( type_tb->type() == TokenType::ttDataType )
	base_dd = &static_cast<TokenDataType *>(type_tb)->definition;
    else if ( is_contextual_identifier_token(type_tb) )
	base_dd = resolve_named_datadef(contextual_identifier_name(type_tb));
    if ( !base_dd )
	return fail();

    while ( peekToken() && peekToken()->id() != TokenID::tkClBrk )
	nextToken();
    TokenBase *close_cast = nextToken();
    if ( !close_cast || close_cast->id() != TokenID::tkClBrk )
	return fail();

    TokenBase *zero_tb = nextToken();
    madc_wide_int zero_value = 0;
    if ( !resolve_integer_constant(zero_tb, zero_value) || zero_value != 0 )
	return fail();
    TokenBase *close_outer = nextToken();
    if ( !close_outer || close_outer->id() != TokenID::tkClBrk )
	return fail();

    TokenBase *access = nextToken();
    if ( !access || (access->id() != TokenID::tkDeRef && access->id() != TokenID::tkDot) )
	return fail();

    int64_t offset = 0;
    DataDef *current = base_dd;
    while ( true )
    {
	if ( DataDefPTR *pdd = dynamic_cast<DataDefPTR *>(current) )
	    current = pdd->base_type;
	DataDefSTRUCT *sdd = dynamic_cast<DataDefSTRUCT *>(current);
	if ( !sdd )
	    return fail();

	TokenBase *member_tb = nextToken();
	if ( !member_tb || !is_contextual_identifier_token(member_tb) )
	    return fail();
	std::string member_name = contextual_identifier_name(member_tb);
	ssize_t member_offset = sdd->m_offset(member_name);
	if ( member_offset < 0 )
	    return fail();
	offset += member_offset;
	current = sdd->m_type(member_name);
	if ( !current )
	    return fail();

	while ( peekToken() && peekToken()->id() == TokenID::tkOpSqr )
	{
	    nextToken();
	    int64_t index = parse_constant_integer_expression();
	    TokenBase *close_sq = nextToken();
	    if ( !close_sq || close_sq->id() != TokenID::tkClSqr )
		return fail();
	    size_t elem_size = current->size ? current->size : 1;
	    offset += index * (int64_t)elem_size;
	}

	if ( peekToken()
	  && (peekToken()->id() == TokenID::tkDeRef || peekToken()->id() == TokenID::tkDot) )
	{
	    nextToken();
	    continue;
	}
	break;
    }

    out = offset;
    return true;
}

// Fold a qualified name that resolves to a class-scoped integral constant
// (a static-const data member or an enumerator) in CONSTANT context:
// `Class::member`, `Outer::Inner::member`, `ns::Class::member`,
// `ns::Tmpl<...>::member`. Reuses instantiate_template_id (for template-id
// segments) and resolve_class_static_member_const_value (for the final member).
// `first` is the already-consumed leading token (a type or a namespace name).
// Consumes the `::`-chain on success; returns false (without guaranteeing the
// stream position) only when the leading token can't begin such a chain — the
// callers below gate on that so non-qualified atoms are untouched.
bool Program::fold_constant_qualified_member(TokenBase *first, madc_wide_int &out)
{
    if ( !first )
	return false;
    DataDefCLASS *scope = NULL;
    std::string pending_ns;            // set while positioned right after a namespace name
    if ( first->type() == TokenType::ttDataType )
	scope = dynamic_cast<DataDefCLASS *>(&((TokenDataType *)first)->definition);
    else if ( is_contextual_identifier_token(first) )
    {
	// In the raw constant-expression token stream a type name is still a
	// bare identifier (not yet resolved to ttDataType).
	std::string nm = contextual_identifier_name(first);
	// Template-id leading segment `Name<...>::...`: instantiate to a scope.
	if ( peekToken() && peekToken()->id() == TokenID::tkLT
	  && (template_map.count(nm) || template_alias_map.count(nm)) )
	{
	    // Fold a trait's `::value` (e.g. `__and_<__has_construct<...>>::value`):
	    // let the variadic trait template really instantiate so its `::value`
	    // member is concrete. The cycle that once made this unsafe is gone now
	    // that the inner trait (`__has_construct`) folds to a true_type leaf.
	    bool saved_vri = allow_variadic_real_inst;
	    allow_variadic_real_inst = true;
	    TokenDataType *inst = instantiate_template_id(nm, first);
	    allow_variadic_real_inst = saved_vri;
	    if ( inst )
		scope = dynamic_cast<DataDefCLASS *>(&inst->definition);
	}
	if ( !scope )
	{
	    flat_datatype_map_iter di = datatype_map.find(nm);
	    if ( di != datatype_map.end() )
		scope = dynamic_cast<DataDefCLASS *>(&(*di)->definition);
	}
	if ( !scope && (namespace_map.count(nm) || namespace_datatype_map.count(nm)) )
	    pending_ns = nm;
	if ( !scope && pending_ns.empty() )
	    return false;
    }
    else
	return false;
    if ( !scope && pending_ns.empty() )
	return false;
    // `Trait<...>{}` / `Trait{}` (or `()`) value-init in a constant expression is
    // the std::integral_constant conversion to its `value` — `static_assert(
    // is_same<int,int>{})`, `__is_invocable<...>{}`, `true_type{}`. Fold to the
    // scope's (possibly inherited) static `value` member, the same constant the
    // `::value` form reads. Only EMPTY `{}`/`()` (value-init); a braced
    // initializer with contents is not a constant trait.
    if ( scope && tokens.size() >= 2 && tokens[0] && tokens[1]
      && (tokens[0]->id() == TokenID::tkOpBrc
       || tokens[0]->id() == TokenID::tkOpBrk) )
    {
	TokenID close = tokens[0]->id() == TokenID::tkOpBrc
		      ? TokenID::tkClBrc : TokenID::tkClBrk;
	int64_t v = 0;
	if ( tokens[1]->id() == close
	  && resolve_class_static_member_const_value(scope, "value", v) )
	{
	    nextToken();   // consume the opening { or (
	    nextToken();   // consume the closing } or )
	    out = v;
	    return true;
	}
    }
    if ( !peekToken() || peekToken()->id() != TokenID::tkNS )
	return false;

    while ( peekToken() && peekToken()->id() == TokenID::tkNS )
    {
	nextToken(); // consume '::'
	TokenBase *seg = nextToken();
	if ( !seg )
	    return false;
	std::string seg_name;
	if ( seg->type() == TokenType::ttDataType )
	    seg_name = ((TokenDataType *)seg)->spelling();
	else if ( is_contextual_identifier_token(seg) )
	    seg_name = contextual_identifier_name(seg);
	else
	    return false;

	// template-id segment `Name<...>` — instantiate (in pending_ns if set).
	DataDefCLASS *seg_scope = NULL;
	if ( peekToken() && peekToken()->id() == TokenID::tkLT )
	{
	    bool saved_vri = allow_variadic_real_inst;
	    allow_variadic_real_inst = true;
	    TokenDataType *inst =
		    instantiate_template_id(seg_name, seg, pending_ns,
					    pending_ns.empty() ? scope : NULL);
	    allow_variadic_real_inst = saved_vri;
	    if ( inst )
		seg_scope = dynamic_cast<DataDefCLASS *>(&inst->definition);
	}

	bool more = peekToken() && peekToken()->id() == TokenID::tkNS;
	if ( more )
	{
	    // Intermediate segment: must name a class to descend into.
	    if ( !seg_scope )
	    {
		if ( !pending_ns.empty() )
		{
		    namespace_datatype_map_t::iterator ni =
			namespace_datatype_map.find(pending_ns);
		    if ( ni != namespace_datatype_map.end() )
		    {
			datatype_map_iter di = ni->find(seg_name);
			if ( di != ni->end() )
			    seg_scope = dynamic_cast<DataDefCLASS *>(
				&di->second->definition);
		    }
		}
		else if ( scope )
		    seg_scope = dynamic_cast<DataDefCLASS *>(
			resolve_class_type_alias(scope, seg_name));
	    }
	    if ( !seg_scope )
		return false;
	    scope = seg_scope;
	    pending_ns.clear();
	    continue;
	}

	// Final segment: a member of the current class scope.
	if ( seg_scope || !scope )
	    return false;            // a type, or no scope to look in
	// The static-member capture map stores int64 (wide static-const
	// members are out of the slice-3 fold's scope); widen on the way out.
	int64_t member_val = 0;
	if ( !resolve_class_static_member_const_value(scope, seg_name, member_val) )
	    return false;
	out = member_val;
	return true;
    }
    return false;
}

madc_wide_int Program::parse_constant_primary()
{
    TokenBase *tb = nextToken();
    madc_wide_int out = 0;

    if ( resolve_integer_constant(tb, out) )
	return out;
    // Qualified class-scoped integral constant: `Class::member`,
    // `ns::Tmpl<...>::member`, etc. Folds to the captured value; gated on the
    // leading token beginning such a chain, so plain atoms fall through.
    if ( fold_constant_qualified_member(tb, out) )
	return out;
    if ( try_parse_constant_functional_cast(tb, out) )
	return out;
    if ( tb && is_contextual_identifier_token(tb) )
    {
	std::string name = contextual_identifier_name(tb);
	bool bool_value = false;
	if ( is_bool_literal_identifier(name, bool_value) )
	    return bool_value ? 1 : 0;
	if ( name == "sizeof" || is_alignof_identifier(name) )
	    return (madc_wide_int)evaluate_type_query(tb, name);
	// Type-trait builtins in constant context — the std::integral_constant
	// initializer shape `static const bool value = __is_class(T);` and non-type
	// template args. Args are concrete (madc monomorphizes); fold to 0/1.
	if ( is_type_trait_builtin(name) )
	{
	    TokenBase *r = evaluate_type_trait(tb, name);
	    return static_cast<TokenInt *>(r)->ival();
	}
	// Unqualified sibling static-const member inside the class body,
	// e.g. `static const category all = (ctype | numeric);`. Resolves
	// to the value captured by capture_constant_initializer_value.
	// Falls through to the throw below for any non-member identifier,
	// so non-class constant contexts are unaffected.
	int64_t member_val = 0;
	if ( resolve_current_class_static_member_const_value(name, member_val) )
	    return member_val;
	if ( is_nullptr_identifier(name) )
	    return 0;
	if ( is_named_cpp_cast(name) )
	    return parse_constant_named_cpp_cast(tb, name);
	// C++20 requires-EXPRESSION as a constraint atom (e.g. inside a concept's
	// constraint `... && requires(_Iter __i) { ++__i; }`). `requires` is already
	// consumed (it is `tb`); evaluate the requirement-seq's well-formedness.
	if ( name == "requires" )
	    return evaluate_requires_expression_constant();
	// C++14 VARIABLE TEMPLATE in a constant expression: `is_floating_point_v
	// <double>` (a non-type bool arg — e.g. enable_if's condition in
	// std::numbers). Substitute the type args into the initializer tokens and
	// fold them recursively in an isolated stream: the init
	// `is_floating_point<_Tp>::value` becomes `is_floating_point<double>::value`,
	// which folds via the normal trait `::value` path. (The parseExpression
	// use-site resolution does not cover this constant-context path.)
	if ( peekToken() && peekToken()->id() == TokenID::tkLT )
	{
	    VarTemplateDef *vti =
		var_template_map.find(name);
	    if ( vti == var_template_map.end() && !current_namespace().empty() )
		vti = var_template_map.find(current_namespace() + "::" + name);
	    if ( vti != var_template_map.end() && !vti->init.empty() )
	    {
		std::vector<DataDef *> targs = capture_call_template_args();
		std::vector<TokenBase *> sub =
		    substitute_var_template_init(*vti, targs);
		if ( !sub.empty() )
		{
		    sub.push_back(new TokenSemi());
		    TokenStream::State saved = tokens.swap_in(std::move(sub));
		    madc_wide_int v = 0;
		    try { v = parse_constant_integer_expression(); }
		    catch ( ... ) { tokens.swap_back(std::move(saved)); throw; }
		    tokens.swap_back(std::move(saved));
		    return v;
		}
	    }
	}
	// C++20 CONCEPT used as a non-type bool in a constant expression — e.g.
	// `__conditional_t<random_access_iterator<It>, ...>`'s condition, or a
	// `static_assert(Concept<T>)`. Substitute the type args into the stored
	// constraint and fold it recursively in an ISOLATED stream → 0/1. Nested
	// concept-ids recurse back into this same arm; trait-based atoms
	// (`derived_from`→`__is_base_of`, `same_as`→`__is_same`, plain type-trait
	// builtins) fold via the existing primary paths; `&&`/`||` short-circuit
	// (parse_constant_land/lor) and `requires`-expressions evaluate via the
	// requires arm below. Same shape as the C++14 variable-template arm above.
	if ( peekToken() && peekToken()->id() == TokenID::tkLT )
	{
	    std::map<std::string, ConceptDef>::iterator cit =
		concept_map.find(name);
	    if ( cit == concept_map.end() && !current_namespace().empty() )
		cit = concept_map.find(current_namespace() + "::" + name);
	    if ( cit != concept_map.end() && !cit->second.constraint.empty() )
	    {
		std::vector<DataDef *> targs = capture_call_template_args();
		std::map<std::string, TokenDataType *> subst;
		for ( size_t i = 0; i < cit->second.typeparams.size()
				&& i < targs.size(); ++i )
		    if ( targs[i] )
			subst[cit->second.typeparams[i]] =
			    new TokenDataType(targs[i]->name.c_str(), *targs[i]);
		std::vector<TokenBase *> sub =
		    clone_template_tokens_with_type_subst(cit->second.constraint,
							  subst);
		if ( !sub.empty() )
		{
		    sub.push_back(new TokenSemi());
		    TokenStream::State saved = tokens.swap_in(std::move(sub));
		    madc_wide_int v = 0;
		    try { v = parse_constant_integer_expression(); }
		    catch ( ... ) { tokens.swap_back(std::move(saved)); throw; }
		    tokens.swap_back(std::move(saved));
		    return v ? 1 : 0;
		}
	    }
	}
    }
    if ( tb && tb->id() == TokenID::tkNeg )
	return -parse_constant_primary();
    if ( tb && tb->id() == TokenID::tkAdd )
	return parse_constant_primary();
    if ( tb && tb->id() == TokenID::tkLnot )
	return !parse_constant_primary();
    if ( tb && tb->id() == TokenID::tkBnot )
	return ~parse_constant_primary();
    if ( tb && tb->id() == TokenID::tkBand )
    {
	// offsetof-style addresses are 64-bit; widen on the way out.
	int64_t addr = 0;
	if ( try_parse_constant_offsetof_address(addr) )
	    return addr;
	Throw(tb) << "Unsupported address expression in constant expression" << flush;
    }
    if ( tb && tb->id() == TokenID::tkOpBrk )
    {
	// Check for cast: (type)value — e.g. (char)SB, (unsigned char)~0
	TokenBase *inner = peekToken();
	if ( inner && (inner->type() == TokenType::ttDataType
	  || inner->id() == TokenID::tkCONST
	  || inner->id() == TokenID::tkRESTRICT) )
	{
	    // Extract the cast target type for truncation
	    DataDef *cast_dd = NULL;
	    bool is_unsigned = false;
	    while ( peekToken()
	         && peekToken()->id() != TokenID::tkClBrk )
	    {
		TokenBase *ct = nextToken();
		if ( ct->type() == TokenType::ttDataType )
		    cast_dd = &((TokenDataType *)ct)->definition;
		if ( ct->type() == TokenType::ttIdentifier )
		{
		    std::string tname = ((TokenIdent *)ct)->spelling();
		    if ( tname == "unsigned" ) is_unsigned = true;
		}
	    }
	    if ( peekToken() )
		nextToken(); // consume ')'
	    madc_wide_int val = parse_constant_primary();
	    return apply_integer_cast_value(cast_dd, val, is_unsigned);
	}
	out = parse_constant_integer_expression();
	tb = nextToken();
	if ( !tb || tb->id() != TokenID::tkClBrk )
	    Throw(tb) << "Expecting ')' in constant expression" << flush;
	return out;
    }
    Throw(tb) << "Expecting integer constant expression" << flush;
    return 0;
}

madc_wide_int Program::parse_constant_mul()
{
    madc_wide_int lhs = parse_constant_primary();

    while ( peekToken() )
    {
	TokenBase *op = peekToken();
	if ( op->id() != TokenID::tkMul && op->id() != TokenID::tkDiv && op->id() != TokenID::tkMod )
	    break;
	nextToken(); // consume operator
	madc_wide_int rhs = parse_constant_primary();
	if ( op->id() == TokenID::tkMul ) lhs *= rhs;
	else if ( op->id() == TokenID::tkDiv )
	{
	    if ( rhs == 0 )
		Throw(op) << "Division by zero in constant expression" << flush;
	    lhs /= rhs;
	}
	else
	{
	    if ( rhs == 0 )
		Throw(op) << "Modulo by zero in constant expression" << flush;
	    lhs %= rhs;
	}
    }

    return lhs;
}

// additive: parse_constant_mul ([+-] parse_constant_mul)*
madc_wide_int Program::parse_constant_add()
{
    madc_wide_int lhs = parse_constant_mul();

    while ( peekToken() )
    {
	TokenBase *op = peekToken();
	if ( op->id() != TokenID::tkAdd && op->id() != TokenID::tkSub && op->id() != TokenID::tkNeg )
	    break;
	nextToken(); // consume operator
	madc_wide_int rhs = parse_constant_mul();
	if ( op->id() == TokenID::tkAdd ) lhs += rhs;
	else lhs -= rhs;
    }

    return lhs;
}

// shift: parse_constant_add ([<<>>] parse_constant_add)*
madc_wide_int Program::parse_constant_shift()
{
    madc_wide_int lhs = parse_constant_add();

    while ( peekToken() )
    {
	TokenBase *op = peekToken();
	if ( op->id() != TokenID::tkBSL && op->id() != TokenID::tkBSR )
	    break;
	nextToken();
	madc_wide_int rhs = parse_constant_add();
	if ( op->id() == TokenID::tkBSL ) lhs <<= rhs;
	else                              lhs >>= rhs;
    }

    return lhs;
}

// bitwise-and / xor / or: same precedence order as C.
madc_wide_int Program::parse_constant_band()
{
    madc_wide_int lhs = parse_constant_eq();
    while ( peekToken() && peekToken()->id() == TokenID::tkBand )
    {
	nextToken();
	lhs &= parse_constant_eq();
    }
    return lhs;
}

madc_wide_int Program::parse_constant_bxor()
{
    madc_wide_int lhs = parse_constant_band();
    while ( peekToken() && peekToken()->id() == TokenID::tkXor )
    {
	nextToken();
	lhs ^= parse_constant_band();
    }
    return lhs;
}

madc_wide_int Program::parse_constant_bor()
{
    madc_wide_int lhs = parse_constant_bxor();
    while ( peekToken() && peekToken()->id() == TokenID::tkBor )
    {
	nextToken();
	lhs |= parse_constant_bxor();
    }
    return lhs;
}

madc_wide_int Program::parse_constant_rel()
{
    madc_wide_int lhs = parse_constant_shift();
    while ( peekToken() )
    {
	TokenBase *op = peekToken();
	if ( op->id() != TokenID::tkLT && op->id() != TokenID::tkGT
	  && op->id() != TokenID::tkLE && op->id() != TokenID::tkGE )
	    break;
	nextToken();
	madc_wide_int rhs = parse_constant_shift();
	switch ( op->id() )
	{
	    case TokenID::tkLT: lhs = lhs < rhs; break;
	    case TokenID::tkGT: lhs = lhs > rhs; break;
	    case TokenID::tkLE: lhs = lhs <= rhs; break;
	    default:            lhs = lhs >= rhs; break;
	}
    }
    return lhs;
}

madc_wide_int Program::parse_constant_eq()
{
    madc_wide_int lhs = parse_constant_rel();
    while ( peekToken() )
    {
	TokenBase *op = peekToken();
	if ( op->id() != TokenID::tkEquals && op->id() != TokenID::tkNotEq )
	    break;
	nextToken();
	madc_wide_int rhs = parse_constant_rel();
	lhs = (op->id() == TokenID::tkEquals) ? (lhs == rhs) : (lhs != rhs);
    }
    return lhs;
}

// Consume (without evaluating) one RHS operand of a `&&`/`||` whose value the
// LHS already short-circuits. A token-consuming recursive-descent evaluator MUST
// still advance past the operand (so the caller lands on the next operator /
// sentinel), but C++ [expr.const] does NOT require a short-circuited operand to
// be a constant expression — so `false && <runtime-call>` folds to false instead
// of throwing. (Previously `lhs = lhs && parse_constant_bor()` relied on C++'s
// own short-circuit, which SKIPPED the call and left the RHS tokens unconsumed,
// so a non-type template arg like `__can_memmove && __assignable` never reached
// its `;` sentinel and the whole fold failed.)
void Program::skip_const_logical_operand(bool stop_at_and)
{
    int depth = 0;
    while ( TokenBase *t = peekToken() )
    {
	TokenID id = (TokenID)t->id();
	if ( depth == 0 )
	{
	    if ( id == TokenID::tkSemi || id == TokenID::tkComma
	      || id == TokenID::tkClBrk || id == TokenID::tkClSqr
	      || id == TokenID::tkClBrc || id == TokenID::tkQmark
	      || id == TokenID::tkColon || id == TokenID::tkLor )
		return;
	    if ( stop_at_and && id == TokenID::tkLand )
		return;
	}
	if ( id == TokenID::tkOpBrk || id == TokenID::tkOpSqr
	  || id == TokenID::tkOpBrc )
	    ++depth;
	else if ( id == TokenID::tkClBrk || id == TokenID::tkClSqr
	       || id == TokenID::tkClBrc )
	{ if ( depth > 0 ) --depth; }
	nextToken();
    }
}

madc_wide_int Program::parse_constant_land()
{
    madc_wide_int lhs = parse_constant_bor();
    while ( peekToken() && peekToken()->id() == TokenID::tkLand )
    {
	nextToken();
	if ( !lhs )
	{
	    skip_const_logical_operand(true);   // short-circuit: 0 && X == 0
	    continue;
	}
	lhs = parse_constant_bor() ? 1 : 0;
    }
    return lhs;
}

madc_wide_int Program::parse_constant_lor()
{
    madc_wide_int lhs = parse_constant_land();
    while ( peekToken() && peekToken()->id() == TokenID::tkLor )
    {
	nextToken();
	if ( lhs )
	{
	    skip_const_logical_operand(false);  // short-circuit: 1 || X == 1
	    lhs = 1;
	    continue;
	}
	lhs = parse_constant_land() ? 1 : 0;
    }
    return lhs;
}

madc_wide_int Program::parse_constant_ternary()
{
    madc_wide_int cond = parse_constant_lor();
    if ( peekToken() && peekToken()->id() == TokenID::tkQmark )
    {
	nextToken(); // consume '?'
	madc_wide_int true_val = parse_constant_integer_expression();
	TokenBase *colon = nextToken();
	if ( !colon || colon->id() != TokenID::tkColon )
	    Throw(colon) << "Expecting ':' in ternary constant expression" << flush;
	madc_wide_int false_val = parse_constant_ternary();
	return cond ? true_val : false_val;
    }
    return cond;
}

madc_wide_int Program::parse_constant_integer_expression()
{
    return parse_constant_ternary();
}

// Materialize a folded constant value as a TokenInt (see madc.h). Historical
// typing preserved exactly for int64-range values; a >64-bit value keeps its
// low 64 bits on the token, parks the full value in valpool (wide_handle),
// and is typed ddINT128/ddUINT128 so wival()/emission see it as semantically
// wide (gcc types such fold results __int128/unsigned __int128).
TokenInt *Program::make_folded_integer_token(madc_wide_int v)
{
    int64_t lo = (int64_t)v;
    TokenInt *tok = new TokenInt(lo);
    if ( (madc_wide_int)lo == v )
    {
	// Fits 64 bits: widen the token's TYPE past default int only when the
	// value exceeds 32-bit range (the pre-slice-3 case-label behavior).
	uint64_t uval = (uint64_t)lo;
	if ( uval > 0x7FFFFFFF )
	    tok->setDataType(lo < 0 ? (DataDef *)&ddINT64 : (DataDef *)&ddUINT64);
	return tok;
    }
    tok->wide_handle = valpool.put_u128((uint64_t)(madc_wide_uint)v,
					(uint64_t)((madc_wide_uint)v >> 64));
    tok->setDataType(v < 0 ? (DataDef *)&ddINT128 : (DataDef *)&ddUINT128);
    return tok;
}

// A streambuf that silently swallows output. The speculative constant-folds below
// (fold_if_constexpr_condition / fold_nontype_arg_constant) mute std::cerr so a
// non-constant arg's caught Throw doesn't leak a diagnostic. Muting via
// rdbuf(NULL) is FRAGILE: a NULL rdbuf makes every insertion set badbit, and a
// write that reaches the throwstream's exceptions(badbit) during the nested
// instantiation the fold triggers throws basic_ios::clear — which ABORTS that
// (legitimate) instantiation instead of merely suppressing a message, and corrupts
// the real error into a spurious "iostream error". A real swallowing buffer keeps
// the stream good, so only the intended suppression happens.
namespace { struct MadcNullStreambuf : std::streambuf {
    int overflow(int c) override { return c; }   // accept and discard
}; MadcNullStreambuf g_madc_null_streambuf; }

bool Program::fold_if_constexpr_condition(int64_t &out)
{
    // Collect the balanced condition tokens (stream is just past the opening `(`),
    // consuming the matching `)`. Keep them so a non-constant condition can be
    // pushed back for the runtime-`if` fallback.
    std::vector<TokenBase *> cond_toks;
    int depth = 1;
    TokenBase *t;
    while ( depth > 0 && (t = nextToken()) )
    {
	if ( t->id() == TokenID::tkOpBrk )
	    ++depth;
	else if ( t->id() == TokenID::tkClBrk )
	{
	    if ( --depth == 0 )
		break;                 // the matching ')' — consumed, not collected
	}
	cond_toks.push_back(t);
    }
    if ( depth != 0 )
    {
	// Unbalanced — push back what we took and bail to the runtime path.
	for ( std::vector<TokenBase *>::reverse_iterator it = cond_toks.rbegin();
	      it != cond_toks.rend(); ++it )
	    pushToken(*it);
	return false;
    }

    // Fold a CLONE in an isolated stream (same idiom as fold_nontype_arg_constant:
    // muted std::cerr, since a non-constant condition Throws and throwbuf::sync
    // prints before the exception we catch).
    size_t saved_diag_count = diagnostics.size();
    Program::ErrorInfo saved_error = last_error;
    std::vector<TokenBase *> body;
    for ( TokenBase *ct : cond_toks )
	body.push_back(ct->clone());
    body.push_back(new TokenSemi());
    TokenStream::State saved_tokens = tokens.swap_in(std::move(body));
    std::streambuf *saved_cerr = std::cerr.rdbuf();
    std::ios::iostate saved_cerr_state = std::cerr.rdstate();
    std::cerr.rdbuf(&g_madc_null_streambuf);
    bool ok = false;
    try
    {
	madc_wide_int v = parse_constant_integer_expression();
	if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
	{
	    // The condition is contextually bool; normalize a wide fold so a
	    // value whose LOW 64 bits are zero (e.g. (__int128)1 << 100) stays
	    // truthy through the int64 out-param.
	    out = ((int64_t)v != 0) ? (int64_t)v : (v != 0 ? 1 : 0);
	    ok = true;
	}
    }
    catch ( ... ) { ok = false; }
    std::cerr.rdbuf(saved_cerr);
    std::cerr.clear(saved_cerr_state);
    tokens = saved_tokens;
    if ( !ok )
    {
	diagnostics.resize(saved_diag_count);
	last_error = saved_error;
	// Restore the live stream: condition tokens followed by the ')'.
	pushToken(new TokenClBrk());
	for ( std::vector<TokenBase *>::reverse_iterator it = cond_toks.rbegin();
	      it != cond_toks.rend(); ++it )
	    pushToken(*it);
    }
    return ok;
}

void Program::skip_discarded_statement()
{
    TokenBase *p = peekToken();
    if ( !p )
	return;
    if ( p->id() == TokenID::tkOpBrc )
    {
	nextToken();                       // consume '{'
	int depth = 1;
	TokenBase *t;
	while ( depth > 0 && (t = nextToken()) )
	{
	    if ( t->id() == TokenID::tkOpBrc ) ++depth;
	    else if ( t->id() == TokenID::tkClBrc ) --depth;
	}
	return;
    }
    // A single (non-block) statement: consume through its terminating ';' at
    // bracket/brace/paren depth 0.
    int pd = 0, bd = 0, sd = 0;
    TokenBase *t;
    while ( (t = peekToken()) )
    {
	TokenID id = t->id();
	if ( id == TokenID::tkSemi && pd == 0 && bd == 0 && sd == 0 )
	{ nextToken(); break; }
	nextToken();
	if ( id == TokenID::tkOpBrk ) ++pd;
	else if ( id == TokenID::tkClBrk && pd > 0 ) --pd;
	else if ( id == TokenID::tkOpBrc ) ++bd;
	else if ( id == TokenID::tkClBrc && bd > 0 ) --bd;
	else if ( id == TokenID::tkOpSqr ) ++sd;
	else if ( id == TokenID::tkClSqr && sd > 0 ) --sd;
    }
}

static bool constant_initializer_has_runtime_access(Program &pgm)
{
    int paren_depth = 0;
    int square_depth = 0;
    int brace_depth = 0;
    for ( size_t i = 0; i < pgm.tokens.size(); ++i )
    {
	TokenBase *t = pgm.tokens[i];
	if ( !t )
	    continue;
	if ( t->id() == TokenID::tkSemi
	  && paren_depth == 0 && square_depth == 0 && brace_depth == 0 )
	    break;
	if ( t->id() == TokenID::tkOpBrk )
	    ++paren_depth;
	else if ( t->id() == TokenID::tkClBrk && paren_depth > 0 )
	    --paren_depth;
	else if ( t->id() == TokenID::tkOpSqr )
	    ++square_depth;
	else if ( t->id() == TokenID::tkClSqr && square_depth > 0 )
	    --square_depth;
	else if ( t->id() == TokenID::tkOpBrc )
	    ++brace_depth;
	else if ( t->id() == TokenID::tkClBrc && brace_depth > 0 )
	    --brace_depth;
	if ( t->id() == TokenID::tkDot || t->id() == TokenID::tkDeRef )
	    return true;
	if ( !is_contextual_identifier_token(t) )
	    continue;
	TokenBase *next = (i + 1 < pgm.tokens.size()) ? pgm.tokens[i + 1] : NULL;
	if ( next && (next->id() == TokenID::tkDot || next->id() == TokenID::tkDeRef) )
	    return true;
	std::string name = contextual_identifier_name(t);
	bool bool_value = false;
	bool constant_callable = name == "sizeof"
			      || is_alignof_identifier(name)
			      || is_type_trait_builtin(name)
			      || is_bool_literal_identifier(name, bool_value)
			      || is_nullptr_identifier(name);
	if ( next && next->id() == TokenID::tkOpBrk && !constant_callable )
	    return true;
    }
    return false;
}

// Speculatively fold a static-data-member initializer (caller has already consumed
// the '=') to a constant integer, expecting a terminating ';'. On success the
// initializer is CONSUMED (stream left at ';') and the value returned via `out`; on
// any failure the stream/diagnostics are restored and false returned, so the caller
// falls back to skipping a non-constant initializer. Same save/try/restore idiom as
// bracket_dim_constant_expression_parses.
bool Program::capture_constant_initializer_value(int64_t &out)
{
    if ( constant_initializer_has_runtime_access(*this) )
	return false;
    auto saved_tokens = tokens.savepos();
    size_t saved_diag_count = diagnostics.size();
    Program::ErrorInfo saved_error = last_error;
    // A non-constant / still-dependent initializer (a dependent `static constexpr`
    // member like libstdc++'s `value = static_cast<...>(...)`) makes
    // parse_constant_integer_expression Throw, and throwbuf::sync() prints to stderr
    // BEFORE the exception we catch — so this legitimate "skip the non-constant
    // initializer" fallback would leak a spurious error. Mute std::cerr for the
    // speculative parse only; restore + clear its state after. (Same idiom as
    // fold_nontype_arg_constant / constraint_expression_well_formed.)
    std::streambuf *saved_cerr = std::cerr.rdbuf();
    std::ios::iostate saved_cerr_state = std::cerr.rdstate();
    std::cerr.rdbuf(&g_madc_null_streambuf);
    bool ok = false;
    int64_t v = 0;
    try
    {
	v = parse_constant_integer_expression();
	if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
	    ok = true;
    }
    catch ( ... ) { ok = false; }
    std::cerr.rdbuf(saved_cerr);
    std::cerr.clear(saved_cerr_state);
    if ( ok )
    {
	out = v;
	return true;                // keep the consumed position (stream at ';')
    }
    tokens = saved_tokens;
    diagnostics.resize(saved_diag_count);
    last_error = saved_error;
    return false;
}

bool Program::bracket_dim_constant_expression_parses()
{
    auto saved_tokens = tokens.savepos();
    size_t saved_diag_count = diagnostics.size();
    Program::ErrorInfo saved_error = last_error;
    try
    {
	int64_t n = parse_constant_integer_expression();
	TokenBase *cl = nextToken();
	tokens = saved_tokens;
	diagnostics.resize(saved_diag_count);
	last_error = saved_error;
	return n >= 0 && cl && cl->id() == TokenID::tkClSqr;
    }
    catch ( ... )
    {
	tokens = saved_tokens;
	diagnostics.resize(saved_diag_count);
	last_error = saved_error;
	return false;
    }
}

bool Program::bracket_dim_uses_runtime_value(
					   const std::set<std::string> *runtime_names)
{
    int depth = 1;
    for ( size_t ix = 0; ix < tokens.size() && depth > 0; ++ix )
    {
	TokenBase *t = tokens[ix];
	if ( t->id() == TokenID::tkOpSqr ) { ++depth; continue; }
	if ( t->id() == TokenID::tkClSqr ) { --depth; continue; }
	if ( t->id() == TokenID::tkSemi || t->id() == TokenID::tkOpBrc ) break;
	// ++ or -- in a dimension expression is inherently runtime
	if ( t->id() == TokenID::tkInc || t->id() == TokenID::tkDec )
	    return true;
	std::string name;
	if ( t->type() == TokenType::ttIdentifier )
	    name = ((TokenIdent *)t)->spelling();
	else
	    continue;
	if ( runtime_names && runtime_names->count(name) )
	    return true;
	Variable *v = findVariable(name);
	if ( !v )
	    continue;
	if ( v->is_constant() )
	{
	    // A const-qualified var folds to a constant dimension ONLY if its
	    // value is known at compile time. A const with a runtime initializer
	    // (e.g. `const int len = atoi(argv[1]);`) carries no folded value
	    // (`var->data` is NULL) and is therefore still a VLA bound.
	    madc_wide_int cval;
	    if ( read_constant_integer(v, cval) )
		continue;
	    return true;
	}
	return true;
    }
    return false;
}

bool Program::bracket_dim_has_constant_fold_query()
{
    int depth = 1;
    for ( size_t ix = 0; ix < tokens.size() && depth > 0; ++ix )
    {
	TokenBase *t = tokens[ix];
	if ( t->id() == TokenID::tkOpSqr ) { ++depth; continue; }
	if ( t->id() == TokenID::tkClSqr ) { --depth; continue; }
	if ( depth != 1 )
	    continue;
	if ( t->type() != TokenType::ttIdentifier )
	    continue;
	std::string name = ((TokenIdent *)t)->spelling();
	if ( name == "sizeof" || is_alignof_identifier(name) )
	    return true;
    }
    return false;
}

bool Program::bracket_dim_needs_runtime_value(
					    const std::set<std::string> *runtime_names)
{
    if ( !bracket_dim_uses_runtime_value(runtime_names) )
	return false;
    if ( !bracket_dim_has_constant_fold_query() )
	return true;
    return !bracket_dim_constant_expression_parses();
}

DataDef *Program::parse_typedef_array_suffix(DataDef *base_dd,
					   const std::string &alias_name,
					   TokenBase *err_tok)
{
    if ( !base_dd )
	return base_dd;
    if ( !(peekToken() && peekToken()->id() == TokenID::tkOpSqr) )
	return base_dd;

    size_t alias_count = 1;
    TokenBase *alias_count_expr = NULL;
    while ( peekToken() && peekToken()->id() == TokenID::tkOpSqr )
    {
	nextToken(); // consume '['
	TokenBase *cl = nextToken();
	if ( cl && cl->id() == TokenID::tkClSqr )
	{
	    alias_count = 0;
	    continue;
	}
	pushToken(cl);
	if ( !alias_count_expr && bracket_dim_needs_runtime_value() )
	{
	    alias_count_expr = parseExpression(nextToken(), true);
	    cl = nextToken();
	    if ( !cl || cl->id() != TokenID::tkClSqr )
		Throw(cl ? cl : err_tok) << "Expected ] in typedef array declaration" << flush;
	    continue;
	}
	int64_t n = parse_constant_integer_expression();
	if ( n < 0 )
	    Throw(err_tok) << "Typedef array dimension must be non-negative" << flush;
	cl = nextToken();
	if ( !cl || cl->id() != TokenID::tkClSqr )
	    Throw(cl ? cl : err_tok) << "Expected ] in typedef array declaration" << flush;
	if ( n == 0 )
	    alias_count = 0;
	else
	    alias_count *= (size_t)n;
    }
    return new DataDefCArray(*base_dd, alias_name, alias_count, alias_count_expr);
}

